const debug = require('debug')
const logBase = debug('minecraft-pathfinding:InteractHandler')
const logPlace = debug('minecraft-pathfinding:PlaceHandler')
const logBreak = debug('minecraft-pathfinding:BreakHandler')

export type InteractType = 'water' | 'solid' | 'replaceable'

interface InteractionPerformInfo {
  ticks: number
  tickAllowance: number
  shiftTick: number
  raycasts: RayType[]
}

export interface InteractOpts {
  info?: InteractionPerformInfo
  returnToStart?: boolean
  returnToPos?: Vec3
  /** Retained for callers; search terrain predictions never change the live world. */
  predictBlock?: boolean
  noAwait?: boolean
}

/**
 * TODO: Predict time of rotation for looking.
 *
 * Allow looking sooner than the actual block placement.
 */
export abstract class InteractHandler {
  protected performing = false
  public cancelled = false

  protected _equipping = false
  protected _done = false
  protected _internalLock = true
  protected task?: Task<void, Error>

  public readonly blockInfo: BlockInfo

  protected readonly move!: MovementExecutor

  protected get settings (): MovementOptions {
    return this.move.settings
  }

  public get vec (): Vec3 {
    return new Vec3(this.x, this.y, this.z)
  }

  public get bb (): AABB {
    return AABB.fromBlock(this.vec)
  }

  public get equipping (): boolean {
    return this._equipping
  }

  constructor (
    public readonly x: number,
    public readonly y: number,
    public readonly z: number,
    public readonly type: InteractType,
    public readonly offhand = false
  ) {
    this.blockInfo = this.toBlockInfo()
  }

  public get isPerforming (): boolean {
    return this.performing
  }

  public get done (): boolean {
    return this._done
  }

  public get allowExit (): boolean {
    return !this._internalLock
  }

  public loadMove (move: MovementExecutor): void {
    (this as any).move = move
  }

  abstract needToPerform (bot: Bot): boolean

  abstract getItem (bot: Bot, block?: Block): Item | null
  abstract perform (bot: Bot, item: Item | null, opts?: InteractOpts): Promise<void>
  abstract performInfo (bot: Bot, ticks?: number): Promise<InteractionPerformInfo>
  abstract toBlockInfo (): BlockInfo

  abstract abort (bot: Bot): Promise<void>

  public async _abort (bot: Bot): Promise<void> {
    if (this.performing && !this.cancelled) {
      logBase(`Aborting interaction at ${this.vec}`)
      await this.abort(bot)
      this.performing = false
      this.cancelled = true
    }
  }

  public async _perform (bot: Bot, item: Item | null, opts: InteractOpts = {}): Promise<void> {
    if (this.performing) {
      logBase(`Error: Already performing interaction at ${this.vec}`)
      throw new Error('Already performing')
    }

    logBase(`Starting interaction at ${this.vec} (Type: ${this.type}, Offhand: ${this.offhand})`)
    this.performing = true
    this._internalLock = true
    this.task = new Task()
    const revision = bot.pathfinder.navigationRevision

    const ret = await this.perform(bot, item, opts).catch((err) => {
      logBase(`Interaction failed at ${this.vec}: %O`, err)
      this._internalLock = true
      this._done = false
      this.performing = false
      // Inventory, tool, health and task safety failures belong to the owner.
      // Retrying a movement here would hide them behind generic cancellation.
      if (err instanceof NavigationTaskError) throw err
      if (this instanceof PlaceHandler && !this.cancelled && !this.move.aborted && !bot.pathfinder.abortCalculation) {
        bot.pathfinder.rejectPlacement(this.vec, revision)
        throw new NavigationError('placement', `Placement failed at ${this.vec}: ${String(err)}`)
      }
      throw new CancelError(`Failed to perform ${this.constructor.name}`, err)
    })

    logBase(`Successfully completed interaction at ${this.vec}`)
    this._internalLock = false
    this._done = true
    this.performing = false
    return ret
  }

  getCurrentItem (bot: Bot): Item | null {
    if (this.offhand) return bot.inventory.slots[bot.getEquipmentDestSlot('off-hand')]
    return bot.inventory.slots[bot.getEquipmentDestSlot('hand')]
  }

  async equipItem (bot: Bot, item: Item | null): Promise<void> {
    if (this._equipping) return // already equipping item, ignore silently.
    this._equipping = true
    if (item === null) {
      logBase(`Unequipping ${this.offhand ? 'off-hand' : 'hand'}`)
      await bot.unequip(this.offhand ? 'off-hand' : 'hand')
    } else if (this.offhand) {
      logBase(`Equipping ${item.name} to off-hand`)
      await bot.equip(item, 'off-hand')
    } else {
      logBase(`Equipping ${item.name} to hand`)
      await bot.equip(item, 'hand')
    }
    bot.updateHeldItem()
    // await bot.waitForTicks(2)
    this._equipping = false
  }

  async allowExternalInfluence (bot: Bot, ticks = 1, sneak = false): Promise<boolean> {
    if (!this.performing) return true
    if (!this._internalLock) return true

    const res = await this.performInfo(bot, ticks)
    if (res.ticks < Infinity) return true

    const ectx = new ClimbAwarePhysics(bot.registry)
    const state = EPhysicsCtx.FROM_BOT(ectx, bot)

    const flag0 = bot.entity.onGround
    for (let i = 0; i < ticks; i++) {
      ectx.simulate(state, bot.pathfinder.world as any)
    }

    if (flag0) if (state.position.y < bot.entity.position.y) return false

    if (state.state.pos.y < bot.entity.position.y) return false
    return this.bb.distanceToVec(state.state.pos) < PlaceHandler.reach
  }
}

export class PlaceHandler extends InteractHandler {
  static reach = 4
  private _placeTask?: Promise<void>

  static fromVec (vec: Vec3, type: InteractType, offhand = false): PlaceHandler {
    return new PlaceHandler(vec.x, vec.y, vec.z, type, offhand)
  }

  static identTypeFromItem (item: Item): InteractType {
    if (item.name.includes('water')) return 'water'
    return 'solid'
  }

  toBlockInfo (): BlockInfo {
    switch (this.type) {
      case 'solid':
        return BlockInfo.SOLID(this.vec)
      case 'water':
        return BlockInfo.WATER(this.vec)
      case 'replaceable':
        return BlockInfo.REPLACEABLE(this.vec)
      default:
        throw new Error('Invalid type')
    }
  }

  getItem (bot: Bot): Item | null {
    switch (this.type) {
      case 'water': {
        return bot.inventory.items().find((item) => item.name === 'water_bucket') ?? null
      }
      case 'solid': {
        return bot.inventory.items().find((item) => BlockInfo.scaffoldingBlockItems.has(item.type)) ?? null
      }
      case 'replaceable': {
        throw new Error('Not implemented')
      }
      default:
        throw new Error('Not implemented')
    }
  }

  getNearbyBlocks (world: World): BlockInfo[] {
    return [
      world.getBlockInfo(this.vec.offset(0, 1, 0)),
      world.getBlockInfo(this.vec.offset(0, -1, 0)),
      world.getBlockInfo(this.vec.offset(0, 0, -1)),
      world.getBlockInfo(this.vec.offset(0, 0, 1)),
      world.getBlockInfo(this.vec.offset(-1, 0, 0)),
      world.getBlockInfo(this.vec.offset(1, 0, 0))
    ]
  }

  needToPerform (bot: Bot): boolean {
    const blockInfo = bot.pathfinder.world.getBlockInfo(this.vec)
    if (blockInfo.isInvalid) {
      logPlace(`Block at ${this.vec} is invalid. needsToPerform: true`)
      return true
    }

    let needs = true
    switch (this.type) {
      case 'water': {
        needs = !(blockInfo.liquid && BlockInfo.waters.has(blockInfo.type))
        break
      }
      case 'solid': {
        needs = !blockInfo.physical
        break
      }
      case 'replaceable': {
        needs = !(blockInfo.replaceable)
        break
      }
    }

    // logPlace(`needToPerform at ${this.vec}? ${needs} (Type: ${this.type})`)
    return needs
  }

  async performInfo (bot: Bot, ticks = 15, scale = 0.5): Promise<InteractionPerformInfo> {
    switch (this.type) {
      case 'water': {
        throw new Error('Not implemented')
      }

      case 'solid': {
        const works = []

        for (let i = 0; i <= ticks; i++) {
          const ectx = EPhysicsCtx.FROM_BOT(bot.physicsUtil.engine, bot)
          const state = ectx.state

          // Lightweight physics simulation
          for (let j = 0; j < i; j++) {
            bot.physicsUtil.engine.simulate(ectx, bot.world)
          }

          const bb1 = state.getBB()
          const eyePos = state.pos.offset(0, state.eyeHeight, 0)

          const dx = eyePos.x - (this.vec.x + 0.5)
          const dy = eyePos.y - (this.vec.y + 0.5)
          const dz = eyePos.z - (this.vec.z + 0.5)

          const verts: Vec3[] = []
          const m = 0.05 // Tiny margin
          const M = 0.95

          // Top / Bottom Face (Center + 4 Corners)
          if (dy > 0) {
            verts.push(this.vec.offset(0.5, 1, 0.5), this.vec.offset(m, 1, m), this.vec.offset(M, 1, m), this.vec.offset(m, 1, M), this.vec.offset(M, 1, M))
          } else {
            verts.push(this.vec.offset(0.5, 0, 0.5), this.vec.offset(m, 0, m), this.vec.offset(M, 0, m), this.vec.offset(m, 0, M), this.vec.offset(M, 0, M))
          }

          // East / West Face (Center + 4 Corners)
          if (dx > 0) {
            verts.push(this.vec.offset(1, 0.5, 0.5), this.vec.offset(1, m, m), this.vec.offset(1, M, m), this.vec.offset(1, m, M), this.vec.offset(1, M, M))
          } else {
            verts.push(this.vec.offset(0, 0.5, 0.5), this.vec.offset(0, m, m), this.vec.offset(0, M, m), this.vec.offset(0, m, M), this.vec.offset(0, M, M))
          }

          // South / North Face (Center + 4 Corners)
          if (dz > 0) {
            verts.push(this.vec.offset(0.5, 0.5, 1), this.vec.offset(m, m, 1), this.vec.offset(M, m, 1), this.vec.offset(m, M, 1), this.vec.offset(M, M, 1))
          } else {
            verts.push(this.vec.offset(0.5, 0.5, 0), this.vec.offset(m, m, 0), this.vec.offset(M, m, 0), this.vec.offset(m, M, 0), this.vec.offset(M, M, 0))
          }

          let good = 0
          for (const vert of verts) {
            const rayRes: RayType | null = (await bot.world.raycast(
              eyePos,
              vert.minus(eyePos).normalize().scale(scale),
              PlaceHandler.reach / scale
            )) as unknown as RayType

            if (rayRes === null) continue

            const pos = rayRes.position.plus(faceToVec(rayRes.face))
            if (pos.equals(this.vec)) {
              if (bb1.containsVec(rayRes.intersect)) continue
              if (AABB.fromBlock(pos).intersects(bb1)) continue

              good++
              works.push(rayRes as unknown as RayType)
            }
          }

          // INSTANT EXIT: The moment we find a valid placement frame, return it!
          if (good > 0) {
            logPlace(`performInfo calculated for pos ${this.blockInfo.position}. ticks: ${i}, raycasts: ${good}`)
            return { ticks: i, tickAllowance: 0, shiftTick: Infinity, raycasts: works }
          }
        }

        logPlace(`performInfo failed to find placement path for pos ${this.blockInfo.position}. Returning Infinity.`)
        return { ticks: Infinity, tickAllowance: Infinity, shiftTick: Infinity, raycasts: works }
      }

      case 'replaceable': {
        throw new Error('Not implemented')
      }
      default: {
        throw new Error('Not implemented')
      }
    }
  }

  async perform (bot: Bot, item: Item | null, opts: InteractOpts = {}): Promise<void> {
    const curInfo = { yaw: bot.entity.yaw, pitch: bot.entity.pitch }

    if (item === null) {
      logPlace('Error: Cannot perform placement with null item')
      throw new Error('Invalid item')
    }

    logPlace(`Starting perform sequence at ${this.vec} with ${item.name}`)

    switch (this.type) {
      case 'water': {
        if (item.name !== 'water_bucket') throw new Error('Invalid item')
        if (this.getCurrentItem(bot) !== item) await this.equipItem(bot, item)

        logPlace(`Looking at ${this.vec} to place water.`)
        await bot.lookAt(this.vec, this.settings.forceLook)
        bot.activateItem(this.offhand)
        logPlace('Water placed.')
        break
      }

      case 'solid': {
        if (this.getCurrentItem(bot) !== item) await this.equipItem(bot, item)

        let works
        if (opts.info === undefined) {
          works = await this.performInfo(bot)
        } else works = opts.info

        let waitTicks = 0
        while (works.raycasts.length === 0) {
          if (this.cancelled || this.move.aborted || bot.pathfinder.abortCalculation) throw new CancelError('Block placement canceled')
          if (waitTicks >= Math.ceil(this.settings.movementTimeoutMs / 50)) throw new CancelError(`No reachable placement face for ${this.vec}`)
          waitTicks++
          await bot.waitForTicks(1)
          works = await this.performInfo(bot)
        }
        if (waitTicks > 0) logPlace(`Waited ${waitTicks} ticks for valid raycast intersections.`)

        const stateEyePos = bot.entity.position.offset(0, 1.62, 0)
        const lookDir = bot.util.getViewDir()
        works.raycasts.sort((a, b) => b.intersect.minus(stateEyePos).dot(lookDir) - a.intersect.minus(stateEyePos).dot(lookDir))

        const rayRes = works.raycasts[0]
        if (rayRes === undefined) {
          logPlace('Error: Failed to find valid rayRes after filtering.')

          throw new Error('Invalid block')
        }

        const pos = rayRes.position.plus(faceToVec(rayRes.face))
        const posBl = AABB.fromBlock(pos)

        logPlace('position: %O', bot.entity.position)
        logPlace(`Simulating movement ticks before placement (ticks needed: ${works.ticks})`)
        let i = 1
        for (; i <= works.ticks; i++) {
          const ectx = EPhysicsCtx.FROM_BOT(bot.physicsUtil.engine, bot)
          const state = ectx.state
          bot.physicsUtil.engine.simulate(ectx, bot.world)

          const sPos = state.pos.offset(0, 1.62, 0)
          const testCheck = (await bot.world.raycast(
            sPos,
            rayRes.intersect.minus(sPos).normalize().scale(0.5),
            PlaceHandler.reach * 2
          )) as unknown as RayType

          if (testCheck === null) {
            logPlace('what the fuck?')
            break
          }

          const pos1 = testCheck.position.plus(faceToVec(testCheck.face))
          const pos1Bl = AABB.fromBlock(pos1)
          if (testCheck.position.equals(rayRes.position) && testCheck.face === rayRes.face && !state.getBB().intersects(pos1Bl)) {
            // if (i < works.ticks && works.ticks !== 0) {
            logPlace(`Early exit from pre-placement simulation at tick ${i}/${works.ticks} due to favorable conditions. Current position: ${state.pos}, Ray intersect: ${rayRes.intersect}, Test check position: ${testCheck.position}, Test check face: ${testCheck.face}`)
            await bot.waitForTicks(1)
            // }
            // logPlace('what teh fuck 2?')
            break
          }
          logPlace(`Simulating tick ${i}/${works.ticks} before placement. Current position: ${state.pos}, Ray intersect: ${rayRes.intersect}, Test check position: ${testCheck.position}, Test check face: ${testCheck.face}`)
          await bot.waitForTicks(1)
        }

        const botBB = AABBUtils.getEntityAABBRaw({ position: bot.entity.position, width: 0.6, height: 1.8 })

        if (!this.move.isLookingAt(rayRes.intersect)) {
          logPlace(`Adjusting look toward raycast intersection at ${rayRes.intersect}`)
          void this.move.lookAt(rayRes.intersect)
          void bot.lookAt(rayRes.intersect, this.settings.forceLook)
        }

        const invalidPlacement = botBB.intersects(posBl)
        if (invalidPlacement) {
          logPlace(`Error: Invalid placement! Bot AABB intersects target placement AABB at ${posBl.bottomMiddlePoint()}. Age: ${i}, bot: ${bot.entity.position}, sim: ${botBB.bottomMiddlePoint()}`)
          await bot.lookAt(rayRes.intersect, this.settings.forceLook)
          throw new CancelError('Invalid placement')
        }

        const direction = faceToVec(rayRes.face)

        logPlace(`Calling bot._placeBlockWithOptions at face ${rayRes.face}`)
        this._placeTask = bot._placeBlockWithOptions(rayRes, direction, { forceLook: 'ignore', swingArm: 'right' })

        // Mineflayer confirms placement by observing the live world. Writing
        // a predicted floor there can satisfy its own confirmation, then leave
        // a phantom support after the server rejects the click. Search branches
        // already carry their virtual edits; execution waits for the real one.
        await this._placeTask
        if (this.needToPerform(bot)) throw new CancelError('Server did not confirm the placed block')
        logPlace('_placeTask resolved.')

        this.task?.finish()
        break
      }
      case 'replaceable':
      default: {
        throw new Error('Not implemented')
      }
    }

    if (opts.returnToPos !== undefined) {
      await bot.lookAt(opts.returnToPos, this.settings.forceLook)
    } else if (opts.returnToStart != null && opts.returnToStart) {
      await bot.look(curInfo.yaw, curInfo.pitch, this.settings.forceLook)
    }

    this._done = true
    this.performing = false
    delete this._placeTask
    logPlace(`Completed perform sequence at ${this.vec}`)
  }

  async abort (bot: Bot): Promise<void> {
    logPlace(`Aborting placement at ${this.vec}`)
    if ((this.task != null) && !this.task.done) {
      this.task.finish()
      this.task.canceled = true
    }

    if (this._placeTask != null) {
      await this._placeTask.catch((err) => {
        logPlace('Caught error during _placeTask abort: %O', err)
      })
    }
  }
}

export class BreakHandler extends InteractHandler {
  static reach = 4
  private _breakTask?: Promise<void>

  static fromVec (vec: Vec3, type: InteractType, offhand = false): BreakHandler {
    return new BreakHandler(vec.x, vec.y, vec.z, type, offhand)
  }

  toBlockInfo (): BlockInfo {
    return BlockInfo.AIR(this.vec)
  }

  getBlock (world: World): Block | null {
    return world.getBlock(this.vec)
  }

  getItem (bot: Bot, block: Block): Item | null {
    switch (this.type) {
      case 'water': {
        return bot.inventory.items().find((item) => item.name === 'bucket') ?? null // empty bucket
      }
      case 'solid': {
        // TODO: identify best tool for block.
        return bot.pathingUtil.bestHarvestingTool(block)
      }
      case 'replaceable': {
        throw new Error('Not implemented')
      }
      default:
        throw new Error('Not implemented')
    }
  }

  needToPerform (bot: Bot): boolean {
    const blockInfo = bot.pathfinder.world.getBlockInfo(this.vec)

    if (blockInfo.isInvalid) {
      logBreak(`Block at ${this.vec} is invalid. needsToPerform: true`)
      return true
    }

    const needs = !(blockInfo.block?.boundingBox === 'empty' && !BlockInfo.liquids.has(blockInfo.type))
    // logBreak(`needToPerform at ${this.vec}? ${needs}`)
    return needs
  }

  async performInfo (bot: Bot, ticks = 15): Promise<InteractionPerformInfo> {
    const bb = AABB.fromBlock(this.vec)
    const eyeHeight = (bot.entity as typeof bot.entity & { eyeHeight?: number }).eyeHeight ?? 1.62
    const eye = bot.entity.position.offset(0, eyeHeight, 0)
    const dist = bb.distanceToVec(eye)
    const block = bot.world.getBlock(this.vec) as Block | null
    let reachable = block != null && dist < BreakHandler.reach && bot.canDigBlock?.(block) !== false
    const raycasts: RayType[] = []
    // Reach alone doesn't expose a block behind another tunnel cell. The
    // old extra-five-block allowance sent digs the server could not accept.
    if (reachable && bot.world.raycast != null) {
      const faces = [[0.5, 0.5, 0.5], [0.001, 0.5, 0.5], [0.999, 0.5, 0.5],
        [0.5, 0.001, 0.5], [0.5, 0.999, 0.5], [0.5, 0.5, 0.001], [0.5, 0.5, 0.999]]
      reachable = faces.some(([x, y, z]) => {
        const delta = this.vec.offset(x, y, z).minus(eye)
        const range = delta.norm() + 0.01
        const hit = bot.world.raycast(eye, delta.normalize(), range) as unknown as RayType | null
        if (hit?.position.equals(this.vec)) { raycasts.push(hit); return true }
        return false
      })
    }

    logBreak(`performInfo calculation. Distance: ${dist.toFixed(2)}, Reachable: ${reachable}`)

    return reachable
      ? { ticks: 0, tickAllowance: 0, shiftTick: 0, raycasts }
      : { ticks: Infinity, tickAllowance: Infinity, shiftTick: Infinity, raycasts: [] }
  }

  async perform (bot: Bot, item: Item | null = null, opts: InteractOpts = {}): Promise<void> {
    const curInfo = { yaw: bot.entity.yaw, pitch: bot.entity.pitch }
    logBreak(`Starting break sequence at ${this.vec}`)

    switch (this.type) {
      case 'water': {
        if (item === null) throw new Error('No item')
        if (item.name !== 'bucket') throw new Error('Invalid item')
        if (this.getCurrentItem(bot) !== item) await this.equipItem(bot, item)

        logBreak(`Looking at ${this.vec} to collect water.`)
        await bot.lookAt(this.vec, this.settings.forceLook)
        bot.activateItem(this.offhand)
        logBreak('Water collected.')
        break
      }

      case 'solid': {
        await waitForMiningGround(bot, () => this.cancelled || this.move.aborted || bot.pathfinder.abortCalculation)
        if (item === null) {
          if (this.getCurrentItem(bot) !== null) await bot.unequip(this.offhand ? 'off-hand' : 'hand')
        } else if (this.getCurrentItem(bot) !== item) {
          await this.equipItem(bot, item)
        }

        const block = await bot.world.getBlock(this.vec) as Block | null
        if (block == null) {
          logBreak('Error: Block is null')
          throw new Error('Invalid block')
        }

        const info = await this.performInfo(bot, 0)
        if (info.ticks === Infinity) throw new CancelError('Block is outside mining reach or its face is obstructed')
        const hit = info.raycasts[0]
        const aim = hit != null ? hit.intersect.minus(faceToVec(hit.face).scaled(0.001)) : this.vec.offset(0.5, 0.5, 0.5)
        logBreak(`Looking at the reachable face of ${this.vec} to start digging.`)
        await bot.lookAt(aim, this.settings.forceLook)

        logBreak(`Calling bot.dig on ${block.name}`)
        // Let Mineflayer send the exposed face as well as the correct look;
        // forceLook='ignore' otherwise leaves its packet face at "top".
        this._breakTask = bot.dig(block, this.settings.forceLook, 'raycast')
        await this._breakTask

        logBreak('Dig task resolved. Now waiting for world update.')

        await waitForSettledBlockStateAtPosition(
          bot,
          this.blockInfo.position,
          (block) => block != null && BlockInfo.replaceables.has(block.type),
          { timeoutMs: 5000, settleMs: 75 }
        )

        if (this.task != null) this.task.finish()
        break
      }

      case 'replaceable': {
        throw new Error('Not implemented')
      }

      default: {
        throw new Error('Not implemented')
      }
    }

    if (opts.returnToPos !== undefined) {
      await bot.lookAt(opts.returnToPos, this.settings.forceLook)
    } else {
      const look = opts.returnToStart ?? false
      if (look) await bot.look(curInfo.yaw, curInfo.pitch, this.settings.forceLook)
    }

    delete this._breakTask
    logBreak(`Completed break sequence at ${this.vec}`)
  }

  async abort (bot: Bot): Promise<void> {
    logBreak(`Aborting break at ${this.vec}`)
    if ((this.task != null) && !this.task.done) {
      this.task.finish()
      this.task.canceled = true
    }

    if (this._breakTask != null) {
      switch (this.type) {
        case 'water': {
          break
        }
        case 'solid': {
          logBreak('Calling bot.stopDigging()')
          bot.stopDigging()
          break
        }
        case 'replaceable': {
          break
        }
      }
      await this._breakTask.catch((err) => {
        logBreak('Caught error during _breakTask abort: %O', err)
      })
    }
  }
}

// SPDX-License-Identifier: GPL-3.0-only
import { Vec3 } from 'vec3'
import type { Bot } from 'mineflayer'
import { Move } from '../move'
import type { Goal } from '../goals'
import type { World } from '../world/worldInterface'
import { Movement } from './movement'
import { MovementProvider } from './movementProvider'
import { MovementExecutor } from './movementExecutor'
import { steerToPosition } from './controls'
import { CancelError } from '../exceptions'
import { COST_INF, WALK_ONE_BLOCK_COST } from './costs'
import { installSupportingBlockPhysics, movementSupport, usesSupportingBlock } from '../supportingBlockPhysics'

const { PlayerState } = require('prismarine-physics')
const log = require('debug')('minecraft-pathfinding:momentum')
const slippery = new Set(['ice', 'packed_ice', 'blue_ice', 'frosted_ice', 'slime_block'])
const ice = new Set(['ice', 'packed_ice', 'blue_ice', 'frosted_ice'])

export function isIceBlock (name?: string): boolean { return name != null && ice.has(name) }
type Step = { position: Vec3; velocity: Vec3; onGround: boolean; yaw: number; jump: boolean; forward: boolean; back: boolean; right: boolean; left?: boolean; preparing?: boolean; support?: Vec3 }
type Warmup = false | { firstHopTick: number; chain: boolean }
type Flight = { steps: Step[]; warmup: Warmup; rimRebound: boolean; runup?: Vec3; airStrafe?: boolean }
type Segment = { edge: Vec3; target: Vec3; warmup: Warmup; rebound: boolean; contactSpeed: number; airStrafe: boolean }
type HopCandidate = { tick: number; distance: number }

/** Native Mineflayer physics includes surface friction, effects and live velocity. */
function predict (bot: Bot, world: World, from: Vec3, velocity: Vec3, edge: Vec3, target: Vec3, warmup: Warmup = false, live = false, candidates?: HopCandidate[], airStrafe = false, contacts?: number[], finalStrafeTicks = Number.POSITIVE_INFINITY): Step[] | undefined {
  installSupportingBlockPhysics(bot)
  log('predict %O -> %O edge=%O warmup=%s velocity=%O', from, target, edge, warmup, velocity)
  const dir = target.minus(edge); dir.y = 0; dir.normalize()
  const yaw = Math.atan2(-dir.x, -dir.z)
  const controls = { forward: true, back: false, left: false, right: false, jump: false, sneak: false, sprint: true }
  const state = new PlayerState(bot, controls)
  state.pos = from.clone(); state.vel = velocity.clone(); state.yaw = yaw
  if (live) {
    if (!state.onGround || state.isInWater || state.isInLava) return
  } else {
    state.onGround = true; state.isInWater = false; state.isInLava = false
    state.vel.y = Math.min(state.vel.y, -0.0784)
    state.jumpTicks = 0; state.jumpQueued = false
  }
  const steps: Step[] = []
  let launched = false
  let hopped = false
  let wasAirborne = false
  let finalAirTick = 0
  for (let tick = 0; tick < 140; tick++) {
    // Simulate the next running tick and take off before losing ice friction.
    let jump = false
    // Sprint on the runway first, then hop onto the ice so landing preserves
    // airborne momentum. A hop from rest wastes most of that acceleration.
    const distance = edge.minus(state.pos).dot(dir)
    if (!launched && state.onGround && wasAirborne && Math.abs(distance) < 1.5) contacts?.push(-distance)
    if (!launched && state.onGround && distance >= 1 && distance <= 7) candidates?.push({ tick, distance })
    const warmupJump = !launched && state.onGround && warmup !== false &&
      (tick === warmup.firstHopTick || (hopped && warmup.chain && distance >= 3))
    if (warmupJump) hopped = true
    if (!launched && state.onGround && !warmupJump) {
      const preview = Object.assign(Object.create(Object.getPrototypeOf(state)), state, {
        pos: state.pos.clone(), vel: state.vel.clone(), control: { ...controls, jump: false }
      })
      ;(bot.physics as any).simulatePlayer(preview, { getBlock: (pos: Vec3) => world.getBlock(pos) })
      // Modern vanilla retains its supporting block through the last grounded
      // edge tick. Legacy physics samples only below the player's center.
      const block = world.getBlockInfo(preview.pos.offset(0, -0.05, 0))
      const modern = usesSupportingBlock(bot)
      const supported = modern ? preview.onGround : block.physical && block.height >= edge.y - 0.05
      // A preparatory hop must rebound on contact with the last part of the
      // ice block, before a walking tick consumes its incoming momentum.
      const surface = movementSupport(bot, world, state) ?? state.pos.offset(0, -0.05, 0)
      const rimContact = wasAirborne && isIceBlock(world.getBlock(surface)?.name) &&
        distance <= (modern ? -0.5 : -0.2) && distance > (modern ? -1.2 : -0.5)
      jump = rimContact || !supported
    }
    if (jump) { launched = true; log('launch at %O velocity=%O', state.pos, state.vel) }
    const remaining = target.minus(state.pos).dot(dir)
    const back = launched && remaining < 0.55
    // Diagonal air inputs normalize to full acceleration. Rotate the view so
    // their resultant still follows the runway; keep sprint-jump impulses straight.
    const right = airStrafe && !state.onGround && !back && (!launched || finalAirTick++ < finalStrafeTicks)
    state.yaw = yaw + (right ? Math.PI / 4 : 0)
    state.control = { ...controls, jump: jump || warmupJump, forward: !back, back, right }
    wasAirborne = !state.onGround
    ;(bot.physics as any).simulatePlayer(state, { getBlock: (pos: Vec3) => world.getBlock(pos) })
    if (!launched && wasAirborne && state.pos.y <= edge.y + 0.01 && Math.abs(state.pos.minus(edge).dot(dir)) < 1.5) {
      contacts?.push(state.pos.minus(edge).dot(dir))
    }
    if (state.isInWater || state.isInLava || state.isCollidedHorizontally || state.pos.y < edge.y - 0.05) { log('rejected tick=%s at %O onGround=%s horizontal=%s', tick, state.pos, state.onGround, state.isCollidedHorizontally); return }
    steps.push({ position: state.pos.clone(), velocity: state.vel.clone(), onGround: state.onGround, yaw: state.yaw, jump: jump || warmupJump, forward: !back, back, right,
      support: movementSupport(bot, world, state)?.clone() })
    if (launched && state.onGround) {
      if (state.pos.floored().equals(target.floored())) { log('landed in %s ticks at %O', steps.length, state.pos); return steps }
      if (state.pos.xzDistanceTo(target) > 0.85) return
    }
    if (!launched && !state.onGround && warmup === false) return
  }
}

/** Face the landing again as early as possible, retaining the clearance of a
 * verified opt-in jump that needed 45-degree inputs.
 */
function shortenAirStrafe (bot: Bot, world: World, from: Vec3, velocity: Vec3, edge: Vec3, target: Vec3, warmup: Warmup, live: boolean, steps: Step[], accept: (steps: Step[]) => boolean): Step[] {
  const dir = target.minus(edge); dir.y = 0; dir.normalize()
  const clearance = (flight: Step[]): number => flight[flight.length - 2].position.minus(target).dot(dir) + 0.5 + (bot.entity.width ?? 0.6) / 2
  const minimum = Math.min(0.005, clearance(steps))
  let takeoff = 0
  for (let i = 0; i < steps.length; i++) if (steps[i].jump) takeoff = i
  const boostedTicks = steps.slice(takeoff).filter(step => step.right).length
  for (let ticks = 0; ticks < boostedTicks; ticks++) {
    const shorter = predict(bot, world, from, velocity, edge, target, warmup, live, undefined, true, undefined, ticks)
    if (shorter != null && clearance(shorter) >= minimum - 1e-7 && accept(shorter)) return shorter
  }
  return steps
}

/** Search actual input ticks: running, a timed hop onto the rim, then takeoff.
 * Ice retains speed; it never supplies an invented velocity or extra jump impulse.
 */
function rimContactStep (world: World, edge: Vec3, target: Vec3, steps: Step[]): Step | undefined {
  const dir = target.minus(edge); dir.y = 0; dir.normalize()
  for (let i = 2; i < steps.length; i++) {
    const step = steps[i]
    if (!step.jump || step.onGround) continue
    const contact = steps[i - 1]
    const rimOffset = contact.position.minus(edge).dot(dir)
    if (contact.onGround && !steps[i - 2].onGround && rimOffset >= 0.2 && rimOffset < (contact.support != null ? 1.2 : 0.5) &&
      isIceBlock(world.getBlock(contact.support ?? contact.position.offset(0, -0.05, 0))?.name)) return contact
  }
}

function reboundsAtRim (world: World, edge: Vec3, target: Vec3, steps: Step[]): boolean {
  return rimContactStep(world, edge, target, steps) != null
}

export function predictMomentumJump (bot: Bot, world: World, from: Vec3, velocity: Vec3, edge: Vec3, target: Vec3, live = false, accept: (steps: Step[]) => boolean = () => true, refineRunup = false, allowAirStrafe = false): Flight | undefined {
  let fallback: Flight | undefined
  const candidates: HopCandidate[] = []
  const dir = target.minus(edge); dir.y = 0; dir.normalize()
  const refine = (warmup: Warmup, airStrafe: boolean, contacts: number[]): Flight | undefined => {
    if (live || !refineRunup || velocity.xzDistanceTo(new Vec3(0, 0, 0)) > 0.02) return
    for (const contact of new Set(contacts)) {
      // Search positions within the starting block for both straight and
      // diagonal inputs, so an avoidable side turn never wins on rounding alone.
      const shift = 0.495 - contact
      if (Math.abs(shift) > 0.49) continue
      const runup = from.plus(dir.scaled(shift))
      if (!world.getBlockInfo(runup.offset(0, -1, 0)).solidFull ||
          ![0, 1, 2].every(y => world.getBlockInfo(runup.offset(0, y, 0)).walkthrough)) continue
      const adjusted = predict(bot, world, runup, velocity, edge, target, warmup, false, undefined, airStrafe)
      if (adjusted != null && accept(adjusted) && reboundsAtRim(world, edge, target, adjusted)) {
        return { steps: airStrafe ? shortenAirStrafe(bot, world, runup, velocity, edge, target, warmup, false, adjusted, accept) : adjusted,
          warmup, rimRebound: true, runup, airStrafe }
      }
    }
  }
  const direct = predict(bot, world, from, velocity, edge, target, false, live, candidates)
  if (direct != null && accept(direct)) {
    fallback = { steps: direct, warmup: false, rimRebound: false }
    // Keep a bot already moving onto the rim in motion, including an incoming
    // hop whose landing happened before this movement started.
    if (from.xzDistanceTo(edge) < 1.5 && velocity.xzDistanceTo(new Vec3(0, 0, 0)) > 0.32) return fallback
  }
  // Roughly one sprint-jump before the rim is a useful search order, not a
  // distance guarantee. Every candidate still runs through native collisions.
  candidates.sort((a, b) => Math.abs(a.distance - 4.5) - Math.abs(b.distance - 4.5))
  for (const { tick } of candidates) {
    const warmup = { firstHopTick: tick, chain: false }
    const steps = predict(bot, world, from, velocity, edge, target, warmup, live)
    if (steps != null && accept(steps)) {
      if (reboundsAtRim(world, edge, target, steps)) return { steps, warmup, rimRebound: true }
      fallback ??= { steps, warmup, rimRebound: false }
    }
  }
  // A longer runway can build momentum with repeated hops. Vary the first
  // takeoff over one ordinary jump's duration to land on a short ice rim.
  if (from.xzDistanceTo(edge) >= 6) {
    for (let firstHopTick = 0; firstHopTick <= 12; firstHopTick++) {
      const warmup = { firstHopTick, chain: true }
      const contacts: number[] = []
      const steps = predict(bot, world, from, velocity, edge, target, warmup, live, undefined, false, contacts)
      if (steps != null && accept(steps)) {
        if (reboundsAtRim(world, edge, target, steps)) return { steps, warmup, rimRebound: true }
        fallback ??= { steps, warmup, rimRebound: false }
      }
      const adjusted = refine(warmup, false, contacts)
      if (adjusted != null) return adjusted
    }
  }
  if (fallback != null || !allowAirStrafe) return fallback
  const warmups: Warmup[] = [false, ...candidates.map(({ tick }) => ({ firstHopTick: tick, chain: false }))]
  if (from.xzDistanceTo(edge) >= 6) for (let tick = 0; tick <= 12; tick++) warmups.push({ firstHopTick: tick, chain: true })
  for (const warmup of warmups) {
    const contacts: number[] = []
    const steps = predict(bot, world, from, velocity, edge, target, warmup, live, undefined, true, contacts)
    if (steps != null && accept(steps)) return { steps: shortenAirStrafe(bot, world, from, velocity, edge, target, warmup, live, steps, accept), warmup, rimRebound: reboundsAtRim(world, edge, target, steps), airStrafe: true }
    const adjusted = refine(warmup, true, contacts)
    if (adjusted != null) return adjusted
  }
}

function flightExclusionCost (movement: Movement, steps: Step[]): number {
  const visited = new Set<string>()
  let cost = 0
  for (const step of steps) {
    const position = step.position.floored()
    const key = position.toString()
    if (visited.has(key)) continue
    visited.add(key)
    cost += movement.exclusionStep(movement.world.getBlockInfo(position))
    if (cost >= COST_INF) break
  }
  return cost
}

export class MomentumJump extends MovementProvider {
  movementDirs = Movement.cardinalDirs
  provideMovements (node: Move, storage: Move[], goal: Goal, closed: Set<string>): void {
    if (!this.settings.allowSprinting || !this.settings.allowJumpSprint) return
    const floor = this.getBlockInfo(node, 0, -1, 0)
    if (!floor.solidFull || this.getBlockInfo(node, 0, 0, 0).liquid) return
    const nodeOrigin = node.cachedVec.offset(0.5, 0, 0.5)
    for (const dir of this.movementDirs) {
      let ahead = 0
      let origin = nodeOrigin
      while (ahead < 24) {
        const next = origin.plus(dir)
        if (!this.getBlockInfo(next, 0, -1, 0).solidFull || ![0, 1, 2].every(y => this.getBlockInfo(next, 0, y, 0).walkthrough)) break
        origin = next; ahead++
      }
      if (this.getBlockInfo(origin, dir.x, -1, dir.z).physical) continue
      let runup = 0
      let boosted = slippery.has(this.getBlockInfo(origin, 0, -1, 0).block?.name ?? '') || node.exitVel.xzDistanceTo(new Vec3(0, 0, 0)) > 0.32
      for (let distance = 1; distance <= 24; distance++) {
        const pos = origin.minus(dir.scaled(distance))
        if (!this.getBlockInfo(pos, 0, -1, 0).solidFull || !this.getBlockInfo(pos, 0, 0, 0).walkthrough || !this.getBlockInfo(pos, 0, 1, 0).walkthrough) break
        runup = distance
        boosted ||= slippery.has(this.getBlockInfo(pos, 0, -1, 0).block?.name ?? '')
      }
      if (!boosted) continue
      for (let distance = 2; distance <= 9; distance++) {
        const pos = origin.plus(dir.scaled(distance))
        if (![0, 1, 2].every(y => this.getBlockInfo(pos, 0, y, 0).walkthrough)) break
        if (!this.getBlockInfo(pos, 0, -1, 0).solidFull) continue
        // Four air blocks (five between floor centers) also need a continuous
        // ice approach; the standing parkour executor can lose this momentum.
        if (distance < 5 || closed.has(`${Math.floor(pos.x)},${pos.y},${Math.floor(pos.z)}`)) break
        let fallback: { flight: Flight; from: Vec3; backup: number } | undefined
        let selected: typeof fallback
        for (let backup = ahead; backup <= runup; backup++) {
          const from = backup === ahead ? node.exitPos : origin.minus(dir.scaled(backup))
          const velocity = backup === ahead ? node.exitVel : new Vec3(0, 0, 0)
          // Runway/flight exclusions also apply to long jumps, not just the landing.
          const flight = predictMomentumJump(this.bot, this.world, from, velocity, origin, pos, false,
            steps => flightExclusionCost(this, steps) < COST_INF, true, this.settings.allowAirStrafe)
          if (flight == null) continue
          const candidate = { flight, from: flight.runup ?? from, backup }
          if (flight.rimRebound || (backup === ahead && velocity.xzDistanceTo(new Vec3(0, 0, 0)) > 0.32)) {
            selected = candidate
            break
          }
          fallback ??= candidate
        }
        selected ??= fallback
        if (selected != null) {
          const { flight, from, backup } = selected
          this.addContinuations(node, storage, goal, closed, dir, origin, pos, flight, from, (backup - ahead) * WALK_ONE_BLOCK_COST)
        }
        break
      }
    }
  }

  private addContinuations (node: Move, storage: Move[], goal: Goal, closed: Set<string>, dir: Vec3, edge: Vec3, target: Vec3, flight: Flight, from: Vec3, approachCost: number): void {
    const segments: Segment[] = []
    let steps: Step[] = []
    const preciseRunup = flight.runup != null
    // A short intermediate runway may only work with the incoming flight's
    // speed. Verify its continuation now and execute all its ticks together.
    for (let count = 0; count < 8; count++) {
      let nextEdge = target.floored().offset(0.5, 0, 0.5)
      let length = 0
      while (length < 24) {
        const next = nextEdge.plus(dir)
        if (!this.getBlockInfo(next, 0, -1, 0).solidFull || ![0, 1, 2].every(y => this.getBlockInfo(next, 0, y, 0).walkthrough)) break
        nextEdge = next; length++
      }
      let nextTarget: Vec3 | undefined
      if (length < 24 && isIceBlock(this.getBlockInfo(nextEdge, 0, -1, 0).block?.name) &&
          !this.getBlockInfo(nextEdge, dir.x, -1, dir.z).physical) {
        for (let distance = 2; distance <= 9; distance++) {
          const next = nextEdge.plus(dir.scaled(distance))
          if (![0, 1, 2].every(y => this.getBlockInfo(next, 0, y, 0).walkthrough)) break
          if (!this.getBlockInfo(next, 0, -1, 0).solidFull) continue
          if (distance >= 5) nextTarget = next
          break
        }
      }
      const continueFrom = (candidate: Flight): Flight | undefined => {
        if (nextTarget == null) return
        const landing = candidate.steps[candidate.steps.length - 1]
        return predictMomentumJump(this.bot, this.world, landing.position, landing.velocity, nextEdge, nextTarget,
          false, nextSteps => flightExclusionCost(this, nextSteps) < COST_INF, false, this.settings.allowAirStrafe)
      }
      let continuation = count < 7 ? continueFrom(flight) : undefined
      // Landing at a block's center can leave the wrong tick phase for a short
      // next runway. Try a few real braking trajectories within that same block
      // and accept one only after its next takeoff is also verified.
      if (count > 0 && count < 7 && nextTarget != null && continuation == null) {
        const incoming = steps[steps.length - 1]
        const center = target.floored().offset(0.5, 0, 0.5)
        for (const shift of [-0.25, -0.45, 0.25, 0.45]) {
          const adjustedTarget = center.plus(dir.scaled(shift))
          const adjusted = predictMomentumJump(this.bot, this.world, incoming.position, incoming.velocity, edge, adjustedTarget,
            false, nextSteps => flightExclusionCost(this, nextSteps) < COST_INF, false, this.settings.allowAirStrafe)
          if (adjusted == null) continue
          const next = continueFrom(adjusted)
          if (next == null) continue
          target = adjustedTarget; flight = adjusted; continuation = next
          break
        }
      }
      segments.push({ edge, target, warmup: flight.warmup, rebound: flight.rimRebound,
        contactSpeed: rimContactStep(this.world, edge, target, flight.steps)?.velocity.dot(dir) ?? 0,
        airStrafe: flight.airStrafe === true })
      steps = [...steps, ...flight.steps]
      const landing = steps[steps.length - 1]
      const cost = approachCost + steps.length + flightExclusionCost(this, steps)
      if (cost >= COST_INF) break
      // The executor settles only at the end of the entire chain. Intermediate
      // predictions below use the real landing speed; a later movement starts
      // from rest. Never assign predicted positions or velocity to the bot.
      const move = new Move(landing.position.x, landing.position.y, landing.position.z, [], [], node.remainingBlocks,
        cost, this, node.exitPos, node.exitVel, landing.position.clone(), new Vec3(0, 0, 0), node)
      move.metadata = { momentumEdge: segments[0].edge, momentumRunup: from, momentumWarmup: segments[0].warmup,
        momentumRebound: segments[0].rebound, momentumContactSpeed: segments[0].contactSpeed,
        momentumAirStrafe: segments.some(segment => segment.airStrafe), momentumPreciseRunup: preciseRunup,
        momentumSegments: segments.slice() }
      if (!closed.has(move.hash)) storage.push(move)
      if (goal.isEnd(move)) break

      if (nextTarget == null || continuation == null) break
      edge = nextEdge; target = nextTarget; flight = continuation
    }
  }
}

export class MomentumJumpExecutor extends MovementExecutor {
  private steps: Step[] = []
  private index = 0
  private listener?: () => void
  private landed = false
  private failure?: Error
  private face (yaw: number): void {
    // Update Mineflayer's transmitted look as well as its physics angle. Direct
    // entity assignments alone leave other players seeing a delayed side turn.
    void this.bot.look(yaw, 0, true)
    this.bot.entity.yaw = yaw; this.bot.entity.pitch = 0
  }
  // Ice contact is an intermediate landing in the same flight sequence.
  override get canInterrupt (): boolean { return this.listener == null || this.landed || this.failure != null }
  override reset (): void {
    if (this.listener != null) this.bot.off('physicsTick', this.listener)
    this.listener = undefined; this.steps = []; this.index = 0; this.landed = false; this.failure = undefined
    super.reset()
  }
  private planFromCurrentState (move: Move, position = this.bot.entity.position, velocity = this.bot.entity.velocity, preferredOnly = false): Step[] {
    const segments: Segment[] = move.metadata!.momentumSegments
    const result: Step[] = []
    for (const [index, segment] of segments.entries()) {
      const { edge, target, warmup } = segment
      const live = index === 0
      const incoming = position.xzDistanceTo(edge) < 1.5 && velocity.xzDistanceTo(new Vec3(0, 0, 0)) > 0.32
      const dir = target.minus(edge); dir.y = 0; dir.normalize()
      const accept = (steps: Step[]): boolean => {
        if (flightExclusionCost(this, steps) >= COST_INF) return false
        if (!segment.rebound || incoming) return true
        const contact = rimContactStep(this.world, edge, target, steps)
        return contact != null && contact.velocity.dot(dir) >= segment.contactSpeed * 0.98
      }
      const strafe = this.settings.allowAirStrafe && segment.airStrafe
      let steps = predict(this.bot, this.world, position, velocity, edge, target, warmup, live, undefined, strafe)
      if (steps != null && accept(steps)) {
        if (strafe) steps = shortenAirStrafe(this.bot, this.world, position, velocity, edge, target, warmup, live, steps, accept)
      } else {
        if (preferredOnly) return []
        steps = predictMomentumJump(this.bot, this.world, position, velocity, edge, target, live, accept, false, this.settings.allowAirStrafe)?.steps
      }
      if (steps == null) return []
      result.push(...steps)
      const landing = steps[steps.length - 1]
      position = landing.position; velocity = landing.velocity
    }
    return result
  }
  private alignmentPlan (move: Move, yaw: number): Step[] {
    const target: Vec3 = move.metadata!.momentumRunup
    if (!this.bot.entity.onGround || this.bot.entity.position.xzDistanceTo(target) > 0.3) return []
    const world = { getBlock: (pos: Vec3) => this.world.getBlock(pos) }
    // Plan a short held key followed by coasting, and start the jump at a
    // physically viable position and speed. No millimetre-by-millimetre dithering.
    const tryInputs = (inputs: number[]): Step[] => {
      const control = { forward: false, back: false, left: false, right: false, jump: false, sprint: false, sneak: true }
      const state = new PlayerState(this.bot, control); state.yaw = yaw
      const prefix: Step[] = []
      for (let tick = 0; tick < inputs.length + 10; tick++) {
        const forward = inputs[tick] ?? 0
        state.control = { ...control, forward: forward > 0, back: forward < 0 }
        ;(this.bot.physics as any).simulatePlayer(state, world)
        if (!state.onGround || state.isInWater || state.isInLava || state.isCollidedHorizontally) break
        prefix.push({ position: state.pos.clone(), velocity: state.vel.clone(), onGround: state.onGround, yaw,
          jump: false, forward: state.control.forward, back: state.control.back, right: false, preparing: true })
        if (tick < inputs.length - 1 || state.pos.xzDistanceTo(target) > 0.12) continue
        const flight = this.planFromCurrentState(move, state.pos, state.vel, true)
        if (flight.length > 0 && flightExclusionCost(this, [...prefix, ...flight]) < COST_INF) return [...prefix, ...flight]
      }
      return []
    }
    for (let hold = 0; hold <= 4; hold++) for (const forward of (hold === 0 ? [0] : [1, -1])) {
      const steps = tryInputs(Array<number>(hold).fill(forward))
      if (steps.length > 0) return steps
    }
    // Some tick phases need one deliberate braking input. Verify the complete
    // sequence before executing it, rather than reversing keys every tick.
    for (let first = 1; first <= 4; first++) for (let brake = 1; brake <= 4; brake++) for (const forward of [1, -1]) {
      const steps = tryInputs([...Array<number>(first).fill(forward), ...Array<number>(brake).fill(-forward)])
      if (steps.length > 0) return steps
    }
    return []
  }
  private coastToRunup (target: Vec3, yaw: number): void {
    const control = { forward: false, back: false, left: false, right: false, jump: false, sprint: false, sneak: true }
    const state = new PlayerState(this.bot, control); state.yaw = yaw
    for (let tick = 0; tick < 12; tick++) (this.bot.physics as any).simulatePlayer(state, { getBlock: (pos: Vec3) => this.world.getBlock(pos) })
    const delta = target.minus(state.pos)
    const forward = -delta.x * Math.sin(yaw) - delta.z * Math.cos(yaw)
    const left = -delta.x * Math.cos(yaw) + delta.z * Math.sin(yaw)
    this.bot.setControlState('forward', forward > 0.025); this.bot.setControlState('back', forward < -0.025)
    this.bot.setControlState('left', left > 0.035); this.bot.setControlState('right', left < -0.035)
    this.bot.setControlState('jump', false); this.bot.setControlState('sprint', false)
    this.bot.setControlState('sneak', this.bot.entity.position.xzDistanceTo(target) < 0.45)
  }
  override align (move: Move): boolean {
    const edge: Vec3 = move.metadata!.momentumEdge
    this.steps = this.planFromCurrentState(move)
    if (this.steps.length > 0 && this.bot.entity.onGround) {
      // Install controls at this physics boundary. Async runner initialization
      // may otherwise consume another tick of the old alignment inputs.
      this.startFlight(move)
      return true
    }
    const target: Vec3 = move.metadata!.momentumRunup
    const firstTarget: Vec3 = move.metadata!.momentumSegments[0].target
    const yaw = Math.atan2(edge.x - firstTarget.x, edge.z - firstTarget.z)
    this.face(yaw)
    this.steps = this.alignmentPlan(move, yaw)
    if (this.steps.length > 0) {
      this.startFlight(move)
      return true
    }
    this.coastToRunup(target, yaw)
    return false
  }
  async performInit (_move: Move): Promise<void> {
    if (this.listener == null && !this.landed) throw this.failure ?? new CancelError('Momentum jump: flight interrupted before initialization')
  }
  private startFlight (move: Move): void {
    this.index = 0
    const apply = (): void => {
      const step = this.steps[this.index++]
      if (step == null) { this.failure = new CancelError('Momentum jump: missed the landing'); return }
      this.face(step.yaw)
      this.bot.setControlState('sneak', step.preparing === true)
      this.bot.setControlState('sprint', step.preparing !== true); this.bot.setControlState('jump', step.jump)
      this.bot.setControlState('forward', step.forward); this.bot.setControlState('back', step.back)
      this.bot.setControlState('right', step.right)
      this.bot.setControlState('left', step.left === true)
    }
    const listener = (): void => {
      if (this.aborted || this.bot.pathfinder.abortCalculation) { this.bot.off('physicsTick', listener); return }
      const previous = this.steps[this.index - 1]
      if (previous != null && previous.position.distanceTo(this.bot.entity.position) > (move.metadata!.momentumAirStrafe ? 0.02 : 0.4)) this.failure = new CancelError('Momentum jump: server position differs from the predicted flight')
      if (this.index > 0 && this.bot.entity.onGround && this.bot.entity.position.floored().equals(move.exitPos.floored())) this.landed = true
      if (this.landed || this.failure != null) {
        this.bot.off('physicsTick', listener); this.listener = undefined; this.bot.clearControlStates()
        const last: Segment = move.metadata!.momentumSegments.at(-1)
        this.face(Math.atan2(last.edge.x - last.target.x, last.edge.z - last.target.z))
        return
      }
      apply()
    }
    apply(); this.listener = listener; this.bot.on('physicsTick', listener)
  }
  performPerTick (move: Move): boolean {
    if (this.failure != null) throw this.failure
    if (!this.landed) return false
    steerToPosition(this.bot, move.exitPos, 0.1)
    this.bot.setControlState('jump', false); this.bot.setControlState('sprint', false)
    return this.bot.entity.onGround && this.bot.entity.position.xzDistanceTo(move.exitPos) < 0.3 && this.bot.entity.velocity.xzDistanceTo(new Vec3(0, 0, 0)) < 0.06
  }
}

import { BaseSimulator, EPhysicsCtx } from '@nxg-org/mineflayer-physics-util'
import { Bot } from 'mineflayer'
import { Vec3 } from 'vec3'
import { Move } from '../move'
import { World } from '../world/worldInterface'
import { BlockInfo } from '../world/cacheWorld'
import { BreakHandler, InteractHandler, PlaceHandler } from './interactionUtils'
import type { InteractType } from './interactionUtils'
import type { Block } from '../../types'
import { Vec3Properties } from '../../types'
import { COST_INF, SPRINT_ONE_BLOCK_COST, WALK_ONE_BLOCK_COST, WALK_ONE_IN_WATER_COST } from './costs'
import type { ExclusionArea } from './exclusionZones'
import { ClimbAwarePhysics } from '../climbablePhysics'

export interface MovementOptions {
  allowDiagonalBridging: boolean
  allowJumpSprint: boolean
  /** Grounded walking only, without jumping, falling, climbing or swimming. */
  walkOnly: boolean
  allowAirStrafe: boolean
  allow1by1towers: boolean

  // --- Cost knobs (all in GAME TICKS; see costs.ts) -----------------------
  /** Extra ticks per block when moving through liquid (water is slow). */
  liquidCost: number
  /** Multiplier on a block's real mining time. 1 = use the true dig time as-is. */
  digCost: number
  /** Extra ticks charged per jump, on top of the physical jump arc. 0 = trust the physics. */
  jumpCost: number
  /** Ticks charged for placing a block. Placing interrupts movement, so it is deliberately costly. */
  placeCost: number
  /** Ticks charged for killing horizontal velocity (e.g. stopping at the edge of a drop). */
  velocityKillCost: number

  forceLook: boolean
  canOpenDoors: boolean
  canDig: boolean
  /** Excavated downward stairs are enabled only while approaching mined resources. */
  allowExcavatedDescent: boolean
  /** Zero disables shaping. Mining routes clear these sections before moving. */
  excavationWidth: number
  excavationHeight: number
  excavationStairWidth: number
  excavationStairHeight: number
  canPlace: boolean
  dontCreateFlow: boolean
  dontMineUnderFallingBlock: boolean

  maxDropDown: number
  allowWaterDrop: boolean
  allowBucketWaterDrop: boolean
  infiniteLiquidDropdownDistance: boolean
  allowSprinting: boolean
  /** Repeated head-hit sprint jumps in supported two-block-high passages. */
  allowLowCeilingJumps: boolean
  careAboutLookAlignment: boolean

  movementTimeoutMs: number

  /**
   * "Keep out" rules for blocks the bot would STAND in / walk into.
   *
   * Each {@link ExclusionArea} is a function that returns the extra cost of a
   * block (return `>= COST_INF` to forbid it entirely). The cost of every area
   * in the list is added together. An empty list (the default) means "no zones",
   * and costs nothing to evaluate.
   *
   * Write your own; ready-to-copy box/radius helpers live in
   * `examples/exclusionZones.js`.
   */
  exclusionAreasStep: ExclusionArea[]

  /** "Keep out" rules for blocks the bot would BREAK (mine). See {@link exclusionAreasStep}. */
  exclusionAreasBreak: ExclusionArea[]

  /** "Keep out" rules for blocks the bot would PLACE (build on). See {@link exclusionAreasStep}. */
  exclusionAreasPlace: ExclusionArea[]
}

export const DEFAULT_MOVEMENT_OPTS: MovementOptions = {
  allowJumpSprint: true,
  walkOnly: false,
  allowAirStrafe: false,
  canOpenDoors: true,
  canDig: true,
  allowExcavatedDescent: false,
  excavationWidth: 0,
  excavationHeight: 2,
  excavationStairWidth: 0,
  excavationStairHeight: 3,
  canPlace: true,
  dontCreateFlow: true,
  dontMineUnderFallingBlock: true,
  allow1by1towers: true,
  maxDropDown: 3,
  allowWaterDrop: true,
  allowBucketWaterDrop: true,
  infiniteLiquidDropdownDistance: true,
  allowSprinting: true,
  allowLowCeilingJumps: false,
  // Extra time water adds over walking the same block on land (~4.46 ticks).
  liquidCost: WALK_ONE_IN_WATER_COST - WALK_ONE_BLOCK_COST,
  // Baritone's block-placement penalty: building a block to stand on is slow.
  placeCost: 20,
  // Keep a block's real mining time as-is (1x). Raise to make digging look worse.
  digCost: 1,
  // The jump arc already has a real tick cost (see JUMP_ONE_BLOCK_COST); add no fudge on top.
  jumpCost: 0,
  velocityKillCost: 2, // implement at a later date.
  forceLook: true,
  careAboutLookAlignment: true,
  allowDiagonalBridging: true,
  movementTimeoutMs: 1000,
  // No exclusion zones by default. Add your own with bot.pathfinder.setMoveOptions(...).
  exclusionAreasStep: [],
  exclusionAreasBreak: [],
  exclusionAreasPlace: []
}

// Lock the default exclusion lists so the single shared instances above can never
// be mutated in place. Real settings always receive their own fresh arrays via
// buildMovementOptions() below, so this is just a safety net.
Object.freeze(DEFAULT_MOVEMENT_OPTS.exclusionAreasStep)
Object.freeze(DEFAULT_MOVEMENT_OPTS.exclusionAreasBreak)
Object.freeze(DEFAULT_MOVEMENT_OPTS.exclusionAreasPlace)

/**
 * Merge user-supplied movement options on top of {@link DEFAULT_MOVEMENT_OPTS}
 * and return a complete {@link MovementOptions}.
 *
 * The three exclusion-area lists are ALWAYS returned as their own fresh arrays.
 * The defaults hold a single shared `[]` per list, so copying here is what stops
 * two different bots — or two `setMoveOptions` calls — from accidentally sharing
 * (and then mutating) the same array. Use this everywhere instead of a bare
 * `Object.assign({}, DEFAULT_MOVEMENT_OPTS, settings)`.
 */
export function buildMovementOptions (settings: Partial<MovementOptions> = {}): MovementOptions {
  const merged = Object.assign({}, DEFAULT_MOVEMENT_OPTS, settings)
  merged.exclusionAreasStep = [...merged.exclusionAreasStep]
  merged.exclusionAreasBreak = [...merged.exclusionAreasBreak]
  merged.exclusionAreasPlace = [...merged.exclusionAreasPlace]
  return merged
}

/**
 * Sum the extra cost every exclusion area in `areas` assigns to `block`.
 *
 * Returns 0 immediately when the list is empty (the normal case), so it is
 * essentially free unless the user opted in to exclusion zones.
 */
export function sumExclusionAreas (areas: ExclusionArea[], block: BlockInfo): number {
  if (areas.length === 0) return 0
  let weight = 0
  for (const area of areas) weight += area(block)
  return weight
}

