import { Vec3 } from 'vec3'
import { SimMovement } from '../movements'
import { BaseSimulator, Controller, EPhysicsCtx, EntityState, SimulationGoal } from '@nxg-org/mineflayer-physics-util'
import { Bot } from 'mineflayer'
import { goals } from '../goals'
import { Move } from '../move'
import { emptyVec } from '@nxg-org/mineflayer-physics-util/dist/physics/settings'

function setState (simCtx: EPhysicsCtx, pos: Vec3, vel: Vec3): void {
  simCtx.state.age = 0
  simCtx.state.pos.set(pos.x, pos.y, pos.z)
  simCtx.state.vel.set(vel.x, vel.y, vel.z)
}

export class ForwardJumpMovement extends SimMovement {
  controlAim (nextPoint: Vec3): Controller {
    // const zero = controls.getControllerSmartMovement(nextPoint, true);
    // const one = controls.getControllerStrafeAim(nextPoint);
    let aimed = false
    return (state: EntityState, ticks: number) => {
      if (!aimed) {
        const dx = nextPoint.x - state.pos.x
        const dz = nextPoint.z - state.pos.z
        state.yaw = Math.atan2(-dx, -dz)
        aimed = true
      }

      if (state.isCollidedHorizontally) {
        state.control.set('jump', true)
        state.control.set('forward', false)
        // state.control.set("back", true);
        state.control.set('sprint', false)
      } else {
        if (state.vel.offset(0, -state.vel.y, 0).norm() > 0.15) state.control.set('jump', true)
        // state.control.set("back", false);
        state.control.set('forward', true)
        state.control.set('sprint', true)
      }

      // zero(state, ticks);
      // one(state, ticks);
    }
  }

  botAim (bot: Bot, nextMove: Vec3, goal: goals.Goal): () => void {
    // const zero = controls.getBotSmartMovement(bot, nextMove, true);
    // const one = controls.getBotStrafeAim(bot, nextMove);
    let aimed = false
    return () => {
      if (!aimed) {
        const dx = nextMove.x - bot.entity.position.x
        const dz = nextMove.z - bot.entity.position.z
        bot.entity.yaw = Math.atan2(-dx, -dz)
        aimed = true
      }

      if ((bot.entity as any).isCollidedHorizontally as boolean) {
        bot.setControlState('jump', true)
        bot.setControlState('forward', false)
        bot.setControlState('back', true)
        bot.setControlState('sprint', false)
      } else {
        // console.log(bot.entity.velocity.offset(0, -bot.entity.velocity.y,0).norm())
        if (bot.entity.velocity.offset(0, -bot.entity.velocity.y, 0).norm() > 0.15) bot.setControlState('jump', true)
        bot.setControlState('back', false)
        bot.setControlState('forward', true)
        bot.setControlState('sprint', true)
      }
      // zero();
      // one();
    }
  }

  // right should be positiive,
  // left should be negative.

  getReached (goal: goals.Goal, nextPos: Vec3, start: Move): SimulationGoal {
    const vecGoal = goal.toVec()
    return (state: EntityState, age: number) => {
      if (!state.isCollidedVertically) return false
      return vecGoal.minus(state.pos).norm() <= vecGoal.minus(nextPos).norm() // && state.pos.minus(start.entryPos).norm() < 0.5
    }
  }

  botReach (bot: Bot, move: Move, goal: goals.Goal): () => boolean {
    const vecGoal = goal.toVec()
    return () => {
      if (!bot.entity.onGround) return false
      return vecGoal.minus(bot.entity.position).norm() <= vecGoal.minus(move.exitPos).norm()
    }
  }

  provideMovements (start: Move, storage: Move[], goal: goals.Goal): void {
    for (const dir of SimMovement.jumpDirs) {
      setState(this.stateCtx, start.exitPos, emptyVec)
      this.stateCtx.state.clearControlStates()

      const nextGoal = new Vec3(start.x + dir.x, start.y + dir.y, start.z + dir.z)
      const stopOnVertCollision: SimulationGoal = (state, ticks) => {
        return state.control.get('jump') && state.isCollidedVertically
      }
      const reach = this.getReached(goal, start.exitPos, start)

      // console.log(start.exitPos)
      const state = this.simulateUntil(
        BaseSimulator.buildAnyGoal(stopOnVertCollision),
        () => {},
        this.controlAim(nextGoal),
        this.stateCtx,
        this.bot.world,
        30
      )

      const diff = state.pos.minus(start.exitPos).norm()

      // console.log(state.pos, nextGoal, diff)
      if (diff === 0) return
      const cost = Math.round(state.age * 1)

      // if (stopOnHoriCollision(state, state.age)) {
      //   return;
      // }

      const good: boolean = reach(state, state.age)
      if (good) {
        // console.log("GI",state.pos, state.isCollidedVertically, cost)
        storage.push(Move.fromPreviousState(cost, state, start, this))
      }
    }
  }

  align (thisMove: Move, tickCount: number, goal: goals.Goal): boolean {
    return this.bot.entity.onGround
  }

  performPerTick = (move: Move, tickCount: number, currentIndex: number, path: Move[]): boolean => {
    // if (tickCount > 160) throw new CancelError("ForwardJumpMovement", "Took too long to reach goal");

    // const botAim = this.botAim(this.bot, move.exitPos, goal);
    // const botReach = this.botReach(this.bot, move, nextMove);
    // botAim();
    // return botReach();
    return true
  }

  performInit = async (move: Move, currentIndex: number, path: Move[]): Promise<void> => {
    await this.bot.lookAt(new Vec3(move.exitPos.x, move.exitPos.y, move.exitPos.z), true)

    const dx = move.exitPos.x - this.bot.entity.position.x
    const dz = move.exitPos.z - this.bot.entity.position.z
    const wantedYaw = Math.atan2(-dx, -dz)
    this.bot.entity.yaw = wantedYaw
  }
}

import { IPhysics } from '@nxg-org/mineflayer-physics-util/dist/physics/engines'
import { PlayerState } from '@nxg-org/mineflayer-physics-util/dist/physics/states'
import { AABB, AABBUtils } from '@nxg-org/mineflayer-util-plugin'
import { Vec3 } from 'vec3'
import { World } from '../../world/worldInterface'
import { BaseSimulator, Controller, EPhysicsCtx, OnGoalReachFunction, SimulationGoal } from '@nxg-org/mineflayer-physics-util'
import { smartMovement, strafeMovement, wrapRadians } from '../controls'

// const ZERO = (0 * Math.PI) / 12
const PI_OVER_TWELVE = (1 * Math.PI) / 12
// const TWO_PI_OVER_TWELVE = (2 * Math.PI) / 12
// const THREE_PI_OVER_TWELVE = (3 * Math.PI) / 12
// const FOUR_PI_OVER_TWELVE = (4 * Math.PI) / 12
const FIVE_PI_OVER_TWELVE = (5 * Math.PI) / 12
// const SIX_PI_OVER_TWELVE = (6 * Math.PI) / 12
const SEVEN_PI_OVER_TWELVE = (7 * Math.PI) / 12
// const EIGHT_PI_OVER_TWELVE = (8 * Math.PI) / 12
// const NINE_PI_OVER_TWELVE = (9 * Math.PI) / 12
// const TEN_PI_OVER_TWELVE = (10 * Math.PI) / 12
const ELEVEN_PI_OVER_TWELVE = (11 * Math.PI) / 12
// const TWELVE_PI_OVER_TWELVE = (12 * Math.PI) / 12
const THIRTEEN_PI_OVER_TWELVE = (13 * Math.PI) / 12
// const FOURTEEN_PI_OVER_TWELVE = (14 * Math.PI) / 12
// const FIFTEEN_PI_OVER_TWELVE = (15 * Math.PI) / 12
// const SIXTEEN_PI_OVER_TWELVE = (16 * Math.PI) / 12
const SEVENTEEN_PI_OVER_TWELVE = (17 * Math.PI) / 12
// const EIGHTEEN_PI_OVER_TWELVE = (18 * Math.PI) / 12
const NINETEEN_PI_OVER_TWELVE = (19 * Math.PI) / 12
// const TWENTY_PI_OVER_TWELVE = (20 * Math.PI) / 12
// const TWENTY_ONE_PI_OVER_TWELVE = (21 * Math.PI) / 12
// const TWENTY_TWO_PI_OVER_TWELVE = (22 * Math.PI) / 12
const TWENTY_THREE_PI_OVER_TWELVE = (23 * Math.PI) / 12
// const TWENTY_FOUR_PI_OVER_TWELVE = (24 * Math.PI) / 12

/**
 * To be used once per movement.
 *
 * Provide state that will serve as a base. The state itself will not be modified/consumed unless called for.
 */
export class JumpSim extends BaseSimulator<PlayerState> {
  public readonly world: World

  constructor (public readonly physics: IPhysics, world: World) {
    super(physics)
    this.world = world
  }

  public clone (): JumpSim {
    return new JumpSim(this.physics, this.world)
  }

  simulateUntilNextTick (ctx: EPhysicsCtx<PlayerState>): PlayerState {
    return this.simulateUntil(
      () => false,
      () => {},
      () => {},
      ctx,
      this.world,
      1
    )
  }

  simulateUntilOnGround (ctx: EPhysicsCtx<PlayerState>, ticks = 5, goal: SimulationGoal = () => false): PlayerState {
    const state = this.simulateUntil(
      JumpSim.buildAnyGoal(goal, (state, ticks) => ticks > 0 && state.onGround),
      () => {},
      () => {},
      ctx,
      this.world,
      ticks
    )

    // if (print) {
    // console.trace("potentially good", state.pos, state.vel, goal(state, 0));
    // console.trace();
    // }
    return state
  }

  simulateSmartAim (goal: AABB[], goalVec: Vec3, ctx: EPhysicsCtx<PlayerState>, sprint: boolean, jump: boolean, jumpAfter = 0, ticks = 20): PlayerState {
    return this.simulateUntil(
      JumpSim.getReachedAABB(goal),
      JumpSim.getCleanupPosition(goalVec),
      JumpSim.buildFullController(
        JumpSim.getControllerStraightAim(goalVec),
        JumpSim.getControllerSmartJumpMovement(goalVec, sprint, jump, jumpAfter)
      ),
      ctx,
      this.world,
      ticks
    )
  }

  /**
   * Assume we know the correct back-up position.
   */
  simulateBackUpBeforeJump (ctx: EPhysicsCtx<PlayerState>, goal: Vec3, sprint: boolean, strafe = true, ticks = 20): PlayerState {
    const aim = strafe ? JumpSim.getControllerStrafeAim(goal, true) : JumpSim.getControllerStraightAim(goal)
    return this.simulateUntil(
      (state) => state.pos.xzDistanceTo(goal) < 0.02,
      JumpSim.getCleanupPosition(goal),
      JumpSim.buildFullController(aim, JumpSim.getControllerSmartMovement(goal, sprint), (state, ticks) => {
        state.control.sprint = false
        state.control.sneak = true
      }),
      ctx,
      this.world,
      ticks
    )
  }

  simulateJumpFromEdgeOfBlock (ctx: EPhysicsCtx<PlayerState>, srcAABBs: AABB[], goalCorner: Vec3, goalBlock: AABB[], sprint: boolean, ticks = 20): PlayerState {
    let jump = false
    let changed = false

    // console.log('edge jump init', ctx.state.pos)
    return this.simulateUntil(
      JumpSim.getReachedAABB(goalBlock),
      JumpSim.getCleanupPosition(goalCorner),
      JumpSim.buildFullController(
        JumpSim.getControllerStraightAim(goalCorner),
        JumpSim.getControllerStrafeAim(goalCorner, true),
        JumpSim.getControllerSmartMovement(goalCorner, sprint),
        (state, ticks) => {
          // console.log('jump edge', state.age, state.pos)
          state.control.sneak = false
          // check if player is leaving src block collision
          const playerBB = state.getBB()
          playerBB.expand(0, 1e-6, 0)
          if (jump && state.pos.xzDistanceTo(goalCorner) < 0.5 && !changed) {
            // goalCorner.set(goalBlockTop.x, goalBlockTop.y, goalBlockTop.z)
            changed = true
          }

          const feet = playerBB.clone(); feet.minY = state.pos.y - 1e-6; feet.maxY = state.pos.y + 1e-6
          let supported = false
          for (let x = Math.floor(feet.minX + 1e-7); x <= Math.floor(feet.maxX - 1e-7); x++) {
            for (let z = Math.floor(feet.minZ + 1e-7); z <= Math.floor(feet.maxZ - 1e-7); z++) {
              supported ||= this.world.getBlockInfo(new Vec3(x, Math.floor(feet.minY), z)).getBBs().some(bb => bb.collides(feet))
            }
          }
          // Leaving a block in the middle of a runway is not the takeoff.
          // Native physics allows the last grounded tick beyond the ledge.
          if (ticks > 0 && state.onGround && !supported && !jump) {
            state.control.jump = true
            jump = true
          } else {
            state.control.jump = false
          }
        }
      ),
      ctx,
      this.world,
      ticks
    )
  }

  static getReachedAABB (bbs: AABB[]): SimulationGoal {
    if (bbs.length === 0) throw new Error('JumpSim: No AABBs for goal provided')
    const maxY = bbs.reduce((max, a) => Math.max(max, a.maxY), -Infinity)

    const lastXZVel = new Vec3(0, 0, 0)
    return (state) => {
      const bb = AABBUtils.getPlayerAABB({ position: state.pos, width: 0.5999, height: 1.8 })
      // if (state.pos.y >= maxY-0.3) console.log('hm?',state.age, state.pos, bbs)
      const xzVel = state.vel.offset(0, -state.vel.y, 0)

      // make sure bump does not occur.
      const ret = state.pos.y >= maxY && bbs.some((a) => a.collides(bb)) && lastXZVel.norm() - xzVel.norm() < 0.04

      return ret
    }
  }

  static getCleanupPosition (...path: Vec3[]): OnGoalReachFunction {
    return (state) => {
      state.control.reset()
    }
  }

  static getControllerStraightAim (nextPoint: Vec3): Controller {
    return (state, ticks) => {
      const dx = nextPoint.x - state.pos.x
      const dz = nextPoint.z - state.pos.z
      state.yaw = Math.atan2(-dx, -dz)
    }
  }

  // right should be positiive,
  // left should be negative.
  static getControllerStrafeAim (nextPoint: Vec3, strict = false): Controller {
    return (state, ticks) => strafeMovement(state, nextPoint, strict)

    // commented out for testing.
    // eslint-disable-next-line no-unreachable
    return (state, ticks) => {
      const offset = state.pos.plus(state.onGround ? state.vel : state.vel.scaled(1))
      const dx = nextPoint.x - offset.x
      const dz = nextPoint.z - offset.z
      const wantedYaw = wrapRadians(Math.atan2(-dx, -dz))
      const diff = wrapRadians(wantedYaw - state.yaw)

      if (PI_OVER_TWELVE < diff && diff < ELEVEN_PI_OVER_TWELVE) {
        state.control.left = true // are these reversed? tf
        state.control.right = false
        // console.log("left");
      } else if (THIRTEEN_PI_OVER_TWELVE < diff && diff < TWENTY_THREE_PI_OVER_TWELVE) {
        state.control.left = false
        state.control.right = true
        // console.log("right");
      } else {
        state.control.left = false
        state.control.right = false
        // console.log("rotate neither, left:", state.control.movements.left, "right:", state.control.movements.right);
      }
    }
  }

  static getControllerJumpSprint (jump: boolean, sprint: boolean, jumpAfter = 0): Controller {
    return (state, ticks) => {
      state.control.jump = state.onGround && jump && ticks >= jumpAfter
      state.control.sprint = sprint
    }
  }

  // forward should be any value that abs. val to below pi / 2
  // backward is any value that abs. val to above pi / 2
  static getControllerSmartMovement (goal: Vec3, sprint: boolean): Controller {
    return (state, ticks) => smartMovement(state, goal, sprint)

    // commented out for testing.
    // eslint-disable-next-line no-unreachable
    return (state, ticks) => {
      const offset = state.pos.plus(state.onGround ? state.vel : state.vel.scaled(1))
      const dx = goal.x - offset.x
      const dz = goal.z - offset.z
      const wantedYaw = wrapRadians(Math.atan2(-dx, -dz))
      const diff = wrapRadians(wantedYaw - state.yaw)
      // console.log(diff / Math.PI * 12)
      if (SEVEN_PI_OVER_TWELVE < diff && diff < SEVENTEEN_PI_OVER_TWELVE) {
        state.control.forward = false
        state.control.sprint = false
        state.control.back = true
        // console.log("back");
      } else if (NINETEEN_PI_OVER_TWELVE < diff || diff < FIVE_PI_OVER_TWELVE) {
        state.control.forward = true
        state.control.sprint = sprint
        state.control.back = false
      } else {
        state.control.forward = false
        state.control.back = false
        state.control.sprint = false
      }
    }
  }

  static getControllerSmartJumpMovement (goal: Vec3, sprint: boolean, jump = false, jumpAfter = 0): Controller {
    return (state, ticks) => {
      smartMovement(state, goal, sprint)
      state.control.jump = state.onGround && jump && ticks >= jumpAfter
    }
  }
}

import type { Bot } from 'mineflayer'
import { Vec3 } from 'vec3'
import { Move } from '../move'
import type { Goal } from '../goals'
import type { World } from '../world/worldInterface'
import { Movement } from './movement'
import { MovementProvider } from './movementProvider'
import { MovementExecutor } from './movementExecutor'
import { CancelError } from '../exceptions'
import { COST_INF } from './costs'

const { PlayerState } = require('prismarine-physics')
const Block = require('prismarine-block')
const log = require('debug')('minecraft-pathfinding:water-drop')
const { toNotchianYaw, toNotchianPitch } = require('mineflayer/lib/conversions')
const MAX_TICKS = 160
const REACH = 4.5
type Flight = { ticks: number, position: Vec3, velocity: Vec3 }

function waterBucket (bot: Bot): ReturnType<Bot['inventory']['items']>[number] | undefined {
  return bot.inventory.items().find(item => item.name === 'water_bucket')
}

export function permitsWater (bot: Bot): boolean {
  const game = bot.game as typeof bot.game & { dimension: string, dimensionData?: { ultrawarm?: boolean } }
  return !String(game.dimension).includes('nether') && game.dimensionData?.ultrawarm !== true
}

/** Identical inputs are used by prediction and live execution. No invented impulse. */
export function flightControls (pos: Vec3, vel: Vec3, target: Vec3, sprint: boolean, jump: boolean) {
  const delta = target.minus(pos); delta.y = 0
  const correction = delta.minus(new Vec3(vel.x, 0, vel.z).scaled(3))
  const yaw = Math.atan2(-correction.x, -correction.z)
  return { yaw, controls: {
    forward: correction.norm() > 0.1, back: false, left: false, right: false,
    jump, sprint: sprint && delta.norm() > 1, sneak: false
  } }
}

export function supportHit (world: World, pos: Vec3, target: Vec3): boolean {
  const eye = pos.offset(0, 1.62, 0)
  const top = target.offset(0, -0.01, 0)
  const delta = top.minus(eye)
  if (delta.norm() > REACH) return false
  const hit = world.raycast(eye, delta.normalize(), REACH)
  return hit != null && hit.position.equals(target.floored().offset(0, -1, 0))
}

/** Run Minecraft's own physics against loaded blocks, including gravity,
 * friction, effects, body collisions and the real water entry tick.
 * A bucket simulation adds water only once its support can actually be used.
 */
export function predictWaterDrop (bot: Bot, world: World, from: Vec3, velocity: Vec3,
  target: Vec3, bucket: boolean, sprint: boolean, live = false): Flight | undefined {
  const state = new PlayerState(bot, {})
  state.pos = from.clone(); state.vel = velocity.clone()
  state.onGround = live ? bot.entity.onGround : true
  state.isInWater = false; state.isInLava = false
  state.jumpTicks = 0; state.jumpQueued = false
  let invalid = false, placed = false, airborne = false, wet = false
  const source = Block(bot.registry).fromStateId(bot.registry.blocksByName.water.minStateId, 0)
  source.position = target.floored()
  const facade = { getBlock: (pos: Vec3) => {
    const info = world.getBlockInfo(pos)
    if (info.isInvalid || !info.safe) invalid = true
    if (placed && pos.floored().equals(source.position)) return source
    return world.getBlock(pos)
  } }
  for (let tick = 0; tick < MAX_TICKS; tick++) {
    const input = flightControls(state.pos, state.vel, target, sprint && !wet,
      (tick === 0 && state.onGround) || (wet && !bucket))
    state.yaw = input.yaw; state.control = input.controls
    if (bucket && !placed && state.vel.y < -0.1 && state.pos.y - target.y < 3.1 &&
      state.pos.y > target.y + 0.8 && supportHit(world, state.pos, target)) placed = true
    ;(bot.physics as any).simulatePlayer(state, facade)
    airborne ||= !state.onGround
    const waterAtFeet = world.getBlockInfo(state.pos.offset(0, 0.1, 0)).water ||
      (placed && state.pos.floored().equals(source.position))
    wet ||= state.isInWater || (state.onGround && waterAtFeet)
    if (invalid || state.isInLava || state.isCollidedHorizontally || (!waterAtFeet && state.pos.y < target.y - 1)) {
      log('reject tick=%s pos=%O target=%O invalid=%s lava=%s wall=%s', tick, state.pos, target, invalid, state.isInLava, state.isCollidedHorizontally)
      return
    }
    if (wet) {
      if ((!bucket || placed) && state.pos.xzDistanceTo(target) < 0.45 &&
        Math.abs(state.pos.y - target.y) < 1.1) {
        return { ticks: tick + 1, position: state.pos.clone(), velocity: state.vel.clone() }
      }
    }
    if (airborne && state.onGround) {
      // One-block puddles can land on the bottom in the same tick as water
      // entry. Require water intersecting the feet before accepting that tick.
      const foot = facade.getBlock(state.pos.offset(0, 0.1, 0))
      if (foot?.name !== 'water' || state.pos.xzDistanceTo(target) >= 0.45) { log('dry ground at %O', state.pos); return }
    }
  }
}

export class WaterDrop extends MovementProvider {
  movementDirs = [...Movement.cardinalDirs, ...Movement.diagonalDirs]

  provideMovements (start: Move, storage: Move[], goal: Goal, closed: Set<string>): void {
    if (!this.settings.allowWaterDrop && !this.settings.allowBucketWaterDrop) return
    if (!this.getBlockInfo(start, 0, -1, 0).physical || this.getBlockInfo(start, 0, 0, 0).liquid) return
    const bucketAvailable = this.settings.allowBucketWaterDrop && permitsWater(this.bot) && waterBucket(this.bot) != null
    if (!this.settings.allowWaterDrop && !bucketAvailable) return
    const minY = Math.max(this.world.minY ?? (this.bot.game as any).minY ?? -64, start.y - 128)
    for (const dir of this.movementDirs) {
      // Walk to a real edge first; don't spend simulation time on flat ground.
      if (this.getBlockInfo(start, dir.x, -1, dir.z).physical) continue
      for (let distance = 1; distance <= (this.settings.allowWaterDrop ? 12 : 4); distance++) {
        const column = start.cachedVec.offset(dir.x * distance, 0, dir.z * distance)
        let target: Vec3 | undefined, bucket = false
        for (let y = start.y; y >= minY; y--) {
          const info = this.getBlockInfoRaw(new Vec3(column.x, y, column.z))
          if (info.isInvalid || !info.safe || (info.liquid && !info.water)) break
          if (info.water) {
            if (this.settings.allowWaterDrop && y < start.y - 1 &&
              (this.settings.infiniteLiquidDropdownDistance || start.y - y <= this.settings.maxDropDown)) target = info.position.offset(0.5, 0.1, 0.5)
            break
          }
          if (info.physical) {
            if (bucketAvailable && distance <= 4 && info.solidFull && start.y - info.height > this.settings.maxDropDown &&
              this.getBlockInfoRaw(info.position.offset(0, 1, 0)).block?.name === 'air') {
              target = info.position.offset(0.5, 1, 0.5); bucket = true
            }
            break
          }
          if (!info.walkthrough) break
        }
        if (target == null || closed.has(`${Math.floor(target.x)},${Math.floor(target.y)},${Math.floor(target.z)}`)) continue
        const head = this.getBlockInfoRaw(target.floored().offset(0, 1, 0))
        if (!head.safe || !head.walkthrough) continue
        const exclusion = this.exclusionStep(this.getBlockInfoRaw(target.floored())) +
          (bucket ? this.exclusionPlace(this.getBlockInfoRaw(target.floored())) : 0)
        if (exclusion >= COST_INF) continue
        const flight = predictWaterDrop(this.bot, this.world, start.exitPos, new Vec3(0, 0, 0),
          target, bucket, this.settings.allowSprinting)
        if (flight == null) continue
        const move = Move.fromPrevious(flight.ticks + exclusion + (bucket ? 20 : 0), target, start, this)
        move.metadata = { waterLanding: true, bucketWaterDrop: bucket, waterDropTicks: flight.ticks }
        storage.push(move)
      }
    }
  }
}

/** Equip before takeoff, place while the support is in reach, and collect only
 * after immersion has arrested the fall and the player has reached the floor.
 */
export class WaterDropExecutor extends MovementExecutor {
  private generation = 0
  private launched = false
  private wet = false
  private placed = false
  private collected = false
  private attempts = 0
  private lastUse = -10
  private started = 0
  private flightTicks = 0
  private previousItem?: ReturnType<Bot['inventory']['items']>[number]

  override get canInterrupt (): boolean { return !this.launched || (this.wet && !this.currentMove.metadata?.bucketWaterDrop) || this.collected }
  override reset (): void {
    this.generation++
    this.launched = false; this.wet = false; this.placed = false; this.collected = false
    this.attempts = 0; this.lastUse = -10; this.started = 0; this.flightTicks = 0
    this.previousItem = undefined
    super.reset()
  }
  isAlreadyCompleted (move: Move): boolean {
    return !move.metadata?.bucketWaterDrop && (this.bot.entity as any).isInWater === true &&
      this.bot.entity.position.xzDistanceTo(move.exitPos) < 0.45
  }
  align (move: Move): boolean {
    const pos = this.bot.entity.position
    // The trajectory is rechecked from the actual takeoff state in init.
    if (!this.bot.entity.onGround) throw new CancelError('Water drop needs a supported takeoff')
    if (pos.xzDistanceTo(move.entryPos) < 0.2 && Math.hypot(this.bot.entity.velocity.x, this.bot.entity.velocity.z) < 0.03) return true
    const input = flightControls(pos, this.bot.entity.velocity, move.entryPos, false, false)
    this.applyControls(input)
    return false
  }
  async performInit (move: Move): Promise<void> {
    const generation = this.generation
    const bucket = move.metadata?.bucketWaterDrop === true
    if (bucket) {
      const item = waterBucket(this.bot)
      if (!permitsWater(this.bot) || item == null ||
        this.world.getBlock(move.exitPos)?.name !== 'air' ||
        !this.world.getBlockInfo(move.exitPos.offset(0, -1, 0)).solidFull) throw new CancelError('Water bucket landing unavailable for drop')
      this.previousItem = this.bot.heldItem ?? undefined
      await this.bot.equip(item, 'hand')
      if (generation !== this.generation) return
    }
    if (predictWaterDrop(this.bot, this.world, this.bot.entity.position, this.bot.entity.velocity,
      move.exitPos, bucket, this.settings.allowSprinting, true) == null) {
      throw new CancelError('Water drop trajectory is no longer safe')
    }
    this.started = performance.now()
  }
  public acceptsWorldUpdate (position: Vec3, name: string): boolean {
    if (!this.currentMove?.metadata?.bucketWaterDrop || !this.placed) return false
    const source = this.currentMove.exitPos.floored()
    if (position.equals(source)) return name === 'water' || (name === 'air' && this.attempts > 0)
    // Water placed by this move can flow sideways and down while we land.
    return name === 'water' && position.y <= source.y && position.xzDistanceTo(source) <= 7
  }
  private applyControls (input: ReturnType<typeof flightControls>): void {
    this.bot.entity.yaw = input.yaw
    for (const [name, value] of Object.entries(input.controls)) this.bot.setControlState(name as keyof typeof input.controls, value)
  }
  private async useBucket (point: Vec3, generation: number): Promise<void> {
    await this.bot.lookAt(point, true)
    if (generation !== this.generation) return
    // Older protocols raycast with the last server-side rotation. Send the
    // look before use_item instead of waiting another falling physics tick.
    this.bot._client.write('look', {
      yaw: Math.fround(toNotchianYaw(this.bot.entity.yaw)),
      pitch: Math.fround(toNotchianPitch(this.bot.entity.pitch)),
      onGround: this.bot.entity.onGround,
      flags: { onGround: this.bot.entity.onGround, hasHorizontalCollision: (this.bot.entity as any).isCollidedHorizontally }
    })
    this.bot.activateItem()
  }
  async performPerTick (move: Move): Promise<boolean> {
    const generation = this.generation
    const pos = this.bot.entity.position, vel = this.bot.entity.velocity
    log('execute pos=%O wet=%s ground=%s collected=%s item=%s', pos, this.wet, this.bot.entity.onGround, this.collected, this.bot.heldItem?.name)
    const bucket = move.metadata?.bucketWaterDrop === true
    if (performance.now() - this.started > MAX_TICKS * 50 + this.settings.movementTimeoutMs) throw new CancelError('Water drop timed out')
    this.wet ||= (this.bot.entity as any).isInWater === true ||
      (this.bot.entity.onGround && this.world.getBlockInfo(pos.offset(0, 0.1, 0)).water)
    const input = flightControls(pos, vel, move.exitPos, this.settings.allowSprinting, !this.launched)
    if (this.wet) { input.controls.jump = !bucket; input.controls.sprint = false }
    this.applyControls(input)
    this.launched = true
    this.flightTicks++
    if (bucket && !this.placed && vel.y < -0.1 && pos.y - move.exitPos.y < 3.1 &&
      supportHit(this.world, pos, move.exitPos)) {
      if (this.bot.heldItem?.name !== 'water_bucket') throw new CancelError('Water bucket lost during drop')
      this.placed = true
      await this.useBucket(move.exitPos.offset(0, -0.01, 0), generation)
    }
    if (!bucket && this.wet && pos.xzDistanceTo(move.exitPos) < 0.5 && Math.abs(pos.y - move.exitPos.y) < 1.1) return true
    if (bucket && this.wet && this.bot.entity.onGround && Math.abs(vel.y) < 0.12 && pos.xzDistanceTo(move.exitPos) < 0.45) {
      if (this.collected || (this.attempts > 0 && this.bot.heldItem?.name === 'water_bucket')) {
        this.collected = true
        if (this.previousItem != null && this.previousItem.name !== 'water_bucket') {
          const item = this.bot.inventory.items().find(item => item.type === this.previousItem?.type)
          if (item != null) await this.bot.equip(item, 'hand')
        }
        return true
      }
      const source = this.world.getBlock(move.exitPos.floored())
      if (source?.name !== 'water' || Number(source.getProperties().level) !== 0) throw new CancelError('Placed water source was removed')
      if (this.bot.heldItem?.name === 'bucket' && this.flightTicks - this.lastUse >= 6) {
        if (this.attempts >= 3) throw new CancelError('Server did not confirm water collection')
        this.lastUse = this.flightTicks; this.attempts++
        await this.useBucket(move.exitPos.offset(0, 0.5, 0), generation)
      }
    }
    if (!this.wet && this.bot.entity.onGround && this.flightTicks > 3) throw new CancelError('Water drop missed its landing')
    return false
  }
}

