/* eslint-disable @typescript-eslint/no-var-requires, @typescript-eslint/restrict-template-expressions */
import { Bot } from 'mineflayer'
import type { OptimizationMap } from '.'
import type { BuildableMoveProvider } from '../movements'
import { MovementProvider } from '../movements'
import { World } from '../world/worldInterface'
import { Move } from '../move'
import { BaseSimulator, BotcraftPhysics } from '@nxg-org/mineflayer-physics-util'
import { Climb } from '../movements/climb'
import { ClimbAwarePhysics } from '../climbablePhysics'

const debug = require('debug')
const log = debug('minecraft-pathfinding:Optimizer')
const logMerge = debug('minecraft-pathfinding:Optimizer:merge')

export abstract class MovementOptimizer {
  bot: Bot
  world: World
  sim: BaseSimulator

  public readonly mergeInteracts: boolean = true

  constructor (bot: Bot, world: World) {
    this.bot = bot
    this.world = world
    this.sim = new BaseSimulator(new ClimbAwarePhysics(bot.registry))
  }

  abstract identEndOpt (currentIndex: number, path: Move[]): number | Promise<number>

  /**
   * Select the move type that should represent the merged block.
   *
   * Default behavior keeps the start move's provider so existing optimizer/executor
   * mappings continue to work unchanged.
   *
   * For now, changing this here does not work. Do not use this to set a different movement provider.
   */
  protected getMergedMoveType (startIndex: number, endIndex: number, path: readonly Move[]): MovementProvider {
    return path[startIndex].moveType
  }

  /**
   * Build the merged move for the optimized span.
   *
   * Subclasses may override this when they need to swap in a different move type
   * or otherwise rewrite the resulting move object.
   */
  protected createMergedMove (startIndex: number, endIndex: number, path: readonly Move[]): Move {
    const startMove = path[startIndex]
    const endMove = path[endIndex]
    const mergedMoveType = this.getMergedMoveType(startIndex, endIndex, path)

    logMerge(`Merging ${endIndex - startIndex + 1} moves: [Index ${startIndex}] ${startMove.moveType.constructor.name} -> [Index ${endIndex}] ${endMove.moveType.constructor.name}`)
    logMerge(`Start Pos: ${startMove.entryPos}, End Pos: ${endMove.exitPos}`)

    const toBreak = [...startMove.toBreak]
    const toPlace = [...startMove.toPlace]
    let costSum = 0

    for (let i = startIndex + 1; i < endIndex; i++) {
      const intermediateMove = path[i]
      if (this.mergeInteracts) {
        toBreak.push(...intermediateMove.toBreak)
        toPlace.push(...intermediateMove.toPlace)
      }
      costSum += intermediateMove.cost
    }

    toBreak.push(...endMove.toBreak)
    toPlace.push(...endMove.toPlace)

    costSum += endMove.cost

    logMerge(`Merge complete. Total Cost: ${costSum.toFixed(2)}, Breaks: ${toBreak.length}, Places: ${toPlace.length}`)

    return new Move(
      startMove.x,
      startMove.y,
      startMove.z,
      toPlace,
      toBreak,
      endMove.remainingBlocks,
      costSum,
      mergedMoveType,
      startMove.entryPos,
      startMove.entryVel,
      endMove.exitPos,
      endMove.exitVel,
      startMove.parent
    )
  }

  mergeMoves (startIndex: number, endIndex: number, path: readonly Move[]): Move {
    return this.createMergedMove(startIndex, endIndex, path)
  }
}

export class Optimizer {
  optMap: OptimizationMap

  private pathCopy!: Move[]
  private currentIndex: number

  constructor (bot: Bot, world: World, optMap: OptimizationMap) {
    this.currentIndex = 0
    this.optMap = optMap
  }

  loadPath (path: Move[]): void {
    log('loadPath called. Initial path length: %d.', path.length)
    this.pathCopy = path
    this.currentIndex = 0
  }

  sanitize (): boolean {
    // eslint-disable-next-line @typescript-eslint/strict-boolean-expressions
    return !!this.pathCopy
  }

  async compute (): Promise<Move[]> {
    if (!this.sanitize()) {
      throw new Error('Optimizer not sanitized')
    }

    log(`compute() started. Iterating over path of length ${this.pathCopy.length}.`)

    while (this.currentIndex < this.pathCopy.length) {
      const move = this.pathCopy[this.currentIndex]
      const opts = this.optMap.get(move.moveType.constructor as BuildableMoveProvider)

      if (opts == null || opts.length === 0 || move.metadata?.waterLanding === true) {
        log(`[Index ${this.currentIndex}] No optimizer mapped for ${move.moveType.constructor.name}. Skipping.`)
        this.currentIndex++
        continue
      }

      let merged = false

      for (const opt of opts) {
        log(`[Index ${this.currentIndex}] Evaluating ${move.moveType.constructor.name} using ${opt.optimizer.constructor.name} (priority ${opt.priority})...`)
        const boundary = this.pathCopy.findIndex((candidate, index) => index > this.currentIndex && (candidate.moveType instanceof Climb || candidate.metadata?.waterLanding === true || candidate.metadata?.momentumEdge != null))
        const candidatePath = boundary === -1 ? this.pathCopy : this.pathCopy.slice(0, boundary)
        const newEnd = await opt.optimizer.identEndOpt(this.currentIndex, candidatePath)

        if (newEnd > this.currentIndex) {
          log(`[Index ${this.currentIndex}] Optimizer identified mergable sequence ending at index ${newEnd}.`)
          const newMove = opt.optimizer.mergeMoves(this.currentIndex, newEnd, this.pathCopy)
          newMove.optimizedExecutor = opt.optimizedExecutor

          // Splice the newly merged move into the array, replacing all intermediate moves
          this.pathCopy[this.currentIndex] = newMove
          this.pathCopy.splice(this.currentIndex + 1, newEnd - this.currentIndex)
          logMerge(`Spliced array. New path length: ${this.pathCopy.length}`)
          merged = true
          break
        }

        log(`[Index ${this.currentIndex}] Optimizer returned non-merge index ${newEnd}. Trying next candidate if available.`)
      }

      if (!merged) {
        log(`[Index ${this.currentIndex}] No optimizer merged this move ${move.moveType.constructor.name}. Skipping.`)
      }

      // Move to the next movement (which will be the movement directly after our merged block)
      this.currentIndex++
    }

    log('compute() finished. Final optimized path length: %d.', this.pathCopy.length)
    return this.pathCopy
  }

  makeResult (): Move[] {
    return this.pathCopy
  }
}

/* eslint-disable @typescript-eslint/no-var-requires, @typescript-eslint/restrict-template-expressions */
import { ControlStateHandler, EPhysicsCtx } from '@nxg-org/mineflayer-physics-util'
import { Vec3 } from 'vec3'
import { Move } from '../move'
import type { RayType } from '../../types'
import { BlockInfo } from '../world/cacheWorld'
import { MovementOptimizer } from './optimizer'
import { World } from '../world/worldInterface'
import { sumExclusionAreas } from '../movements/movement'
import type { ExclusionArea } from '../movements/exclusionZones'
import { COST_INF } from '../movements/costs'
import { clearBodySegment, supportedWalkSegment } from '../navigationGeometry'

import { AABB, AABBUtils } from '@nxg-org/mineflayer-util-plugin'
import { stateLookAt } from '../movements/movementUtils'

const debug = require('debug')
const log = debug('minecraft-pathfinding:optimizers')

/**
 * Walk the straight segment from `from` to `to` with a voxel traversal
 * (Amanatides & Woo) and return true as soon as a cell lands inside a HARD step
 * zone (summed weight >= COST_INF). Visiting exactly the cells the segment
 * crosses keeps the check correct (no skipped cells) and cheap.
 *
 * Only hard zones stop a straight-line merge; soft zones are a preference, not a
 * wall. Returns false immediately when there are no step areas.
 */
export function lineCrossesHardExclusion (world: World, from: Vec3, to: Vec3, areas: ExclusionArea[]): boolean {
  if (areas.length === 0) return false

  let x = Math.floor(from.x)
  let y = Math.floor(from.y)
  let z = Math.floor(from.z)
  const endX = Math.floor(to.x)
  const endY = Math.floor(to.y)
  const endZ = Math.floor(to.z)

  const dx = to.x - from.x
  const dy = to.y - from.y
  const dz = to.z - from.z

  const stepX = Math.sign(dx)
  const stepY = Math.sign(dy)
  const stepZ = Math.sign(dz)

  // The segment is parameterised by t in [0, 1]. tMax* is the t at which we next
  // cross a cell boundary on that axis; tDelta* is the t to cross one whole cell.
  const tDeltaX = stepX !== 0 ? Math.abs(1 / dx) : Infinity
  const tDeltaY = stepY !== 0 ? Math.abs(1 / dy) : Infinity
  const tDeltaZ = stepZ !== 0 ? Math.abs(1 / dz) : Infinity

  let tMaxX = stepX !== 0 ? (stepX > 0 ? x + 1 - from.x : from.x - x) / Math.abs(dx) : Infinity
  let tMaxY = stepY !== 0 ? (stepY > 0 ? y + 1 - from.y : from.y - y) / Math.abs(dy) : Infinity
  let tMaxZ = stepZ !== 0 ? (stepZ > 0 ? z + 1 - from.z : from.z - z) / Math.abs(dz) : Infinity

  // Cells to visit = Manhattan distance in cells + 1. A fixed loop count (rather
  // than tMax comparisons) keeps termination floating-point safe.
  const cells = Math.abs(endX - x) + Math.abs(endY - y) + Math.abs(endZ - z)

  for (let i = 0; i <= cells; i++) {
    if (sumExclusionAreas(areas, world.getBlockInfo(new Vec3(x, y, z))) >= COST_INF) return true

    if (tMaxX <= tMaxY && tMaxX <= tMaxZ) {
      x += stepX
      tMaxX += tDeltaX
    } else if (tMaxY <= tMaxZ) {
      y += stepY
      tMaxY += tDeltaY
    } else {
      z += stepZ
      tMaxZ += tDeltaZ
    }
  }
  return false
}

export class LandStraightAheadOpt extends MovementOptimizer {
  async identEndOpt (currentIndex: number, path: Move[]): Promise<number> {
    const startIndex = currentIndex
    const thisMove = path[currentIndex] // starting move
    const stepAreas = thisMove.moveType.settings.exclusionAreasStep

    let lastMove = path[currentIndex]
    let nextMove = path[++currentIndex]

    log(`[LandStraightAhead] Optimizing from index ${startIndex} (${thisMove.moveType.constructor.name})`)

    if (nextMove === undefined) {
      log('[LandStraightAhead] nextMove is undefined, aborting.')
      return --currentIndex
    }

    const orgY = thisMove.entryPos.y

    const orgPos = thisMove.entryPos.floored().translate(0.5, 0, 0.5) // ensure middle of block.
    const hW = 0.6 // ensure safety (larger than actual bot aabb)
    const uW = 0.4

    const bb = AABBUtils.getEntityAABBRaw({ position: orgPos, width: hW, height: 1.8 })
    const verts = bb.expand(0, -0.1, 0).toVertices()

    const verts1 = [
      orgPos.offset(-uW / 2, -0.6, -uW / 2),
      orgPos.offset(-uW / 2, -0.6, uW / 2),
      orgPos.offset(uW / 2, -0.6, -uW / 2),
      orgPos.offset(uW / 2, -0.6, uW / 2)
    ]

    while (lastMove.exitPos.y === orgY && nextMove.exitPos.y === orgY) {
      // Rays along the body's vertices can miss a block that enters through
      // the middle of a side. Keep the original turn in that case.
      if (!clearBodySegment(this.world, orgPos, nextMove.exitPos)) return --currentIndex
      if (!supportedWalkSegment(this.world, orgPos, nextMove.exitPos)) return --currentIndex
      if (!AABB.fromBlockPos(nextMove.entryPos).collides(AABB.fromBlockPos(nextMove.exitPos))) {
        log(`[LandStraightAhead] Index ${currentIndex}: AABB collision failed between entry and exit.`)
        return --currentIndex
      }

      if (nextMove === undefined) {
        log(`[LandStraightAhead] Index ${currentIndex}: nextMove became undefined.`)
        return --currentIndex
      }

      for (const vert of verts) {
        const offset = vert.minus(orgPos)
        const test1 = nextMove.exitPos.offset(0, orgY - nextMove.exitPos.y, 0)
        const test = test1.plus(offset)
        const dist = nextMove.exitPos.distanceTo(orgPos)

        const raycast0 = this.bot.world.raycast(
          vert,
          test.minus(vert).normalize(),
          dist,
          (block) => (!BlockInfo.replaceables.has(block.type) || BlockInfo.liquids.has(block.type) || BlockInfo.blocksToAvoid.has(block.type)) && block.shapes.length > 0
        ) as unknown as RayType | null

        const valid0 = (raycast0 == null) || raycast0.position.distanceTo(orgPos) > dist

        if (!valid0) {
          log(`[LandStraightAhead] Index ${currentIndex}: Block check raycast hit an obstacle at ${raycast0.position}.`)
          return --currentIndex
        }
      }

      let validCount = 0
      for (const vert of verts1) {
        const offset = vert.minus(orgPos)
        const test1 = nextMove.exitPos.offset(0, orgY - nextMove.exitPos.y, 0)
        const test = test1.plus(offset)
        const dist = nextMove.exitPos.distanceTo(orgPos)

        const raycast0 = (await this.bot.world.raycast(
          vert,
          test.minus(vert).normalize(),
          dist,
          (block) => BlockInfo.replaceables.has(block.type) || BlockInfo.liquids.has(block.type) || block.shapes.length === 0
        )) as unknown as RayType | null

        const valid0 = (raycast0 == null) || raycast0.shapes.length > 0 || raycast0.position.distanceTo(orgPos) > dist

        if (valid0) validCount++
      }

      // Require every foot-corner probe to be clear. Accepting a line when
      // only one probe succeeds lets the optimizer merge paths that skim block
      // edges and then snag the player's hitbox.
      if (validCount !== verts1.length) {
        log(`[LandStraightAhead] Index ${currentIndex}: Air check raycast failed (${validCount}/${verts1.length} corners clear).`)
        return --currentIndex
      }

      // Exclusion zones: do not straight-line the merge through a hard "keep out"
      // area the original route went around. Stop before this move if it would.
      if (lineCrossesHardExclusion(this.world, orgPos, nextMove.exitPos, stepAreas)) {
        log(`[LandStraightAhead] Index ${currentIndex}: straight line would cross a hard exclusion zone.`)
        return --currentIndex
      }

      if (++currentIndex >= path.length) {
        log('[LandStraightAhead] Reached end of path.')
        return --currentIndex
      }
      lastMove = nextMove
      nextMove = path[currentIndex]
    }

    log(`[LandStraightAhead] Y-level changed or loop ended naturally. Returning index ${currentIndex - 1}.`)
    return --currentIndex
  }
}

export class DropDownOpt extends MovementOptimizer {
  readonly mergeInteracts = false

  identEndOpt (currentIndex: number, path: Move[]): number | Promise<number> {
    const startIndex = currentIndex
    let lastMove = path[currentIndex]
    let nextMove = path[++currentIndex]

    log(`[DropDownOpt] Optimizing from index ${startIndex} (${lastMove.moveType.constructor.name})`)

    if (nextMove === undefined) return --currentIndex

    const firstPos = lastMove.exitPos
    const entryPos = lastMove.entryPos
    const direction = firstPos.minus(entryPos)

    let flag0 = false
    let flag1 = false
    while (currentIndex < path.length) {
      // Steering a merged descent aims directly at its final landing. A
      // sideways turn at a cave/stair exit must remain a separate move;
      // otherwise that diagonal cuts across the rim instead of descending.
      const offset = nextMove.exitPos.minus(entryPos)
      if (Math.abs(direction.x * offset.z - direction.z * offset.x) > 1e-6 ||
          direction.x * offset.x + direction.z * offset.z <= 0) return --currentIndex
      if (nextMove.exitPos.y > lastMove.exitPos.y) {
        log(`[DropDownOpt] Index ${currentIndex}: nextMove goes UP. Aborting.`)
        return --currentIndex
      }
      if (nextMove.toPlace.length > 0 || nextMove.toBreak.length > 0) {
        log(`[DropDownOpt] Index ${currentIndex}: nextMove requires block placement/breaking. Aborting.`)
        return --currentIndex
      }

      if (!AABB.fromBlockPos(nextMove.entryPos).collides(AABB.fromBlockPos(nextMove.exitPos))) {
        log(`[DropDownOpt] Index ${currentIndex}: AABB collision failed.`)
        return --currentIndex
      }

      if (nextMove.exitPos.xzDistanceTo(firstPos) < lastMove.exitPos.xzDistanceTo(firstPos)) {
        log(`[DropDownOpt] Index ${currentIndex}: Bot is moving closer to start position (looping). Aborting.`)
        return --currentIndex
      }

      const ctx = EPhysicsCtx.FROM_BOT(this.bot.physicsUtil.engine, this.bot)
      ctx.velocity.set(0, 0, 0)
      ctx.position.set(lastMove.entryPos.x, lastMove.entryPos.y, lastMove.entryPos.z)
      stateLookAt(ctx.state, nextMove.entryPos)
      ctx.state.control = ControlStateHandler.DEFAULT()
      ctx.state.control.forward = true
      ctx.state.control.sprint = true

      const bl0 = lastMove.moveType.getBlockInfo(nextMove.entryPos, 0, -1, 0)
      const bl1 = lastMove.moveType.getBlockInfo(nextMove.exitPos, 0, -1, 0)
      const bb0solid = bl0.physical || bl0.liquid
      const bb1solid = bl1.physical || bl1.liquid
      const blockBB0 = AABB.fromBlockPos(nextMove.entryPos.offset(0, -1, 0))
      const blockBB1 = AABB.fromBlockPos(nextMove.exitPos.offset(0, -1, 0))
      let flag = false
      let good = false

      this.sim.simulateUntil(
        (state, ticks) => {
          const pBB = AABBUtils.getPlayerAABB({ position: ctx.state.pos, width: 0.6, height: 1.8 })
          const collided =
            (pBB.collides(blockBB0) && bb0solid) || (pBB.collides(blockBB1) && bb1solid && (state.onGround || state.isInWater))

          if (collided) {
            good = true
            return true
          }

          if (state.pos.y < nextMove.entryPos.y && state.pos.y < nextMove.exitPos.y) flag = true

          if (flag) return (ticks > 0 && state.onGround) || state.isCollidedHorizontally
          else return false
        },
        () => {},
        (state) => stateLookAt(state, nextMove.exitPos),
        ctx,
        this.world,
        1000
      )

      if (!good) {
        log(`[DropDownOpt] Index ${currentIndex}: Physics simulation failed to reach target safely.`)
        return --currentIndex
      }

      if (ctx.state.isInWater) flag1 = true
      else if (flag1) {
        log(`[DropDownOpt] Index ${currentIndex}: Bot left water during drop. Aborting.`)
        return --currentIndex
      }

      if (nextMove.exitPos.y === nextMove.entryPos.y) {
        if (!bb1solid) {
          log(`[DropDownOpt] Index ${currentIndex}: Landing block is not solid.`)
          return --currentIndex
        }
        if (flag0) {
          log(`[DropDownOpt] Index ${currentIndex}: Flag0 triggered. Returning.`)
          return currentIndex
        } else flag0 = true
      }

      if (++currentIndex >= path.length) return --currentIndex
      lastMove = nextMove
      nextMove = path[currentIndex]
    }

    return --currentIndex
  }
}

export class ForwardJumpUpOpt extends MovementOptimizer {
  identEndOpt (currentIndex: number, path: Move[]): number | Promise<number> {
    const startIndex = currentIndex
    let lastMove = path[currentIndex]
    let nextMove = path[++currentIndex]

    log(`[ForwardJumpUpOpt] Optimizing from index ${startIndex} (${lastMove.moveType.constructor.name})`)

    if (lastMove.toPlace.length > 0) {
      log('[ForwardJumpUpOpt] Initial move places a block. Aborting.')
      return --currentIndex
    }

    if (nextMove === undefined) return --currentIndex

    // Carry an ascent only through a straight, clear continuation. A turn
    // needs its own supported landing before the next movement starts.
    const direction = lastMove.exitPos.minus(lastMove.entryPos); direction.y = 0; direction.normalize()
    const sameDirection = (move: Move): boolean => {
      const next = move.exitPos.minus(move.entryPos); next.y = 0
      return next.norm() > 0 && direction.dot(next.normalize()) > 0.999
    }
    const landing = lastMove.exitPos.clone()

    while (
      lastMove.exitPos.y === nextMove.exitPos.y &&
      lastMove.entryPos.y !== lastMove.exitPos.y &&
      nextMove.toPlace.length === 0 &&
      nextMove.toBreak.length === 0
    ) {
      if (!sameDirection(nextMove) || !clearBodySegment(this.world, landing, nextMove.exitPos)) return --currentIndex
      if (lastMove.toPlace.length > 1) {
        log(`[ForwardJumpUpOpt] Index ${currentIndex}: Places >1 blocks. Aborting.`)
        return --currentIndex
      }

      if (!AABB.fromBlockPos(nextMove.entryPos).collides(AABB.fromBlockPos(nextMove.exitPos))) {
        log(`[ForwardJumpUpOpt] Index ${currentIndex}: AABB collision failed.`)
        return --currentIndex
      }

      if (++currentIndex >= path.length) return --currentIndex
      lastMove = nextMove
      nextMove = path[currentIndex]
    }

    const firstPos = lastMove.exitPos

    while (
      lastMove.exitPos.y === nextMove.exitPos.y &&
      nextMove.exitPos.distanceTo(firstPos) <= 2 &&
      nextMove.toPlace.length === 0 &&
      nextMove.toBreak.length === 0
    ) {
      if (!sameDirection(nextMove) || !clearBodySegment(this.world, landing, nextMove.exitPos)) return --currentIndex
      if (nextMove.exitPos.y > firstPos.y) {
        log(`[ForwardJumpUpOpt] Index ${currentIndex}: nextMove Y is higher than firstPos Y. Aborting.`)
        return --currentIndex
      }
      if (++currentIndex >= path.length) return --currentIndex
      lastMove = nextMove
      nextMove = path[currentIndex]
    }

    log(`[ForwardJumpUpOpt] Optimized up to index ${currentIndex - 1}`)
    return --currentIndex
  }
}

import { Bot } from 'mineflayer'
import type { BuildableMoveProvider, MovementOptions } from '../movements'
import { MovementExecutor } from '../movements'
import { World } from '../world/worldInterface'
import { MovementOptimizer } from './optimizer'

export type BuildableMoveOptimizer = new (bot: Bot, world: World, settings: Partial<MovementOptions>) => MovementOptimizer

export interface RegisteredOptimizer {
  optimizer: MovementOptimizer
  optimizedExecutor?: MovementExecutor
  priority: number
  order: number
}

export type OptimizationMap = Map<BuildableMoveProvider, RegisteredOptimizer[]>

export class OptimizationRegistry {
  private readonly entries: OptimizationMap = new Map()
  private nextOrder = 0

  constructor (
    private readonly bot: Bot,
    private readonly world: World,
    private settings: Partial<MovementOptions>
  ) {}

  private createOptimizerInstance (
    Optimizer: BuildableMoveOptimizer | MovementOptimizer
  ): MovementOptimizer {
    if (Optimizer instanceof MovementOptimizer) {
      return Optimizer
    }

    return new Optimizer(this.bot, this.world, this.settings)
  }

  private addEntry (
    provider: BuildableMoveProvider,
    optimizer: BuildableMoveOptimizer | MovementOptimizer,
    priority: number,
    optimizedExecutor?: MovementExecutor
  ): void {
    const entry = {
      optimizer: this.createOptimizerInstance(optimizer),
      optimizedExecutor,
      priority,
      order: this.nextOrder++
    }

    const current = this.entries.get(provider)
    if (current == null) {
      this.entries.set(provider, [entry])
      return
    }

    current.push(entry)
  }

  setSettings (settings: Partial<MovementOptions>): void {
    this.settings = settings
    for (const entries of this.entries.values()) {
      for (const entry of entries) {
        if (entry.optimizedExecutor != null) Object.assign(entry.optimizedExecutor.settings, settings)
      }
    }
  }

  setOptimizer (
    provider: BuildableMoveProvider,
    optimizer: BuildableMoveOptimizer | MovementOptimizer,
    optimizedExecutor?: MovementExecutor,
    priority = 100
  ): void {
    this.entries.set(provider, [])
    this.addEntry(provider, optimizer, priority, optimizedExecutor)
  }

  addOptimizer (
    provider: BuildableMoveProvider,
    optimizer: BuildableMoveOptimizer | MovementOptimizer,
    optimizedExecutor?: MovementExecutor,
    priority = 100
  ): void {
    this.addEntry(provider, optimizer, priority, optimizedExecutor)
  }

  clear (): void {
    this.entries.clear()
  }

  snapshot (): OptimizationMap {
    const ret: OptimizationMap = new Map()

    for (const [provider, entries] of this.entries) {
      ret.set(
        provider,
        [...entries].sort((a, b) => {
          if (a.priority !== b.priority) return b.priority - a.priority
          return a.order - b.order
        })
      )
    }

    return ret
  }
}

