        BlockInfo.replaceables.has(b.type) || openWaterNames.has(b.name),
        BlockInfo.gravityBlocks.has(b.type),
        (climbable || BlockInfo.carpets.has(b.type)) && safe,
        safe,
        !climbable,
        false,
        climbable,
        height,
        BlockInfo.openable.has(b.type),
        b.position,
        b.type,
        b
      )
    } else {
      return new BlockInfo(
        BlockInfo.replaceables.has(b.type) || openWaterNames.has(b.name),
        false,
        !hazardNames.has(b.name),
        !hazardNames.has(b.name),
        false,
        openWaterNames.has(b.name) || b.name === 'lava' || Boolean(b.getProperties().waterlogged),
        climbableNames.has(b.name),
