  private async timeAsync<T>(label: string, task: () => T | Promise<T>): Promise<T> {
    if (!log.enabled) return await task()
    const start = performance.now()
    try {
      return await Promise.resolve().then(task)
    } finally {
      const duration = performance.now() - start
      log(`${label} took ${duration.toFixed(2)}ms.`)
      log(`pos: ${this.bot.entity.position}`)
      printBotControls(this.bot, log)
    }
  }

  private findNextCurrentIdx (move: Move, localPath: Move[], currentIndex: number, adding?: boolean | number): number {
    const endIdx = localPath.findIndex(
      (m, i) => i >= currentIndex && m.exitPos.distanceTo(move.exitPos) < 0.1
    )

    if (typeof adding === 'number') {
      if (Number.isFinite(adding) && adding > 0) currentIndex += adding
    } else {
      currentIndex = endIdx !== -1 ? endIdx + 1 : currentIndex + 1
    }

    return currentIndex
  }

  public async perform (path: Path, goal: goals.Goal, entry = 0, continueSwimming?: () => boolean): Promise<void> {
    const MAX_RECOVERY_DEPTH = 2

    if (entry > MAX_RECOVERY_DEPTH) {
      throw new NavigationError('recovery', 'Too many failures, exiting performing.')
    }

    const bot = this.bot
    const myExecutionId = this.bumpExecutionId()
    const localPath = path.path
    if (localPath.length === 0) return
    let currentIndex = 0

    const isAtGoal = (): boolean => {
      if (this.getCurrentExecutor()?.canInterrupt === false) return false
      const lastMove = localPath[localPath.length - 1]
      const pos = bot.entity.position
      if (!bot.entity.onGround && !this.host.world.getBlockInfo(pos).climbable && !(bot.entity as any).isInWater) return false
      // A partial water route ends a horizontal stroke, not a dive to the
      // search node's depth. Breathing raises the swimmer within that column.
      if (continueSwimming?.() === true && Math.floor(pos.x) === lastMove.x && Math.floor(pos.z) === lastMove.z) return true
      if (goal instanceof goals.GoalNear || goal instanceof goals.GoalFollowEntity) {
        return goal.isEnd({ ...lastMove, exitPos: pos, x: pos.x, y: pos.y, z: pos.z } as Move)
      }
      const actual = Move.startMove(lastMove.moveType, pos, bot.entity.velocity, lastMove.remainingBlocks)
      return goal.isEnd(actual)
    }

    this.setCurrentIndex(currentIndex)
    this.setCurrentPath(localPath)

    const { movements, optimizers } = this.host.getActiveMappings()

    let lastPathLength = -1
    let optSequence: Move[] = []
    let runnerStage: RunnerStage = 'idle'
    let pendingOptimize: Promise<void> | undefined
    let pendingInit: Promise<void> | undefined
    let tickCount = 0
    let settled = false
    let keptSwimming = false
    let recoveryInFlight = false
    const stopController = new ClimbExecutor(bot, this.host.world, this.host.defaultMoveSettings)

    let resolveCompletion!: () => void
    let rejectCompletion!: (err: unknown) => void

    let tickInFlight = false
    let lastProgressPosition = bot.entity.position.clone()
    let lastProgressAt = performance.now()
    let activeDig: BreakHandler | undefined
    let digDeadline = 0
    let collisionTicks = 0
    let progressMove: Move | undefined
    let bestMoveDistance = Infinity
    let productiveAt = lastProgressAt
    let stoppingAt: Vec3 | undefined
    const adjustStop = (target: Vec3): void => {
      const pos = bot.entity.position
      const distance = pos.xzDistanceTo(target)
      if (distance <= 0.08) {
        // Let ground friction finish the stop inside the accepted position.
        // Alternating full forward/back input here creates a small permanent
        // oscillation, especially when catch-up ticks update every frame.
        for (const control of ['forward', 'back', 'left', 'right'] as const) bot.setControlState(control, false)
      } else stopController.adjustPosition(target, 0.08)
      bot.setControlState('jump', false)
      bot.setControlState('sprint', false)
      const projected = pos.offset(bot.entity.velocity.x * 3, 0, bot.entity.velocity.z * 3)
      // A nearly stopped player with a server speed bonus can cross the whole
      // arrival tolerance in one full walking tap. Use a crouched correction
      // only for that final alignment, without changing the arrival tolerance.
      let precisionCorrection = false
      if (distance > 0.08 && distance < 0.3 && Math.hypot(bot.entity.velocity.x, bot.entity.velocity.z) < 0.025) {
        const physics = bot.physics as typeof bot.physics & { movementSpeedAttribute: string, sprintingUUID: string }
        const speed = bot.entity.attributes?.[physics.movementSpeedAttribute]
        // Exclude vanilla sprint, which the next walking tick removes, and
        // retain all server modifiers without mutating their original array.
        if (speed != null) precisionCorrection = getAttributeValue({
          value: speed.value,
          modifiers: speed.modifiers.filter(modifier => modifier.uuid !== physics.sprintingUUID)
        }) > 0.100001
      }
      bot.setControlState('sneak', precisionCorrection || !supportedWalkSegment(this.host.world, pos, projected))
    }

    const completion = new Promise<void>((resolve, reject) => {
      resolveCompletion = resolve
      rejectCompletion = reject
    })

    const executorSafeReset = (executor?: MovementExecutor): void => {
      executor?.reset()
    }

    const finish = async (completed = false): Promise<void> => {
      if (settled) return
      settled = true
      bot.off('physicsTick', moveListener)
      if (this.getCurrentExecutionId() === myExecutionId) {
        keptSwimming = completed && continueSwimming?.() === true
        await this.timeAsync('finish cleanup', async () => await this.host.cleanupBot(false, keptSwimming))
      }
      resolveCompletion()
    }

    const fail = async (err: unknown): Promise<void> => {
      if (settled) return
      settled = true
      bot.off('physicsTick', moveListener)
      if (this.getCurrentExecutionId() === myExecutionId) {
        const interaction = this.getCurrentExecutor()?.cI
        if (interaction instanceof BreakHandler) {
          try {
            await interaction._abort(bot)
          } catch (abortErr) {
            log('Failed to abort mining after movement failure: %O', abortErr)
          }
        }
      }
      rejectCompletion(err)
    }

    const scheduleRecovery = (rawMove: Move): void => {
      if (settled || this.getCurrentExecutionId() !== myExecutionId || recoveryInFlight) return
      recoveryInFlight = true

      void (async () => {
        try {
          await this.recovery(rawMove, path, goal, entry)
          await finish()
        } catch (recoveryErr) {
          await fail(recoveryErr)
        }
      })()
    }

    const handleExecutionError = async (err: unknown): Promise<void> => {
      if (settled || this.getCurrentExecutionId() !== myExecutionId) return
      log(`Error: ${err}`)

      if (err instanceof AbortError) {
        executorSafeReset(this.getCurrentExecutor())
        await finish()
        return
      }

      if (err instanceof ManualResetError) {
        executorSafeReset(this.getCurrentExecutor())
        await finish()
        return
      }

      if (err instanceof ResetError) {
        executorSafeReset(this.getCurrentExecutor())
        await finish()
        return
      }

      if (err instanceof CancelError) {
        executorSafeReset(this.getCurrentExecutor())

        if (err.message.includes('superseded')) {
          await finish()
          return
        }

        const rawMove = localPath[currentIndex]
        if (rawMove == null) {
          throw err
        }

        scheduleRecovery(rawMove)
        return
      }

      await fail(err)
      throw err
    }

    const beginOptimization = (): void => {
      if (pendingOptimize != null) return

      runnerStage = 'optimize'
      const optimizer = new Optimizer(bot, this.host.world, optimizers)
      optimizer.loadPath(localPath.slice(currentIndex))

      pendingOptimize = this.timeAsync('optimizer.compute', async () => await optimizer.compute()).then(
        (result) => {
          if (settled) return
          if (this.getCurrentExecutionId() !== myExecutionId) return

          optSequence = result
          lastPathLength = localPath.length
          pendingOptimize = undefined
          if (runnerStage === 'optimize') runnerStage = 'idle'
          // Prime a verified momentum flight before another tick consumes its
          // incoming speed. Other executors retain their physics-tick boundary.
          if (localPath[currentIndex]?.moveType.constructor.name === 'MomentumJump') moveListener()
        },
        (err) => {
          pendingOptimize = undefined
          void fail(err)
        }
      )
    }

    const prepareNextMove = async (): Promise<boolean> => {
      while (currentIndex < localPath.length) {
        if (localPath.length !== lastPathLength) {
          beginOptimization()
          return false
        }

        if (pendingOptimize != null) return false

        const rawMove = localPath[currentIndex]
        const move = optSequence.find((m) => m.hash === rawMove.hash) ?? rawMove
        let executor: MovementExecutor | undefined

        if (rawMove !== move) {
          executor = move.optimizedExecutor
        }
        if (executor == null) {
          executor = movements.get(move.moveType.constructor as BuildableMoveProvider)
        }
        if (executor == null) {
          throw new Error('No executor for movement type ' + move.moveType.constructor.name)
        }

        const previousMove = this.getCurrentMove() ?? localPath[currentIndex - 1]
        // Consecutive water strokes must retain forward/sprint. Clearing them
        // between blocks exits the swim pose before the next stroke can start.
        const waterStroke = (candidate: Move | undefined): boolean => candidate != null &&
          /^(Forward|Diagonal)$/.test(candidate.moveType.constructor.name) &&
          candidate.toPlace.length === 0 && candidate.toBreak.length === 0 &&
          this.host.world.getBlockInfo(candidate.exitPos).liquid
        const resumingSwim = currentIndex <= 1 && canContinueSwimming(bot)
        const keepSwimming = (bot.entity as any).isInWater === true &&
          ((waterStroke(move) && (waterStroke(previousMove) || resumingSwim)) ||
            (resumingSwim && move.moveType.constructor.name === 'IdleMovement'))
        const keepClimbing = previousMove?.moveType.constructor.name === 'Climb' &&
          move.moveType.constructor.name === 'Climb' &&
          this.host.world.getBlockInfo(bot.entity.position).climbable &&
          move.exitPos.y > move.entryPos.y && bot.getControlState('jump')
        this.setCurrentMove(move)
        this.setCurrentExecutor(executor)
        this.setCurrentIndex(currentIndex)
        this.setCurrentPath(localPath)

        log(`[ExecID %d] Entering movement ${move.moveType.constructor.name}. Idx: ${this.getCurrentIndex()}, start: ${move.entryPos}, end: ${move.exitPos}`, myExecutionId)
        tickCount = 0

        await this.timeAsync('prepare cleanup', async () => await this.host.cleanupBot(false, keepSwimming || keepClimbing))
        if (settled || this.getCurrentExecutionId() !== myExecutionId) return false
        executor.loadMove(move)

        if (executor.isAlreadyCompleted(move, tickCount, goal)) {
          const nextIndex = this.findNextCurrentIdx(move, localPath, currentIndex)
          if (nextIndex < localPath.length || isAtGoal()) {
            currentIndex = nextIndex
            this.setCurrentIndex(currentIndex)
            continue
          }
        }

        runnerStage = 'align'
        return true
      }

      return false
    }

    const runMovementTick = async (): Promise<void> => {
      if (settled) return
      if (this.getCurrentExecutionId() !== myExecutionId) {
        await finish()
        return
      }

      try {
        while (!settled) {
          if (this.getCurrentExecutionId() !== myExecutionId) {
            await finish()
            return
          }

          // The actual supported position is authoritative. A predicted move
          // completion can otherwise leave a stopped bot waiting at its goal.
          const active = this.getCurrentMove() ?? localPath[localPath.length - 1]
          const atGoal = isAtGoal()
          const routeConsumed = currentIndex >= localPath.length
          if ((atGoal || routeConsumed) && bot.entity.onGround &&
              (routeConsumed || (active?.toBreak.length === 0 && active.toPlace.length === 0))) {
            const target = localPath[localPath.length - 1].exitPos
            const speed = bot.entity.velocity.offset(0, -bot.entity.velocity.y, 0).norm()
            const needsCentering = (goal instanceof goals.GoalBlock || !atGoal) && bot.entity.position.xzDistanceTo(target) > 0.08
            if (speed > 0.025 || needsCentering) {
              stoppingAt = target
              adjustStop(target)
              return
            }
            await finish()
            return
          }
          stoppingAt = undefined

          if (runnerStage === 'idle') {
            const hasWork = await prepareNextMove()
            if (!hasWork) {
              if (pendingOptimize == null) {
                log(`execution ${myExecutionId} completed at ${bot.entity.position}`)
                await finish(true)
                return
              }
              return
            }
            continue
          }

          if (runnerStage === 'optimize') {
            return
          }

          const move = this.getCurrentMove()
          const executor = this.getCurrentExecutor()

          if (move == null || executor == null) {
            throw new Error('Movement runner lost its current move or executor.')
          }

          if (runnerStage === 'align') {
            this.check()

            const aligned = await this.timeAsync(
              `align ${move.moveType.constructor.name}`,
              async () => await executor.align(move, tickCount, goal)
            )
            if (settled || this.getCurrentExecutionId() !== myExecutionId) return
            tickCount++

            if (aligned) {
              runnerStage = 'init'
              pendingInit = this.timeAsync(
                `performInit ${move.moveType.constructor.name}`,
                async () => await executor._performInit(move, currentIndex, localPath)
              )
              pendingInit.then(
                () => {
                  if (settled) return
                  if (this.getCurrentExecutionId() !== myExecutionId) return
                  tickCount = 0
                  runnerStage = 'perform'
                  pendingInit = undefined
                },
                (err) => {
                  pendingInit = undefined
                  void handleExecutionError(err).catch((handleErr) => {
                    void fail(handleErr)
                  })
                }
              )
              continue
            }

            return
          }

          if (runnerStage === 'init') {
            return
          }

          if (runnerStage === 'perform') {
            this.check()

            const adding = await this.timeAsync(
              `performPerTick ${move.moveType.constructor.name}`,
              async () => await executor._performPerTick(move, tickCount, currentIndex, localPath)
            )
            if (settled || this.getCurrentExecutionId() !== myExecutionId) return
            tickCount++

            if (adding) {
              const nextIndex = this.findNextCurrentIdx(move, localPath, currentIndex, adding)
              if (nextIndex >= localPath.length && !isAtGoal()) return
              currentIndex = nextIndex
              this.setCurrentIndex(currentIndex)
              runnerStage = 'idle'
              this.setCurrentMove(undefined)
              this.setCurrentExecutor(undefined)
              tickCount = 0
              continue
            }

            return
          }
        }
      } catch (err) {
        if (settled || this.getCurrentExecutionId() !== myExecutionId) return
        log(`Error: ${err}`)
        if (err instanceof AbortError) {
          executorSafeReset(this.getCurrentExecutor())
          await finish()
          return
        }

        if (err instanceof ManualResetError) {
          executorSafeReset(this.getCurrentExecutor())
          await finish()
          return
        }

        if (err instanceof ResetError) {
          executorSafeReset(this.getCurrentExecutor())
          await finish()
          return
        }

        if (err instanceof CancelError) {
          executorSafeReset(this.getCurrentExecutor())

          if (err.message.includes('superseded')) {
            await finish()
            return
          }

          const rawMove = localPath[currentIndex]
          if (rawMove == null) {
            throw err
          }

          scheduleRecovery(rawMove)
          return
        }

        await fail(err)
        throw err
      }
    }

    const moveListener = (): void => {
      if (settled) return
      // Superseded optimizers can still be pending. Retire their tick listener
      // before the stage guard and watchdog so they cannot stall a newer route.
      if (this.getCurrentExecutionId() !== myExecutionId) {
        // A nested recovery owns its own watchdog. The parent must wait for
        // its result instead of finishing the outer goto and stopping the child.
        if (!recoveryInFlight) void finish()
        return
      }
      // Catch-up physics can run several ticks before an async movement call
      // returns. Recompute braking each tick instead of holding the same
      // correction through the target and oscillating on both sides of it.
      if (stoppingAt != null && tickInFlight && bot.entity.onGround) adjustStop(stoppingAt)
      const interaction = this.getCurrentExecutor()?.cI
      const block = bot.targetDigBlock
      const now = performance.now()
      if (interaction instanceof BreakHandler && interaction.isPerforming && block?.position.equals(interaction.vec)) {
        if (activeDig !== interaction) {
          activeDig = interaction
          // Mining is useful progress while stationary. Bound it by the real
          // dig time with the equipped tool plus the normal response allowance.
          const expected = bot.digTime(block)
          digDeadline = now + (Number.isFinite(expected) ? Math.max(0, expected) : 0) + this.host.defaultMoveSettings.movementTimeoutMs
        }
        if (now >= digDeadline) {
          void fail(new Error(`Movement stalled: mining ${block.name} did not finish within its dig time and movement timeout.`))
          return
        }
        lastProgressAt = now
      } else activeDig = undefined
      const move = this.getCurrentMove()
      const horizontalStroke = (bot.entity as any).isInWater === true && move != null &&
        Math.abs(move.exitPos.y - move.entryPos.y) < 0.1
      if (move !== progressMove) {
        progressMove = move
        bestMoveDistance = Infinity
        productiveAt = now
      }
      if (move != null && interaction == null && (runnerStage === 'align' || runnerStage === 'perform') &&
          this.getCurrentExecutor()?.canInterrupt !== false) {
        const remaining = horizontalStroke ? bot.entity.position.xzDistanceTo(move.exitPos) : bot.entity.position.distanceTo(move.exitPos)
        if (remaining < bestMoveDistance - 0.08) {
          bestMoveDistance = remaining
          productiveAt = now
        } else if (now - productiveAt >= Math.max(2000, this.host.defaultMoveSettings.movementTimeoutMs * 2)) {
          // Walking in circles and repeating failed jumps are motion, but do
          // not advance this movement. Replan instead of resetting forever.
          void fail(new NavigationError('stalled', 'Movement stalled: repeated motion without advancing to the waypoint.'))
          return
        }
      } else productiveAt = now
      const displacement = horizontalStroke
        ? bot.entity.position.xzDistanceTo(lastProgressPosition)
        : bot.entity.position.distanceTo(lastProgressPosition)
      if (displacement >= 0.08) {
        lastProgressPosition = bot.entity.position.clone()
        lastProgressAt = now
        collisionTicks = 0
      } else if (now - lastProgressAt >= this.host.defaultMoveSettings.movementTimeoutMs) {
        void fail(new NavigationError('stalled', 'Movement stalled: no progress within the movement timeout.'))
        return
      }
      if ((bot.entity as any).isCollidedHorizontally && interaction == null &&
          this.getCurrentExecutor()?.canInterrupt !== false && (bot.entity.onGround || horizontalStroke) &&
          (bot.getControlState('forward') || bot.getControlState('back') || bot.getControlState('left') || bot.getControlState('right'))) {
        if (++collisionTicks >= 12) {
          void fail(new NavigationError('stalled', 'Movement stalled: blocked by a wall or corner.'))
          return
        }
      } else collisionTicks = 0
      if (tickInFlight || recoveryInFlight || runnerStage === 'optimize' || pendingOptimize != null || runnerStage === 'init' || pendingInit != null) {
        return
      }

      tickInFlight = true
      void runMovementTick().catch((err) => {
        void fail(err)
      }).finally(() => {
        tickInFlight = false
        if (settled && !keptSwimming && this.getCurrentExecutionId() === myExecutionId) {
          bot.clearControlStates()
          if (bot.entity.onGround) bot.setControlState('sneak', needsWalkSneak(this.host.world, bot.entity.position, bot.entity.velocity))
        }
      })
    }

    this.cancelActive = finish
    beginOptimization()

    bot.prependListener('physicsTick', moveListener)

    try {
      await completion
    } finally {
      bot.off('physicsTick', moveListener)
      if (this.cancelActive === finish) delete this.cancelActive
    }
  }

  public async recovery (move: Move, path: Path, goal: goals.Goal, entry = 0): Promise<void> {
    const bot = this.bot
    const revision = this.host.navigationRevision
    const canceled = (): boolean => this.host.navigationRevision !== revision || this.host.abortCalculation || this.getResetReason() === 'goalReassignment'
    log(`recovery ${entry} for ${move.moveType.constructor.name}`)

    bot.clearControlStates()
    const landingDeadline = performance.now() + this.host.defaultMoveSettings.movementTimeoutMs
    while (!bot.entity.onGround && !(bot.entity as any).isInWater) {
      if (canceled()) return
      if (performance.now() >= landingDeadline) throw new Error('Recovery failed: no landing within the movement timeout.')
      await this.host.waitForTick()
    }

    bot.emit('enteredRecovery', entry)
    await this.timeAsync('recovery cleanup', async () => await this.host.cleanupBot())
    if (canceled()) return

    const ind = path.path.findIndex((m) => m.entryPos.distanceTo(move.entryPos) < 0.1)
    if (ind === -1) {
      log(' recovery failed: could not find move in path')
      return
    }

    let newGoal: goals.Goal
    const pos = bot.entity.position
    let bad = false

    let nextMove = [...path.path].sort((a, b) => a.entryPos.distanceTo(pos) - b.entryPos.distanceTo(pos))[0] as Move | undefined
    if (nextMove == null || path.path.indexOf(nextMove) < ind) {
      bad = true
    } else if (path.path.indexOf(nextMove) === ind) {
      nextMove = path.path[ind + 1]
    }

    const no = entry > 5 || bad
    if (no || nextMove == null) {
      newGoal = goal
    } else {
      newGoal = goals.GoalBlock.fromVec(nextMove.vec)
    }

    const path1 = await this.timeAsync(
      'recovery pathfinding',
      async () => await this.host.getPathFromToRaw(bot.entity.position, EMPTY_VEC, newGoal)
    )
    if (canceled()) return

    if (path1 === null) {
      log(' recovery pathfinding returned null')
      bot.emit('exitedRecovery', entry)
    } else if (no || nextMove == null) {
      log(' executing full recovery path')
      bot.emit('exitedRecovery', entry)
      await this.perform(path1, goal, entry + 1)
    } else {
      log(' executing partial recovery path')
      await this.perform(path1, newGoal, entry + 1)
      if (canceled()) return

      // Recovery reached nextMove's destination, which may be several steps
      // beyond the failed move. Do not replay those steps from their old
      // takeoffs (especially an upper stair after we have already descended).
      path.path.splice(0, path.path.indexOf(nextMove) + 1)

      log(' continuing original goal after partial recovery')
      bot.emit('exitedRecovery', entry)
      if (path.path.length > 0) await this.perform(path, goal, 0)
    }
  }

  private check (): void {
    const resetReason = this.getResetReason()
    if (resetReason != null) {
      throw new ResetError(resetReason)
    }
  }
}

