] as Array<[BuildableMoveProvider, BuildableMoveOptimizer]>

const DEFAULT_SETUP = new Map(DEFAULT_PROVIDER_EXECUTORS)
const DEFAULT_OPTIMIZATION = new Map(DEFAULT_OPTIMIZERS)

type PathInfo = Path
type PathGenerator = AsyncGenerator<PathGeneratorResult, PathGeneratorResult | null, unknown>
interface PathGeneratorResult {
  result: PathInfo
  astarContext: AAStar<Move, MovementHandler>
}

interface RouteOpts {
  /** Try movement without block edits first; only an exhausted search permits edits. */
  preferExistingTerrain?: boolean
}

interface PerformOpts extends RouteOpts {
  /** Commit short excavated routes during gathering, with the caller's exclusions. */
  allowMiningPrefix?: boolean
  errorOnReset?: boolean
  errorOnAbort?: boolean
}

export class ThePathfinder {
  public get navigationRevision (): number { return this.goalRequestId }
  private readonly rejectedPlacements = new Set<string>()
  private readonly traversalMemory = new TraversalMemory()

  rejectPlacement (pos: Vec3, revision: number): void {
    if (revision === this.goalRequestId && this.currentGotoGoal != null) this.rejectedPlacements.add(pos.floored().toString())
  }
  astar: AStar | null
  world: World
  movements: ExecutorMap
  defaultMoveSettings: MovementOptions
  pathfinderSettings: PathfinderOptions
  private readonly optimizerRegistry: OptimizationRegistry

  private executeTask: Task<void, void> = Task.createDoneTask()
  private goalRequestId = 0
  private readonly waiters = new Set<() => void>()
  private readonly disposeListeners: Array<() => void> = []
  private wakeGoal?: () => void
  private disposed = false
  private pendingReset?: Promise<void>
  public abortCalculation = false

  private currentGotoGoal?: goals.Goal
  private _currentProducer?: PathProducer
  private readonly executionRunner: PathExecutor

  private _gotoMappings?: {
    movements: ExecutorMap
    optimizers: OptimizationMap
  }

  public get currentAStar (): AStar | undefined {
    return this._currentProducer?.getAstarContext()
  }

  public get currentProducer (): PathProducer | undefined {
    return this._currentProducer
  }

  private snapshotMappings (): {
    movements: ExecutorMap
    optimizers: OptimizationMap
  } {
    return {
      movements: new Map(this.movements),
      optimizers: this.optimizerRegistry.snapshot()
    }
  }

  private get activeMappings (): {
    movements: ExecutorMap
    optimizers: OptimizationMap
  } {
    return this._gotoMappings ?? this.snapshotMappings()
  }

  public getActiveMappings (): ExecutionMappings {
    return this.activeMappings
  }

  public get isPathing (): boolean {
    return !this.executeTask.done
  }

  public get currentGoal (): Readonly<goals.Goal> | undefined {
    return this.currentGotoGoal
  }

  public get resetReason (): ResetReason | undefined {
    return this.executionRunner.getResetReason()
  }

  public get currentIndex (): number {
    return this.executionRunner.getCurrentIndex()
  }

  public get currentPath (): Move[] | undefined {
    return this.executionRunner.getCurrentPath()
  }

  public set currentPath (path: Move[] | undefined) {
    this.executionRunner.setCurrentPath(path)
  }

  public get currentMove (): Move | undefined {
    return this.executionRunner.getCurrentMove()
  }

  public set currentMove (move: Move | undefined) {
    this.executionRunner.setCurrentMove(move)
  }

  public get currentExecutor (): MovementExecutor | undefined {
    return this.executionRunner.getCurrentExecutor()
  }

  public set currentExecutor (executor: MovementExecutor | undefined) {
    this.executionRunner.setCurrentExecutor(executor)
  }

  public clearResetReason (): void {
    this.executionRunner.clearResetReason()
  }

  reconstructPath = reconstructPath

  constructor (private readonly bot: Bot, opts: HandlerOpts = {}) {
    this.world = opts.world ?? new CacheSyncWorld(bot, bot.world)
    const moveSettings: MovementOptions = {} as MovementOptions
    const pathfinderSettings: PathfinderOptions = {} as PathfinderOptions
    const optimizers = opts.optimizers ?? DEFAULT_OPTIMIZATION
    const moveSetup = opts.movements ?? DEFAULT_SETUP

    Object.assign(moveSettings, buildMovementOptions(opts.moveSettings))
    Object.assign(pathfinderSettings, { ...DEFAULT_PATHFINDER_OPTS, ...opts.pathfinderSettings })

    const moves = new Map<BuildableMoveProvider, MovementExecutor>()
    for (const [providerType, ExecutorType] of moveSetup) {
      moves.set(providerType, new ExecutorType(bot, this.world, moveSettings))
    }

    this.optimizerRegistry = new OptimizationRegistry(bot, this.world, moveSettings)
    for (const [providerType, ExecutorType] of optimizers) {
      this.optimizerRegistry.setOptimizer(providerType, new ExecutorType(bot, this.world, moveSettings))
    }
    this.movements = moves
    this.defaultMoveSettings = moveSettings
    this.pathfinderSettings = pathfinderSettings
    this.astar = null
    this.executionRunner = new PathExecutor(this.bot, this)

    this.setupListeners()
    log('Pathfinder initialized.')
  }

  setExecutor (provider: BuildableMoveProvider, Executor: BuildableMoveExecutor | MovementExecutor): void {
    if (Executor instanceof MovementExecutor) {
      this.movements.set(provider, Executor)
    } else {
      this.movements.set(provider, new Executor(this.bot, this.world, this.defaultMoveSettings))
    }
  }

  setOptimizer (
    provider: BuildableMoveProvider,
    Optimizer: BuildableMoveOptimizer | MovementOptimizer,
    Executor?: BuildableMoveExecutor | MovementExecutor,
    priority = 100
  ): void {
    const optimizer = Optimizer instanceof MovementOptimizer
      ? Optimizer
      : new Optimizer(this.bot, this.world, this.defaultMoveSettings)

    const optimizedExecutor = Executor == null
      ? undefined
      : Executor instanceof MovementExecutor
        ? Executor
        : new Executor(this.bot, this.world, this.defaultMoveSettings)

    this.optimizerRegistry.setOptimizer(provider, optimizer, optimizedExecutor, priority)
  }

  addOptimizer (
    provider: BuildableMoveProvider,
    Optimizer: BuildableMoveOptimizer | MovementOptimizer,
    Executor?: BuildableMoveExecutor | MovementExecutor,
    priority = 100
  ): void {
    const optimizer = Optimizer instanceof MovementOptimizer
      ? Optimizer
      : new Optimizer(this.bot, this.world, this.defaultMoveSettings)

    const optimizedExecutor = Executor == null
      ? undefined
      : Executor instanceof MovementExecutor
        ? Executor
        : new Executor(this.bot, this.world, this.defaultMoveSettings)

    this.optimizerRegistry.addOptimizer(provider, optimizer, optimizedExecutor, priority)
  }

  setMoveOptions (settings: Partial<MovementOptions>): void {
    this.defaultMoveSettings = buildMovementOptions({ ...this.defaultMoveSettings, ...settings })
    this.optimizerRegistry.setSettings(this.defaultMoveSettings)
    for (const [, executor] of this.movements) {
      executor.settings = this.defaultMoveSettings
    }
    installLowCeilingJumps(this.bot, this.defaultMoveSettings.allowLowCeilingJumps)
  }

  setOptions (settings: Partial<PathfinderOptions>): void {
    this.pathfinderSettings = Object.assign({}, DEFAULT_PATHFINDER_OPTS, this.pathfinderSettings, settings)
  }

  dropMovment (provider: BuildableMoveProvider): void {
    this.movements.delete(provider)
  }

  dropMovement (provider: BuildableMoveProvider): void {
    this.dropMovment(provider)
  }

  dropAllMovements (): void {
    this.movements.clear()
  }

  async cancel (): Promise<void> {
    log('User cancelled pathfinding.')
    this.goalRequestId++
    await this.interrupt(this.defaultMoveSettings.movementTimeoutMs, true, 'goalReassignment')
  }

  async stop (): Promise<void> {
    await this.cancel()
    await this.executeTask.promise
    this.bot.clearControlStates()
  }

  async destroy (): Promise<void> {
    if (this.disposed) return
    this.disposed = true
    for (const dispose of this.disposeListeners.splice(0)) dispose()
    await this.stop()
    this.world.dispose?.()
  }

  async waitForTick (): Promise<void> {
    if (this.abortCalculation || this.disposed) return
    await new Promise<void>((resolve) => {
      const timer = setTimeout(finish, 1000)
      const bot = this.bot
      const waiters = this.waiters
      function finish (): void {
        clearTimeout(timer)
        bot.off('physicsTick', finish)
        bot.off('end', finish)
        waiters.delete(finish)
        resolve()
      }
      this.waiters.add(finish)
      bot.once('physicsTick', finish)
      bot.once('end', finish)
    })
  }

  private async waitForRetry (delay: number, update: Promise<void>): Promise<void> {
    if (this.resetReason === 'goalReassignment' || this.disposed) return
    await new Promise<void>(resolve => {
      const finish = (): void => {
        clearTimeout(timer)
        this.bot.off('blockUpdate', finish)
        this.bot.off('chunkColumnLoad', finish)
        this.waiters.delete(finish)
        resolve()
      }
      const timer = setTimeout(finish, delay)
      this.waiters.add(finish)
      this.bot.once('blockUpdate', finish)
      this.bot.once('chunkColumnLoad', finish)
      void update.then(finish)
    })
  }

  async interrupt (timeout = this.defaultMoveSettings.movementTimeoutMs, cancelCalculation = true, reasonStr?: ResetReason): Promise<void> {
    log('Interrupt called. Cancel Calculation: %s. %s', cancelCalculation, reasonStr)
    this.abortCalculation = cancelCalculation
    this.executionRunner.setResetReason(reasonStr)
    this.wakeGoal?.()
    for (const wake of [...this.waiters]) wake()

    const currentExecutor = this.currentExecutor
    const currentMove = this.currentMove
    const reason = reasonStr ? ResetError.fromReason(reasonStr) : undefined
    const abort = currentExecutor != null && currentMove != null
      ? currentExecutor.abort(currentMove, { timeout, reason })
      : Promise.resolve()
    await this.executionRunner.cancelExecution()
    currentExecutor?.reset()
    await abort
  }

  reset (reason: ResetReason, cancelTimeout = this.defaultMoveSettings.movementTimeoutMs): Promise<void> {
    if (this.pendingReset != null) return this.pendingReset
    const pending = Promise.resolve().then(async () => {
      log('Reset triggered due to: %s', reason)
      this.bot.emit('resetPath', reason)
      await this.interrupt(cancelTimeout, true, reason)
    })
    this.pendingReset = pending
    void pending.finally(() => { if (this.pendingReset === pending) this.pendingReset = undefined }).catch(() => {})
    return pending
  }

  setupListeners (): void {
    let memoryDimension = this.bot.game.dimension
    let memoryCell: string | undefined
    const clearMemory = (): void => { this.traversalMemory.clear(); memoryCell = undefined }
    const rememberGround = (): void => {
      if (this.bot.game.dimension !== memoryDimension) {
        clearMemory()
        memoryDimension = this.bot.game.dimension
      }
      const entity = this.bot.entity
      if (entity == null || (entity as any).isInWater || (entity as any).isInLava ||
          (!entity.onGround && !(this.currentMove?.moveType instanceof Climb))) return
      // Observe physics without reading/populating the world's block cache on
      // every tick. The corridor tolerates edge offsets; planning revalidates
      // support, headroom and liquids before it can reuse any of these hints.
      const position = entity.position
      const cell = position.floored().toString()
      if (cell === memoryCell) return
      memoryCell = cell
      this.traversalMemory.remember(position)
    }
    this.bot.on('physicsTick', rememberGround)
    this.bot.on('respawn', clearMemory)
    rememberGround()
    this.disposeListeners.push(() => {
      this.bot.off('physicsTick', rememberGround)
      this.bot.off('respawn', clearMemory)
      clearMemory()
    })
    const blockAbort = new AbortController()
    const acknowledgedEdits = new Map<string, number>()
    const rememberEdit = (_old: Block | null, block: Block | null): void => {
      if (block == null) return
      const key = block.position.toString()
      if (this.updateMatchesWanted(block)) {
        acknowledgedEdits.set(key, block.stateId)
        if (acknowledgedEdits.size > 256) acknowledgedEdits.delete(acknowledgedEdits.keys().next().value!)
      } else acknowledgedEdits.delete(key)
    }
    const clearEdits = (): void => { acknowledgedEdits.clear() }
    this.bot.on('blockUpdate', rememberEdit)
    this.bot.on('goalSet', clearEdits)
    const disposeBlockUpdateListener = handleSettledBlockEvent(
      this.bot,
      async (oldBlock: Block | null, newBlock: Block | null, settledBlock: Block | null) => {
        // log(
        //   'settled block update',
        //   oldBlock?.name,
        //   oldBlock?.position,
        //   newBlock?.name,
        //   newBlock?.position,
        //   settledBlock?.name,
        //   settledBlock?.position
        // )

        const currentPath = this.currentPath
        if (oldBlock == null || settledBlock == null) return
        if (currentPath == null) return
        if (oldBlock.type === settledBlock.type) return // break in progress.
        // An acknowledged dig may settle after execution has switched from
        // its prefix to the retained tail. It still belongs to this route.
        const acknowledged = acknowledgedEdits.get(settledBlock.position.toString())
        if (acknowledged === settledBlock.stateId) return
        if (!this.isPositionNearPath(oldBlock.position)) return
        if (settledBlock == null) return
        if (this.updateMatchesWanted(settledBlock, currentPath)) return

        log('Block update near path detected, resetting...')
        await this.reset('blockUpdate')
      },
      {
        settleMs: 75,
        timeoutMs: 250,
        signal: blockAbort.signal
      }
    )
    this.disposeListeners.push(() => {
      blockAbort.abort()
      disposeBlockUpdateListener()
      this.bot.off('blockUpdate', rememberEdit)
      this.bot.off('goalSet', clearEdits)
    })

    const onChunkLoad = (chunk: Vec3): void => {
      const astarContext = this.currentAStar
      if (astarContext == null) return
      const cx = chunk.x >> 4 // can confirm, they need to be shifted.
      const cz = chunk.z >> 4
      const path = this.currentPath
      if (path != null && path.length > this.currentIndex) {
        // Loading terrain beside the search frontier does not invalidate a
        // committed route through already loaded chunks. Restart only when
        // the refreshed column contains part of the remaining route.
        const touchesColumn = path.slice(this.currentIndex).some(move =>
          [move.entryPos, move.exitPos, ...move.toBreak.map(block => block.vec), ...move.toPlace.map(block => block.vec)]
            .some(pos => (Math.floor(pos.x) >> 4) === cx && (Math.floor(pos.z) >> 4) === cz))
        if (!touchesColumn) return
      }
      if (
        astarContext.visitedChunks.has(`${cx},${cz}`) ||
        astarContext.visitedChunks.has(`${cx - 1},${cz}`) ||
        astarContext.visitedChunks.has(`${cx},${cz - 1}`) ||
        astarContext.visitedChunks.has(`${cx + 1},${cz}`) ||
        astarContext.visitedChunks.has(`${cx},${cz + 1}`)
      ) {
        log('Chunk column loaded near path, resetting...')
        void this.reset('chunkLoad').catch(() => {})
      }
    }
    this.bot.on('chunkColumnLoad', onChunkLoad)
    const onEnd = (): void => { void this.destroy().catch(() => {}) }
    this.bot.once('end', onEnd)
    this.disposeListeners.push(() => {
      this.bot.off('chunkColumnLoad', onChunkLoad)
      this.bot.off('end', onEnd)
    })
  }

  public updateMatchesWanted (block: Block | null, path: Move[] | undefined = this.currentPath): boolean {
    const currentIndex = this.currentIndex
    log(`block: ${block?.name} pos: ${block?.position}, path: ${path?.length}, index: ${currentIndex}`)
    if (block == null || path == null) return false
    if (this.currentExecutor instanceof WaterDropExecutor && this.currentExecutor.acceptsWorldUpdate(block.position, block.name)) return true

    const pos = block.position.floored()
    // Server updates may settle after several fast excavation steps.
    // Accept the committed route's own changes even behind the player.
    for (let i = 0; i < path.length; i++) {
      const move = path[i]
      for (const place of move.toPlace) {
        if (place.vec.equals(pos)) {
          switch (place.type) {
            case 'solid':
              return block.boundingBox === 'block'
            case 'water':
              return BlockInfo.waters.has(block.type)
            case 'replaceable':
              return BlockInfo.replaceables.has(block.type)
          }
        }
      }

      for (const br of move.toBreak) {
        log(`[debug] check break position: ${br.vec}, ${pos}, ${block.boundingBox}`)
        if (br.vec.equals(pos)) {
          return block.boundingBox === 'empty' && !BlockInfo.liquids.has(block.type)
        }
      }
    }

    return block.boundingBox === 'empty' && (block.name === 'wall_torch' || block.name === 'torch')
  }

  isPositionNearPath (pos: Vec3 | undefined, path: Move[] | undefined = this.currentPath): boolean {
    if (pos == null || path == null) return false

    for (let i = this.currentIndex; i < path.length; i++) {
      const move = path[i]
      let comparisonPoint: Vec3 | null = null

      comparisonPoint = closestPointOnLineSegment(pos, move.entryPos, move.exitPos)

      const dx = Math.abs(comparisonPoint.x - pos.x - 0.5)
      const dy = Math.abs(comparisonPoint.y - pos.y - 0.5)
      const dz = Math.abs(comparisonPoint.z - pos.z - 0.5)

      if (dx <= 1 && dy <= 2 && dz <= 1) {
        return true
      }
    }

    return false
  }

  private registerAll (
    goal: goals.GoalDynamic,
    opts: { onHasUpdate?: () => void, onInvalid?: () => void, onCleanup?: () => void, forAll?: () => void }
  ): () => void {
    const boundEvent = goal._hasChanged.bind(goal)
    const boundValid = goal.isValid.bind(goal)

    const fuckEvent: Array<[keyof BotEvents, (...args: Parameters<BotEvents[keyof BotEvents]>) => void]> = []
    const fuckValid: Array<[keyof BotEvents, (...args: Parameters<BotEvents[keyof BotEvents]>) => void]> = []

    const newOnHasUpdate = (): void => {
      if (opts.onHasUpdate != null) opts.onHasUpdate()
      if (opts.forAll != null) opts.forAll()
      for (const [key, val] of fuckEvent) {
        this.bot.off(key, val)
      }
    }
    const newOnInvalid = (): void => {
      if (opts.onInvalid != null) opts.onInvalid()
      if (opts.forAll != null) opts.forAll()
      for (const [key, val] of fuckValid) {
        this.bot.off(key, val)
      }
      for (const [key, val] of fuckEvent) {
        this.bot.off(key, val)
      }
    }

    const cleanup = (): void => {
      if (opts.onCleanup != null) opts.onCleanup()
      if (opts.forAll != null) opts.forAll()
      for (const [key, val] of fuckValid) {
        this.bot.off(key, val)
      }
      for (const [key, val] of fuckEvent) {
        this.bot.off(key, val)
      }
    }

    for (const key of goal._eventKeys) {
      const listener = (...args: Parameters<BotEvents[keyof BotEvents]>): void => {
        if (this.resetReason === 'goalReassignment') return cleanup()
        if (boundEvent(key, ...args)) newOnHasUpdate()
      }
      this.bot.on(key, listener)
      fuckEvent.push([key, listener])
    }

    for (const key of goal._validKeys) {
      const listener1 = (...args: Parameters<BotEvents[keyof BotEvents]>): void => {
        if ((this.resetReason === 'goalReassignment')) return cleanup()
        if (!boundValid(key, ...args)) newOnInvalid()
      }
      this.bot.on(key, listener1)
      fuckValid.push([key, listener1])
    }

    goal.cleanup = cleanup

    return cleanup
  }

  getPathTo (goal: goals.Goal, settings = this.defaultMoveSettings, searchScale = 1, routeOpts: RouteOpts = {}): PathGenerator {
    const { movements } = this.activeMappings
    return this.getPathFromTo(this.bot.entity.position, this.bot.entity.velocity, goal, settings, movements, searchScale, routeOpts)
  }

  async * getPathFromTo (
    startPos: Vec3,
    startVel: Vec3,
    goal: goals.Goal,
    settings = this.defaultMoveSettings,
    movements = this.activeMappings.movements,
    searchScale = 1,
    routeOpts: RouteOpts = {}
  ): PathGenerator {
    this.abortCalculation = false
    this.clearResetReason()

    const actualStartPos = getNormalizedPos(this.bot, startPos).clone()
    startPos = getSupportedStartPos(this.world, actualStartPos)
    log('Generating path from %O to %O', startPos, goal)

    const startMove = new Move(
      startPos.x, startPos.y, startPos.z, [], [], getScaffoldCount(this.bot), 0,
      new IdleMovement(this.bot, this.world), actualStartPos, startVel.clone(),
      actualStartPos.clone(), startVel.clone()
    )

    this.executionRunner.setCurrentMove(startMove)
    this.executionRunner.setCurrentExecutor(new IdleMovementExecutor(this.bot, this.world, this.defaultMoveSettings))

    this.bot.pathingUtil.refresh()

    const positionedGoal = goal instanceof goals.GoalBlock || goal instanceof goals.GoalNear || goal instanceof goals.GoalFollowEntity
    const destinationSupport = positionedGoal ? new Vec3(Math.floor(goal.x), Math.floor(goal.y - 0.01), Math.floor(goal.z)) : undefined
    const supportInfo = destinationSupport == null ? undefined : this.world.getBlockInfo(destinationSupport)
    // Keep the destination's existing floor. Excavating a staircase through
    // it can remove the owner's footing and make the final goal unreachable.
    const protectedSettings = destinationSupport != null && supportInfo?.physical && positionedGoal && Math.abs(supportInfo.height - goal.y) < 0.2
      ? { ...settings, exclusionAreasBreak: [...settings.exclusionAreasBreak,
          (block: BlockInfo) => block.position.equals(destinationSupport) ? Infinity : 0] }
      : settings
    const routeSettings = this.rejectedPlacements.size > 0
      ? { ...protectedSettings, exclusionAreasPlace: [...protectedSettings.exclusionAreasPlace,
          (block: BlockInfo) => this.rejectedPlacements.has(block.position.toString()) ? Infinity : 0] }
      : protectedSettings

    const elevatedGoal = positionedGoal && goal.y >= startPos.y + 4
    const target = positionedGoal ? new Vec3(goal.x, goal.y, goal.z) : undefined
    const horizontalDistance = target == null ? Infinity : startPos.xzDistanceTo(target)
    let needsBridge = false
    if (target != null && target.y >= startPos.y - settings.maxDropDown && horizontalDistance > 1) {
      // Look beyond the current landing, including small platforms where the
      // bot is not yet standing at the rim. Preserve verified ice approaches.
      for (let step = 0; step <= Math.min(64, Math.ceil(horizontalDistance)); step++) {
        const t = step / Math.ceil(horizontalDistance)
        const floor = this.world.getBlockInfo(new Vec3(startPos.x + (target.x - startPos.x) * t,
          startPos.y - 0.01, startPos.z + (target.z - startPos.z) * t))
        if (isIceBlock(floor.block?.name)) break
        if (floor.isInvalid || floor.liquid) break
        if (!floor.physical) { needsBridge = true; break }
      }
    }
    const constructionCandidate = target != null && !settings.allowExcavatedDescent && settings.canPlace &&
      startMove.remainingBlocks > 0 && (elevatedGoal || needsBridge) && horizontalDistance <= 64 &&
      !this.world.getBlockInfo(startPos).liquid && !this.world.getBlockInfo(target).isInvalid &&
      !this.world.getBlockInfo(target).liquid
    const constructionMoves = new Map([...movements].filter(([provider]) =>
      [IdleMovement, Forward, Diagonal, ForwardJump, ForwardDropDown, StraightUp, Climb,
        ParkourForward, ParkourDiagonal, NeoProvider, LadderForward, LadderDiagonal,
        LadderLandingForward, LadderLandingDiagonal, AroundCornerDiagonal].includes(provider as any)))
    const preferExistingTerrain = routeOpts.preferExistingTerrain === true && (settings.canDig || settings.canPlace)
    const traversalSettings = { ...routeSettings, canDig: false, canPlace: false,
      allowWaterDrop: preferExistingTerrain && settings.allowWaterDrop, allowBucketWaterDrop: false,
      infiniteLiquidDropdownDistance: preferExistingTerrain && settings.infiniteLiquidDropdownDistance }
    const probe = async (probeGoal: goals.Goal, probeSettings: MovementOptions, probeMovements: ExecutorMap,
      timeoutMs: number, maxVisitedNodes: number, probeStart = startMove): Promise<ReturnType<ContinuousPathProducer['advance']>> => {
      const producer = new ContinuousPathProducer(probeStart, probeGoal, probeSettings, this.bot, this.world,
        probeMovements, searchScale, { timeoutMs: Math.min(timeoutMs, this.pathfinderSettings.searchTimeoutMs * searchScale),
          maxVisitedNodes: Math.min(maxVisitedNodes, this.pathfinderSettings.maxVisitedNodes * searchScale) })
      this._currentProducer = producer
      let res
      do {
        res = producer.advance()
        if (this.abortCalculation || this.disposed) res.result.status = 'canceled'
        if (res.result.status !== 'partial') break
        await new Promise<void>(resolve => setImmediate(resolve))
      } while (true)
      return res
    }
    let triedMemory = false
    const rememberedPath = async (): Promise<ReturnType<ContinuousPathProducer['advance']> | undefined> => {
      if (triedMemory || this.traversalMemory.size < 8 || !this.traversalMemory.contains(startPos)) return
      const memoryTarget = target ?? (goal instanceof goals.GoalMiningApproach
        ? new Vec3(goal.position.x, goal.y, goal.position.z) : undefined)
      // Unknown, still enclosed ore has no remembered dry connection. Do not
      // spend a second walking budget on every new excavation segment.
      if (goal instanceof goals.GoalMiningApproach && memoryTarget != null && !this.traversalMemory.near(memoryTarget, 6)) return
      triedMemory = true
      const previousProducer = this._currentProducer
      const corridor = (destination: Vec3 | undefined): MovementOptions => ({ ...traversalSettings,
        exclusionAreasStep: [...traversalSettings.exclusionAreasStep, (block: BlockInfo) =>
          block.position.distanceTo(startPos) <= 4 ||
          (destination != null && block.position.distanceTo(destination) <= 6) ? 0 : this.traversalMemory.stepCost(block.position)] })
      // Prefer a complete ordinary route, then narrow a retry to known
      // passages. This prevents a broad cave from flooding the search before
      // it reaches the remembered stairs in the opposite direction.
      if (memoryTarget == null || this.traversalMemory.near(memoryTarget, 6)) {
        const known = await probe(goal, corridor(memoryTarget), movements, 500, 8000)
        if (known.result.status === 'success' || known.result.status === 'canceled') return known
      } else {
        // The owner can move away from the mine entrance. Rejoin the known
        // exit on the destination's level, then validate a fresh walking tail.
        const anchor = this.traversalMemory.levelAnchor(memoryTarget)
        if (anchor != null) {
          const known = await probe(goals.GoalBlock.fromVec(anchor), corridor(anchor), movements, 500, 8000)
          if (known.result.status === 'canceled') return known
          if (known.result.status === 'success' && known.result.path.length > 0) {
            const last = known.result.path[known.result.path.length - 1]
            const reconnectStart = new Move(last.x, last.y, last.z, [], [], last.remainingBlocks, 0,
              new IdleMovement(this.bot, this.world), last.exitPos.clone(), last.exitVel.clone(),
              last.exitPos.clone(), last.exitVel.clone(), last)
            const tail = await probe(goal, traversalSettings, movements, 300, 6000, reconnectStart)
            if (tail.result.status === 'canceled') return tail
            if (tail.result.status === 'success') {
              tail.result = { ...tail.result, path: [...known.result.path, ...tail.result.path],
                cost: known.result.cost + tail.result.cost,
                calcTime: known.result.calcTime + tail.result.calcTime }
              return tail
            }
          }
        }
      }
      this._currentProducer = previousProducer
    }
    if (preferExistingTerrain || (elevatedGoal && !settings.allowExcavatedDescent && settings.canDig) || constructionCandidate) {
      // Always try the complete enabled traversal repertoire before editing
      // terrain. Removing Neo/ladder providers here made a ready course appear
      // disconnected and sent the bot into bridge/tower construction instead.
      // Combat also probes ordinary ledges and detours. A search timeout is
      // not evidence that digging/building is necessary: retry traversal with
      // a larger budget instead of committing edits to a reachable battlefield.
      // Other callers keep their bounded dry probe without deep water scans.
      let existing = await probe(goal, traversalSettings, movements,
        preferExistingTerrain ? this.pathfinderSettings.searchTimeoutMs * searchScale : 300,
        preferExistingTerrain ? this.pathfinderSettings.maxVisitedNodes * searchScale : 6000)
      if (existing.result.status !== 'success' && existing.result.status !== 'canceled') existing = await rememberedPath() ?? existing
      if (existing.result.status === 'success' || existing.result.status === 'canceled' ||
          (preferExistingTerrain && existing.result.status !== 'noPath')) {
        if (existing.result.status === 'success') this.bot.emit('pathGenerated', existing.result)
        yield existing
        return existing
      }
    }
    if (constructionCandidate && target != null && positionedGoal) {
      // Price the missing supports as well as the rise. A walking heuristic
      // otherwise explores thousands of airborne stair/tower combinations at
      // every bridge end. Keep one connected plan through the final landing.
      const bridgeEstimate = (node: Move): number => {
        const distance = node.exitPos.xzDistanceTo(target)
        const steps = Math.ceil(distance)
        const seen = new Set<string>()
        let missing = 0
        for (let step = 1; step <= steps; step++) {
          const floorPos = new Vec3(node.exitPos.x + (target.x - node.exitPos.x) * step / steps,
            node.exitPos.y - 0.01, node.exitPos.z + (target.z - node.exitPos.z) * step / steps).floored()
          const key = floorPos.toString()
          if (seen.has(key)) continue
          seen.add(key)
          const floor = this.world.getBlockInfo(floorPos)
          if (!floor.physical || Math.abs(floor.height - node.exitPos.y) > 0.2) missing++
        }
        return missing * settings.placeCost
      }
      const constructionGoal: goals.Goal = {
        isEnd: node => goal.isEnd(node),
        heuristic: node => goal.heuristic(node) + 2 * (bridgeEstimate(node) +
          Math.max(0, goal.y - node.exitPos.y - 1) * settings.placeCost),
        distHeuristic: node => goal.distHeuristic(node),
        onFinish: executor => goal.onFinish(executor)
      }
      const dx = target.x - startPos.x; const dz = target.z - startPos.z
      const lengthSquared = dx * dx + dz * dz
      const constructionSettings = { ...routeSettings, canDig: false,
        exclusionAreasStep: [...routeSettings.exclusionAreasStep, (block: BlockInfo) => {
          const x = block.position.x + 0.5; const z = block.position.z + 0.5
          const t = lengthSquared === 0 ? 0 : Math.max(0, Math.min(1,
            ((x - startPos.x) * dx + (z - startPos.z) * dz) / lengthSquared))
          return Math.hypot(x - startPos.x - dx * t, z - startPos.z - dz * t) > 4 ||
            block.position.y < Math.min(startPos.y, Math.floor(goal.y)) ||
            block.position.y > Math.max(startPos.y, Math.ceil(goal.y)) + 1 ? Infinity : 0
        }] }
      const construction = await probe(constructionGoal, constructionSettings, constructionMoves, 200, 4000)
      if (construction.result.status === 'success' || construction.result.status === 'canceled') {
        if (construction.result.status === 'success') {
          // A missing first gap can make a complete read-only route impossible.
          // After repairing that gap, reconnect to the ready course before
          // accepting further towers around its Neo obstacles or ladders.
          const plan = construction.result.path
          const firstEdit = plan.findIndex(move => move.toPlace.length > 0)
          const firstTraverse = plan.findIndex((move, index) => index > firstEdit && move.toPlace.length === 0)
          if (firstEdit >= 0 && firstTraverse > firstEdit && plan.slice(firstTraverse).some(move => move.toPlace.length > 0)) {
            const constructionProducer = this._currentProducer
            const prefix = plan.slice(0, firstTraverse)
            const last = prefix[prefix.length - 1]
            const reconnectStart = new Move(last.x, last.y, last.z, [], [], last.remainingBlocks, 0,
              new IdleMovement(this.bot, this.world), last.exitPos.clone(), last.exitVel.clone(),
              last.exitPos.clone(), last.exitVel.clone(), last)
            const reconnect = await probe(goal, traversalSettings, movements, 300, 6000, reconnectStart)
            if (reconnect.result.status === 'success' || reconnect.result.status === 'canceled') {
              if (reconnect.result.status === 'success') {
                reconnect.result = { ...reconnect.result, path: [...prefix, ...reconnect.result.path],
                  cost: prefix.reduce((cost, move) => cost + move.cost, 0) + reconnect.result.cost,
                  calcTime: construction.result.calcTime + reconnect.result.calcTime }
                this.bot.emit('pathGenerated', reconnect.result)
              }
              yield reconnect
              return reconnect
            }
            this._currentProducer = constructionProducer
          }
        }
        if (construction.result.status === 'success') this.bot.emit('pathGenerated', construction.result)
        yield construction
        return construction
      }
    }

    const miningApproach = settings.canDig && goal instanceof goals.GoalMiningApproach
    const excavationDescent = miningApproach && settings.allowExcavatedDescent && goal.y <= startPos.y - 4
    let descentCost = 0
    if (miningApproach) {
      // Caves can shorten shallow, horizontal and upward mining approaches too.
      let existing = await probe(goal, traversalSettings, movements, 100, 2000)
      if (existing.result.status !== 'success' && existing.result.status !== 'canceled') existing = await rememberedPath() ?? existing
      if (existing.result.status === 'success' || existing.result.status === 'canceled') {
        if (existing.result.status === 'success') this.bot.emit('pathGenerated', existing.result)
        yield existing
        return existing
      }
    }
    if (excavationDescent) {
      const floor = this.world.getBlockInfo(startPos.offset(0, -0.05, 0)).block
      if (floor != null) {
        const digTicks = this.bot.pathingUtil.digCost(floor, { inWater: false, notOnGround: false }) / 50
        if (Number.isFinite(digTicks)) descentCost = digTicks * settings.digCost *
          Math.max(1, settings.excavationStairWidth) * settings.excavationStairHeight
      }
    }

    // Deep excavation makes every sideways tunnel a cheap alternative to
    // climbing. Prefer progress toward the exit instead of exhausting those
    // tunnels and committing a single stair on every search timeout. The
    // movement providers still validate all digging, supports and hazards.
    const excavationAscent = settings.canDig && !settings.allowExcavatedDescent &&
      (goal instanceof goals.GoalBlock || goal instanceof goals.GoalNear || goal instanceof goals.GoalFollowEntity) &&
      goal.y >= startPos.y + 4
    let nearbyClimb = false
    if (excavationAscent) {
      const feet = startPos.floored()
      for (let x = -3; x <= 3 && !nearbyClimb; x++) for (let z = -3; z <= 3 && !nearbyClimb; z++) {
        for (let y = 0; y <= 2; y++) if (this.world.getBlockInfo(feet.offset(x, y, z)).climbable) { nearbyClimb = true; break }
      }
    }
    const configuredWeight = this.pathfinderSettings.heuristicWeight
    const heuristicWeight = nearbyClimb || this.world.getBlockInfo(startPos).water ? 1 : excavationAscent ? 3
      : Number.isFinite(configuredWeight) ? Math.max(1, Math.min(3, configuredWeight)) : 1
    const searchGoal: goals.Goal = heuristicWeight !== 1 || descentCost > 0
      ? {
          isEnd: node => goal.isEnd(node),
          heuristic: node => (goal.heuristic(node) + (goal instanceof goals.GoalMiningApproach
            ? Math.max(0, node.exitPos.y - goal.y) * descentCost : 0)) * heuristicWeight,
          distHeuristic: node => goal.distHeuristic(node),
          onFinish: executor => goal.onFinish(executor)
        }
      : goal

    if (this.pathfinderSettings.partialPathProducer) {
      this._currentProducer = new PartialPathProducer(
        startMove,
        searchGoal,
        routeSettings,
        this.bot,
        this.world,
        movements,
        searchScale
      )
    } else {
      this._currentProducer = new ContinuousPathProducer(
        startMove,
        searchGoal,
        routeSettings,
        this.bot,
        this.world,
        movements,
        searchScale
      )
    }
    log('Path producer initialized: %s', this._currentProducer.constructor.name)

    let result, astarContext

    do {
      const res = this._currentProducer.advance()
      result = res.result
      astarContext = res.astarContext

      if (this.abortCalculation || this.disposed) result.status = 'canceled'

      if (!settings.canDig && !settings.canPlace && (result.status === 'noPath' || result.status === 'timeout')) {
        const known = await rememberedPath()
        if (known != null) { result = known.result; astarContext = known.astarContext }
      }

      if (result.status === 'success') {
        this.bot.emit('pathGenerated', result)
        MovementHandler.count = 0
        MovementHandler.totCount = 0
        log('Path generation successful. Length: %d', result.path.length)
        yield { result, astarContext }
        return { result, astarContext }
      }

      if (this.abortCalculation) {
        result.status = 'canceled'
        log('Path generation canceled.')
        yield { result, astarContext }
        return { result, astarContext }
      }

      yield { result, astarContext }

      if (result.status === 'partial' || result.status === 'partialSuccess') {
        await new Promise<void>(resolve => setImmediate(resolve))
      }
    } while (result.status === 'partial' || result.status === 'partialSuccess')

    log('Path generation ended with status: %s', result.status)
    return {
      result,
      astarContext
    }
  }

  async getPathFromToRaw (startPos: Vec3, startVel: Vec3, goal: goals.Goal): Promise<PathInfo | null> {
    for await (const res of this.getPathFromTo(startPos, startVel, goal)) {
      if (res.result.status !== 'success') {
        if (res.result.status === 'noPath' || res.result.status === 'timeout') return null
      } else {
        return res.result
      }
    }
    return null
  }

  async goto (goal: goals.Goal | null, performOpts: PerformOpts = {}): Promise<void> {
    log('goto called')
    if (this.disposed) throw new Error('Pathfinder has been destroyed.')
    if (goal == null) {
      await this.stop()
      return
    }

    const requestId = ++this.goalRequestId

    if (!this.executeTask.done) {
      log('Cancelling previous goto task to start new one.')
      await this.interrupt(this.defaultMoveSettings.movementTimeoutMs, true, 'goalReassignment')
      await this.executeTask.promise
      log('Cancelled other goal! Beginning new one: %O', goal)
    }
    if (requestId !== this.goalRequestId || this.disposed) return
    this.rejectedPlacements.clear()

    // Survival owns movement while eating or arresting an accidental fall.
    // A new command stays cancellable and starts from the recovered position.
    this.abortCalculation = false
    while (this.bot.launcherSurvival?.busy && requestId === this.goalRequestId && !this.disposed) {
      await this.waitForTick()
    }
    if (requestId !== this.goalRequestId || this.disposed) return

    this.cleanupClient()
    this.executeTask = new Task()
    this.currentGotoGoal = goal
    this.bot.emit('goalSet', goal)

    this._gotoMappings = this.snapshotMappings()

    let completed = false
    try {
      await this._goto(goal, performOpts, requestId)
      completed = requestId === this.goalRequestId && !this.abortCalculation && !this.disposed
    } finally {
      try {
        await this.cleanupAll(goal, this.currentExecutor, completed)
      } finally {
        delete this._gotoMappings
        this.executeTask.finish()
        this.cleanupClient()
      }
    }
  }

  /** Finish the SAME search while its committed excavation prefix is executed. */
  private prepareContinuation (prefix: Path, canceled: () => boolean): { take: () => Promise<Path | undefined>, stop: () => void } {
    let context = prefix.context
    const producer = this._currentProducer
    const committed = prefix.path.slice()
    let anchored = false
    let suffix: ContinuousPathProducer | undefined
    let stopped = false
    const stop = (): void => { stopped = true }
    // Expected digs are already represented in the search's virtual terrain.
    // Changes in terrain actually read by the search invalidate its nodes.
    // Unrelated farm, fluid and player updates must not discard the plan.
    const onBlock = (oldBlock: Block | null, block: Block | null): void => {
      if (oldBlock?.stateId === block?.stateId) return
      const changed = block ?? oldBlock
      if (changed == null || !context.movementProvider.readBlocks.has(`${changed.position.x}:${changed.position.y}:${changed.position.z}`)) return
      if (!this.updateMatchesWanted(block, committed)) stop()
    }
    const onColumn = (pos: Vec3): void => {
      const x = Math.floor(pos.x) >> 4; const z = Math.floor(pos.z) >> 4
      if ([[0, 0], [-1, 0], [1, 0], [0, -1], [0, 1]].some(([dx, dz]) => context.visitedChunks.has(`${x + dx},${z + dz}`))) stop()
    }
    this.bot.on('blockUpdate', onBlock)
    this.bot.on('chunkColumnLoad', onColumn)
    this.bot.on('chunkColumnUnload', onColumn)
    const invalid = (): boolean => stopped || canceled() || this.abortCalculation || this.resetReason != null || this._currentProducer !== producer
    const result = (async (): Promise<Path | undefined> => {
      try {
        while (!invalid()) {
          await new Promise<void>(resolve => setImmediate(resolve))
          if (invalid()) return
          const advanced = suffix?.advance()
          if (advanced != null) context = advanced.astarContext
          const next = advanced?.result ?? context.compute()
          if (next.status === 'partial') continue
          // A better branch may diverge from the steps already executed. Never
          // splice it by coordinates alone: its digs and supports may differ.
          if (!['success', 'timeout', 'noPath'].includes(next.status)) return
          if (!anchored && !committed.every((move, i) => next.path[i] === move)) {
            // The original tree found a cheaper branch behind our committed
            // digs. Plan from the segment's END while digging still runs,
            // carrying its virtual edits, instead of waiting then replanning
            // from the player after each broken block.
            const last = committed[committed.length - 1]
            const start = new Move(last.x, last.y, last.z, [], [], last.remainingBlocks, 0,
              new IdleMovement(this.bot, this.world), last.exitPos.clone(), new Vec3(0, 0, 0),
              last.exitPos.clone(), new Vec3(0, 0, 0), last)
            suffix = new ContinuousPathProducer(start, context.goal as goals.Goal, last.moveType.settings,
              this.bot, this.world, this.activeMappings.movements)
            anchored = true
            continue
          }
          const tail = anchored ? next.path : next.path.slice(committed.length)
          // Budget/frontier exhaustion does not erase already validated digs.
          // Execute that tail before starting a search in newly loaded terrain.
          if (next.status !== 'success' && tail.length < 4) return
          return { ...next, path: tail }
        }
      } catch {
        // Execution owns recovery; an abandoned lookahead must not stop it.
        return undefined
      }
    })()
    return {
      take: async () => { const path = await result; return invalid() ? undefined : path },
      stop: () => {
        stop()
        this.bot.off('blockUpdate', onBlock)
        this.bot.off('chunkColumnLoad', onColumn)
        this.bot.off('chunkColumnUnload', onColumn)
      }
    }
  }

  private async _goto (goal: goals.Goal, performOpts: PerformOpts = {}, requestId = this.goalRequestId): Promise<void> {
    const canceled = (): boolean => requestId !== this.goalRequestId || this.disposed || this.resetReason === 'goalReassignment'
    const dynamic = goal instanceof goals.GoalDynamic && goal.dynamic
    const doForever = dynamic && goal.neverfinish
    let shore: goals.Goal | undefined
    let continuation: Path | undefined
    let failures = 0
    let waitingAtGoal = false
    const rejectedShores: goals.Goal[] = []
    let shoreRetryAt = 0
    const prefixVisits = new Map<string, number>()
    while (!canceled()) {
      await this.pendingReset
      if (canceled()) return
      if (performance.now() >= shoreRetryAt) rejectedShores.length = 0
      if (dynamic) goal.update()
      let toWaitOn = new Promise<void>(() => {})
      let cleanup = (): void => {}
      if (dynamic) {
        toWaitOn = new Promise<void>((resolve) => {
          cleanup = this.registerAll(goal, {
            onHasUpdate: () => {
              shore = undefined
              continuation = undefined
              prefixVisits.clear()
              rejectedShores.length = 0
              // A rebound's ice contact is still part of the committed flight.
              if (!(goal instanceof goals.GoalFollowEntity) ||
                  ((this.bot.entity.onGround || (this.bot.entity as any).isInWater) && this.currentExecutor?.canInterrupt !== false)) {
                void this.reset('goalUpdated').catch(() => {})
              }
            },
            onInvalid: () => { void this.cancel().catch(() => {}) },
            forAll: resolve
          })
          this.wakeGoal = cleanup
        })
      }

      try {
        const pos = this.bot.entity.position
        if (doForever && goal.isEnd({ x: pos.x, y: pos.y, z: pos.z, exitPos: pos } as Move) &&
            (this.bot.entity.onGround || (this.bot.entity as any).isInWater || this.world.getBlockInfo(pos).climbable)) {
          failures = 0
          if (!waitingAtGoal) {
            await this.cleanupBot()
            if (this.world.getBlockInfo(pos).climbable) this.bot.setControlState('sneak', true)
          }
          waitingAtGoal = true
          await this.waitForRetry(500, toWaitOn)
          continue
        }
        waitingAtGoal = false
        // Keep the same exits across partial routes and movement recovery.
        // Re-scanning around every new position can send a swimmer back and
        // forth between different banks without ever reaching dry ground.
        shore ??= await findShoreGoal(this.bot, this.world, goal, () => this.abortCalculation || this.disposed, rejectedShores)
        if (canceled()) return
        const routingGoal = shore ?? goal
        let path: Path | undefined
        if (continuation != null) {
          const first = continuation.path[0]
          const last = continuation.path[continuation.path.length - 1]
          // A moving follow target may have changed without an entity event.
          // Reuse only when we actually landed at this plan's starting bank
          // and its final node still satisfies the current destination.
          if (this.bot.entity.onGround && first != null && last != null &&
              (goal.isEnd(last) || continuation.status !== 'success') &&
              Math.abs(pos.y - first.entryPos.y) < 0.2 && pos.xzDistanceTo(first.entryPos) < 0.8) path = continuation
          continuation = undefined
        }
        let executionGoal = routingGoal
        let prefix = path != null && path.status !== 'success'
        if (prefix && path != null) executionGoal = goals.GoalBlock.fromVec(path.path[path.path.length - 1].exitPos)
        let unverifiedIceTakeoff = false
        const searchOrigin = pos.clone()
        const searchStarted = performance.now()
        if (path != null) this.bot.emit('pathGenerated', path)
        else for await (const res of this.getPathTo(routingGoal, this.defaultMoveSettings, Math.min(3, failures + 1), performOpts)) {
          if (canceled()) return
          if (res.result.status === 'success') path = res.result
          const opts = this.pathfinderSettings
          const miningPrefix = performOpts.allowMiningPrefix === true
          const swimmingPrefix = this.world.getBlockInfo(searchOrigin).water
          const distantGoal = !swimmingPrefix && shore == null &&
            (routingGoal instanceof goals.GoalBlock || routingGoal instanceof goals.GoalNear || routingGoal instanceof goals.GoalFollowEntity) &&
            (searchOrigin.distanceTo(new Vec3(routingGoal.x, routingGoal.y, routingGoal.z)) >= 48 ||
              this.world.getBlockInfo(new Vec3(routingGoal.x, routingGoal.y, routingGoal.z)).isInvalid)
          const exhausted = res.result.status === 'noPath' || res.result.status === 'timeout'
          const frontier = res.result.path[res.result.path.length - 1]
          const reachesFrontier = distantGoal && frontier != null && Movement.cardinalDirs.some(dir => {
            const next = frontier.cachedVec.plus(dir)
            return this.world.getBlockInfo(next).isInvalid &&
              routingGoal.heuristic({ ...frontier, x: next.x, y: next.y, z: next.z, exitPos: next } as Move) < routingGoal.heuristic(frontier)
          })
          const minimumPrefix = miningPrefix ? Math.max(1, Math.min(4, opts.routePrefixLength)) : distantGoal ? (exhausted || reachesFrontier ? 16 : 32) : 5
          if ((miningPrefix || swimmingPrefix || distantGoal) &&
              (res.result.status === 'partial' || (exhausted && (miningPrefix || distantGoal))) && opts.routePrefixMs > 0 &&
              (exhausted || performance.now() - searchStarted >= opts.routePrefixMs) && res.result.path.length >= minimumPrefix) {
            let moves = res.result.path.slice(0, distantGoal ? Math.max(48, opts.routePrefixLength) : opts.routePrefixLength)
            // Gathering opts into a bounded excavation segment. Retain all
            // of its validated steps rather than searching after every dig.
            // Walking callers stop before uncommitted digging; distant routes
            // wait for a long section or the loaded frontier, not five steps.
            const firstDig = moves.findIndex(move => move.toBreak.length > 0)
            if (!miningPrefix && firstDig >= 0) moves = moves.slice(0, firstDig)
            if (moves.length < minimumPrefix) {
              if (!exhausted) continue
            } else prefixCandidate: {
              const last = moves[moves.length - 1]
              if ((prefixVisits.get(last.hash) ?? 0) >= 2) break prefixCandidate
              // Stopping a walking prefix on the ice consumes the run-up before
              // we know whether the search can reach the opposite platform.
              const iceRim = Movement.cardinalDirs.some(dir => {
                let rim = last.exitPos
                for (let distance = 0; distance <= 6; distance++) {
                  const next = rim.plus(dir)
                  if (!this.world.getBlockInfo(next.offset(0, -1, 0)).physical) {
                    return isIceBlock(this.world.getBlockInfo(rim.offset(0, -1, 0)).block?.name) &&
                      routingGoal.heuristic({ ...last, exitPos: next, x: Math.floor(next.x), y: Math.floor(next.y), z: Math.floor(next.z) } as Move) < routingGoal.heuristic(last)
                  }
                  if (![0, 1].every(y => this.world.getBlockInfo(next.offset(0, y, 0)).walkthrough)) break
                  rim = next
                }
                return false
              })
              if (iceRim) { unverifiedIceTakeoff = true; break prefixCandidate }
              const elevatedGoal = shore == null &&
                (goal instanceof goals.GoalBlock || goal instanceof goals.GoalNear || goal instanceof goals.GoalFollowEntity) &&
                goal.y > last.exitPos.y + 0.5 && !this.world.getBlockInfo(new Vec3(goal.x, goal.y, goal.z)).water
              // A partial search may get horizontally closer to a bridge by
              // abandoning the shore, without finding any way back up. Executing
              // that prefix repeats the water/shore loop. Wait for a full route
              // or a prefix that keeps a dry foothold. Compare against the end
              // of the prefix, including when the bridge starts at our height.
              const losesFoothold = elevatedGoal &&
                (last.metadata?.waterLanding === true || this.world.getBlockInfo(last.exitPos).water)
              const prefixStart = miningPrefix
                ? { ...last, exitPos: searchOrigin, x: Math.floor(searchOrigin.x), y: Math.floor(searchOrigin.y), z: Math.floor(searchOrigin.z) } as Move
                : moves[0]
              if (!losesFoothold && routingGoal.heuristic(last) < routingGoal.heuristic(prefixStart) - (miningPrefix ? 0.5 : 2)) {
                path = { ...res.result, path: moves }
                executionGoal = goals.GoalBlock.fromVec(last.exitPos)
                prefix = true
                this.bot.emit('pathGenerated', path)
                break
              }
            }
          }
          if (res.result.status === 'noPath' || res.result.status === 'timeout') {
            // A short, costly climb can be the only way off a shore ledge.
            // Waiting for an entire high mountain route on every retry drops
            // that climb forever. Commit one supported rise, then search from
            // the new height with the original destination and fresh inventory.
            if (res.result.status === 'timeout' && opts.routePrefixMs > 0 && shore == null &&
                this.bot.entity.onGround && !this.world.getBlockInfo(searchOrigin).liquid &&
                (goal instanceof goals.GoalBlock || goal instanceof goals.GoalNear || goal instanceof goals.GoalFollowEntity) &&
                goal.y > searchOrigin.y + 0.5 && !this.world.getBlockInfo(new Vec3(goal.x, goal.y, goal.z)).water) {
              const moves = selectAscentPrefix(res.result, this.world, goal, searchOrigin, opts.routePrefixLength, prefixVisits)
              if (moves != null) {
                path = { ...res.result, path: moves }
                executionGoal = goals.GoalBlock.fromVec(moves[moves.length - 1].exitPos)
                prefix = true
                this.bot.emit('pathGenerated', path)
                break
              }
            }
            if (unverifiedIceTakeoff) throw new Error(`Pathfinding failed: ${res.result.status}; no verified route beyond the ice with the available runway and speed`)
            throw new NavigationError(res.result.status, `Pathfinding failed: ${res.result.status}`)
          }
          if (res.result.status === 'canceled') break
        }

        if (canceled()) {
          if (performOpts.errorOnAbort) throw new Error('Goto: Goal was canceled.')
          return
        }
        if (this.resetReason != null) {
          if (performOpts.errorOnReset) throw new Error(`Goto reset: ${this.resetReason}`)
          await this.cleanupBot()
          continue
        }
        if (path == null) throw new Error('Pathfinding ended without a path.')

        if (!prefix && shore == null && goal instanceof goals.GoalFollowEntity &&
            goal.isEnd === goals.GoalFollowEntity.prototype.isEnd) {
          executionGoal = new goals.GoalNear(goal.x, goal.y, goal.z, Math.sqrt(goal.sqDist))
        }
        const last = path.path[path.path.length - 1]
        // Land at the bank's planned takeoff, not merely the edge of its
        // composite goal cell, so the saved dry route can be reused directly.
        if (!prefix && shore != null && last != null) executionGoal = goals.GoalBlock.fromVec(last.exitPos)
        const continueSwimming = (): boolean => prefix && this.resetReason == null && !this.disposed &&
          last != null && last.toPlace.length === 0 && last.toBreak.length === 0 &&
          /^(Forward|Diagonal)$/.test(last.moveType.constructor.name) &&
          this.world.getBlockInfo(last.exitPos).water && canContinueSwimming(this.bot)
        // Keep water's continuous sprint strokes intact. Excavation spends
        // time breaking blocks: use that time to finish its existing search,
        // instead of discarding the open set and searching after each block.
        const lookahead = prefix && path.status === 'partial' && shore == null && !this.world.getBlockInfo(searchOrigin).water
          ? this.prepareContinuation(path, canceled) : undefined
        try {
          await this.perform(path, executionGoal, 0, continueSwimming)
          if (lookahead != null && !canceled() && this.resetReason == null) continuation = await lookahead.take()
        } finally {
          lookahead?.stop()
        }
        await this.pendingReset
        if (canceled()) return
        if (this.resetReason != null) {
          if (this.resetReason === 'goalReassignment') return
          if (performOpts.errorOnReset) throw new Error(`Goto reset: ${this.resetReason}`)
          await this.cleanupBot()
          continue
        }
        await this.cleanupBot(false, continueSwimming())
        const arrived = this.bot.entity.position
        const actual = { ...path.path[path.path.length - 1], x: Math.floor(arrived.x), y: Math.floor(arrived.y + 1e-4),
          z: Math.floor(arrived.z), exitPos: arrived } as Move
        // A time-sliced water prefix can already end on the selected bank.
        // Complete that shore goal now instead of searching an empty dry path
        // before handing control to its verified continuation.
        if (prefix && !(shore != null && this.bot.entity.onGround && routingGoal.isEnd(actual))) {
          prefixVisits.set(last.hash, (prefixVisits.get(last.hash) ?? 0) + 1)
          if (prefixVisits.size > 32) prefixVisits.delete(prefixVisits.keys().next().value!)
          continue
        }
        if (!(routingGoal instanceof goals.GoalFollowEntity) && !routingGoal.isEnd(actual)) {
          throw new NavigationError('recovery', 'Movement ended before reaching the route goal.')
        }
        if (shore != null) {
          if (shore instanceof ShoreRouteGoal) continuation = shore.continuation
          shore = undefined
          continue
        }
        if (goal instanceof goals.GoalFollowEntity) {
          goal.update()
          if (!goal.isEnd(actual)) continue
        }
        if (!doForever) return
        if (this.world.getBlockInfo(this.bot.entity.position).climbable) this.bot.setControlState('sneak', true)
        failures = 0
        waitingAtGoal = true
        await this.waitForRetry(500, toWaitOn)
        if (this.resetReason === 'goalReassignment' || this.disposed) return
      } catch (error) {
        await this.pendingReset
        if (canceled()) return
        if (!(error instanceof NavigationError) || performOpts.errorOnReset || (!doForever && failures >= 2)) throw error
        failures++
        if (shore != null && error.reason === 'noPath') {
          // A usable ascent is still useless when its bank cannot be reached
          // from this water basin. Try the other exits before revisiting it.
          rejectedShores.push(shore)
          shoreRetryAt = performance.now() + 8000
          shore = undefined
        }
        await this.cleanupBot()
        // A stopped follow task never hears about the next terrain/target
        // change. Keep it alive, with a bounded backoff and cancellable waits.
        await this.waitForRetry(doForever ? Math.min(3000, 250 * 2 ** Math.min(failures - 1, 4)) : 100, toWaitOn)
      } finally {
        cleanup()
        delete this.wakeGoal
      }
    }
  }

  async perform (path: Path, goal: goals.Goal, entry = 0, continueSwimming?: () => boolean): Promise<void> {
    return await this.executionRunner.perform(path, goal, entry, continueSwimming)
  }

  async recovery (move: Move, path: Path, goal: goals.Goal, entry = 0): Promise<void> {
    return await this.executionRunner.recovery(move, path, goal, entry)
  }

  async cleanupBot (forceSafety = false, keepControls = false): Promise<void> {
    if (!keepControls) {
      this.bot.clearControlStates()
      if (this.bot.entity.onGround && !this.world.getBlockInfo(this.bot.entity.position).water) {
        this.bot.setControlState('sneak', needsWalkSneak(this.world, this.bot.entity.position, this.bot.entity.velocity))
      }
    }

    // rough code. just need any of them.

    let exec
    for (const [, executor] of this.activeMappings.movements) {
      exec ??= executor
      executor.reset()
    }

    if (forceSafety && exec != null) {
      if (this.abortCalculation || this.disposed) return
      if (this.world.getBlockInfo(this.bot.entity.position).climbable) {
        this.bot.setControlState('sneak', true)
        return
      }
      const safetyDeadline = performance.now() + this.defaultMoveSettings.movementTimeoutMs
      let normVel
      do {
        normVel = this.bot.entity.onGround ? this.bot.entity.velocity.offset(0, -this.bot.entity.velocity.y, 0) : this.bot.entity.velocity
        const ectx = exec.simForward({ ticks: 2 })
        if (ectx.state.isInWater || ectx.state.isInLava) return
        if (this.bot.entity.onGround && !ectx.state.onGround && ectx.position.y < this.bot.entity.position.y) {
          this.bot.setControlState('sneak', true)
        }

        log(normVel, normVel.norm())
        await this.waitForTick()
      } while (!this.abortCalculation && !this.disposed && performance.now() < safetyDeadline && normVel.norm() > 5e-4)

      this.bot.setControlState('sneak', this.bot.entity.onGround &&
        needsWalkSneak(this.world, this.bot.entity.position, this.bot.entity.velocity))
    }
  }

  cleanupClient (): void {
    this.rejectedPlacements.clear()
    this.abortCalculation = false
    this.clearResetReason()
    delete this.currentGotoGoal
    this.currentPath = undefined
    this.currentExecutor = undefined
    this.currentMove = undefined
    this.executionRunner.setCurrentIndex(0)
    delete this._currentProducer
  }

  async cleanupAll (goal: goals.Goal, executor = this.currentExecutor, completed = true): Promise<void> {
    if (goal instanceof goals.GoalDynamic && goal.dynamic) {
      goal.cleanup?.()
    }

    await this.cleanupBot(true)

    if (executor != null && completed) {
      await goal.onFinish(executor)
    }
    this.world.cleanup?.()

    if (!completed) {
      log('Cleanup: Goal aborted.')
      this.bot.emit('goalAborted', goal)
    } else {
      log('Cleanup: Goal finished.')
      this.bot.emit('goalFinished', goal)
    }

    this.abortCalculation = false

    log('Task finished, cleanup client.')
  }
}

