    try {
      await rig.bot.pathfinder.goto(new goals.GoalBlock(1, 70, 0))
      assert.ok(rig.bot.entity.position.floored().equals(new Vec3(1, 70, 0)), `position=${rig.bot.entity.position}`)
      assert.equal(rig.bot.entity.onGround, true)
