            return changed === 'branch' ? { ...full, path: full.path.map(move => move.clone()) } : full
          }
          await rig.bot.waitForTicks(1)
          yield { ...result, result: { ...full, status: 'partial' as const, path: full.path.slice(0, 3) } }
