  let queried: number[] = []
  provider.getBlockInfo = (pos, dx, dy, dz) => {
    queried.push(Math.floor(pos.y) + dy)
    return cacheWorld.getBlockInfo(new Vec3(Math.floor(pos.x) + dx, Math.floor(pos.y) + dy, Math.floor(pos.z) + dz))
