    let swimTicks = 0, ticks = 0
    rig.bot.on('physicsTick', () => { ticks++; if (rig.bot.entity.swimming) swimTicks++ })
    t.signal.addEventListener('abort', () => { void rig.bot.pathfinder.stop() }, { once: true })
    try {
