const { EventEmitter } = require("node:events");
const { Vec3 } = require("vec3");
const { goals } = require("./pathfinder.cjs");
const { queueInventoryTask } = require("./combat-inventory.cjs");
const {
  integer,
  itemByName,
  planCraft,
  smeltingRecipe,
  fuelItems,
  inventoryItems,
  emptySlots,
} = require("./production-plan.cjs");
const { isStorage, discoverBlocks, inspectContents, assignStorage } = require("./storage-scan.cjs");

const STATIONS = new Set([
  "crafting_table",
  "furnace",
  "blast_furnace",
  "smoker",
  "anvil",
  "chipped_anvil",
  "damaged_anvil",
  "enchanting_table",
  "brewing_stand",
  "stonecutter",
  "smithing_table",
  "grindstone",
  "loom",
  "cartography_table",
  "chest",
  "trapped_chest",
  "ender_chest",
  "barrel",
  "hopper",
  "dispenser",
  "dropper",
  "shulker_box",
  "crafter",
]);
const supported = (name) => STATIONS.has(name) || /_shulker_box$/.test(name);
class Cancelled extends Error {
  constructor() {
    super("Работа остановлена");
  }
}

function createProductionController(bot, hooks = {}) {
  const {
    onStatus = () => {},
    onError = () => {},
    onStart = () => {},
    operationTimeoutMs = 20000,
    moveTimeoutMs = 60000,
    smeltTimeoutMs = 900000,
    pollMs = 250,
