    f.bot.entity.position.set(0.5, 64, 0.5);
    for (const patch of [
      { position: new Vec3(2, 64, 0.5) },
      { position: new Vec3(1, 66, 0.5) },
      { position: new Vec3(1, 64, 0.5), type: "projectile" },
