      pursuit = null;
      bot.launcherTravel?.stopChase();
      return false;
    }
    if (!allowed(target)) {
      const enemy = pursuit.enemy;
      const replacement = Object.values(bot.entities ?? {}).find(
        (entity) =>
          allowed(entity) &&
          (enemy.uuid ? entity.uuid === enemy.uuid : entity.username === enemy.username),
