      const returnPoint = bot.entity.position.clone();
      deliveryContext = { task, paused, reason, drops: [...trackedDrops], picked: [...picked] };
      restoreMovement();
      task = {
        id: nextId++,
        kind: "deliver",
        owner,
        returnPoint,
        mined: 0,
        collected: 0,
        deposited: 0,
        delivered: 0,
        failed: new Map(),
        scaffolds: new Map(),
