    world: {},
    defaultMoveSettings: {
      canDig: true,
      canPlace: true,
      allowSprinting: true,
      walkOnly: false,
      allowJumpSprint: true,
      allowLowCeilingJumps: true,
      maxDropDown: 3,
      exclusionAreasStep: [],
