});

test("fruit harvesting preserves stems and decorative pumpkins", async () => {
  const f = fixture();
  try {
    f.put("pumpkin", 1, 64);
    f.put("attached_pumpkin_stem", 2, 64);
    f.put("pumpkin", -2, 64);
    f.work.enqueue({ kind: "harvest", crop: "pumpkin" });
