    assert.equal(result.harvested, 1);
    assert.equal(result.planted, 0);
    assert.equal(f.bot.blockAt(new Vec3(2, 64, 0)).name, "attached_pumpkin_stem");
    assert.equal(f.bot.blockAt(new Vec3(-2, 64, 0)).name, "pumpkin");
