    get task() {
      return task;
    },
    async dispose() {
      disposed = true;
      bot.off("entityHurt", hurt);
      bot.off("entityDead", removed);
      bot.off("entitySwingArm", swing);
      bot.off("entityGone", removed);
      bot.off("entitySpawn", spawned);
