const { isDeepStrictEqual } = require("node:util");
const FILTERS = require("./storage-filters.json");
const categories = new Set(FILTERS.map((entry) => entry.name));
const materials = new Set([
  "coal",
  "iron",
  "copper",
  "gold",
  "redstone",
  "lapis",
  "diamond",
  "emerald",
  "quartz",
  "netherite",
]);
const timber =
