const woodItems = new Set([
  "stick",
  "ladder",
  "chest",
  "trapped_chest",
  "barrel",
  "crafting_table",
  "bookshelf",
  "chiseled_bookshelf",
  "lectern",
  "composter",
  "cartography_table",
  "fletching_table",
  "smithing_table",
  "loom",
  "note_block",
  "jukebox",
  "bowl",
  "charcoal",
