  const pick = f.item("iron_pickaxe");
  const torch = { ...f.item("torch"), count: 4 };
  f.items.push(pick);
  if (mode !== "empty") f.items.push(torch);
  for (const x of [2, 6, 10]) {
    f.put("iron_ore", x);
    f.put("stone", x - 1, 65, 2);
  }
  const wrappedDig = f.bot.dig;
