    ["redstone", "Редстоун · все руды", "redstone"], ["lapis", "Лазурит · все руды", "lapis_lazuli"],
    ["diamond", "Алмазы · все руды", "diamond"], ["emerald", "Изумруды · все руды", "emerald"],
    ["quartz", "Кварц · все руды", "quartz"],
