      return {
        slot,
        name: item.name,
        displayName: item.displayName || item.name,
        count: item.count,
        texture: item.texture || assets?.textureContent?.[item.name]?.texture || FALLBACK,
        durability: maximum ? Math.max(0, maximum - (item.durabilityUsed || 0)) : null,
        maxDurability: maximum || null,
